window.__D("text/torat-chaim/c021",{"p":[[2300540532,"רק אפס קצהו האחרון דרצון בא לגילוי ע\"כ הוא הנמשך לשכל וכן משכל למדות כו' (והן אותיות שנק' מראה שמראה בגילוי לבד על עצם הדבר ואינו נחשב מעצמו' הדבר כלל כו'). אבל יש אותיו' שנק' אותיו' עצמיי' שהן עצם הדבר ומהותו ממש והוא כאשר נתגלה עצם ומהות הרצון והתענוג או מהות השכל והמדות כו', והיינו תרגומו של אתא שבא הדבר כמו שהוא בעצם ממש כמו אדם הבא ממקום מרחק לביתו שאעפ\"י שלא נתחדש דבר בעצם מהותו שהרי הוא האדם שהי' במרחק ובא לכאן וכמו וזרח השמש<sup data-n=\"7103\">141</sup> שהי' בהעלם מתחת לארץ ובא לגילוי בזריחתו כמו השמש יצא על הארץ<sup data-n=\"7104\">142</sup> שיצא מהעלמו, אין זה כמו גילוי אותיו' הנ\"ל שהרי בא בעצם הדבר שהוא האדם כמו שהוא והשמש כמו שהיא ממש בעצמיו'<sup data-n=\"7105\">143</sup> הנפש כאשר באין הן עצמן ממש בקירוב בכלי המוח והלב כו', זהו ענין אותיו' העצמיי' שהוא ענין ביאת עצם הדבר כמו שהוא ממש מהעלם לגילוי שא\"א שיבא בדרך עו\"ע מרצון לשכל כו'. וכמו שאנו רואי' בחוש שכאשר נגלה בחי' פנימי' נקודת הרצון כמו שהוא ממש א\"א שבא מכלל טעם לרצון וכן מפנימי' השכל א\"א לבא במדות וכן מפנימי' המדות א\"א לבא במח' ודיבור כו' וד\"ל. ולפי\"ז כאשר בא גילוי אותיות העצמיי' מנפש עצמה שנק' יחידה ממילא יוכל להיות שינוי אותיות הרצון הקדום שבא בבחי' התגלות חיצונית אותיו' הנ\"ל, וכן מרצון לשכל כאשר בא לגילוי עצם נקודת הרצון יהופך הארת אותיו' חיצוני' דרצון בשכל וכן משכל למדות וממדות למח' ודו\"מ כו' וד\"ל.\n<b>והדוגמא</b> מכ\"ז יובן למעלה בשרש ענין קי\"ס שהי' בחי' הגילוי דעצמו' המאציל ממש כמו שהוא באמיתית עצמותו כמ\"ש זה אלי<sup data-n=\"7106\">144</sup> זה ממש, וע\"כ הי' ענין היפוך ים ליבשה שאם הי' רק כפי סדר ההשתלשלות דאותיו' חיצוני' הנ\"ל בעו\"ע דרצה\"ע (חכ' ומדו' כו') הרי לא הי' יכול להיות מים יבשה שהוא שינוי הצירוף דים ליבשה כו', אך מפני שהי' עליי' והתכללות דאותיו' דרצון למעלה בעצמות המאציל מצד בחי' גילוי עצמו' המאציל ממש כמו שמתבטל גילוי הרצון בעצמו' הנפש דיחידה כו' אז נמשך ובא מאותיות העצמיי' דעצמו' ממש שינוי צירוף חדש מפני שגם הוא נמשך מבחי' עצמותו ומהותו בחכ' וכן מחכ' למדו' כו' עד שיכול להיות שינוי חדש לעשות מים יבשה באותיו' דמו\"ד (להיות שהעלם עצמו' המח' נעשה בחי' גילוי מאחר שעצמיו' הרצון בא לגילוי מצד גילוי העצמי ממש וזהו עיקר ענין קי\"ס כו'). ובזה יובן בתוס' ביאור יותר ענין הרמה דמטה משה דהיינו להרים לאותיות דרצון וחכ' למעלה בעצמות שיומשך מבחי' עצמותו ממש בבחי' אותיות עצמיי' הנ\"ל בכדי לעשות שינוי צירוף דים ליבשה ממילא והוא מ\"ש",[["7103","141","<b>וזרח השמש</b>: קהלת א, ה."],["7104","142","<b>השמש יצא על הארץ</b>: וירא יט, כג."],["7105","143","<b>בעצמיו'</b>: אוצ\"ל: וכ\"ה באותיות."],["7106","144","<b>זה אלי</b>: בשלח טו, ב."]]],[2300540550,"ונטה את יד\"ך מלמעלה למטה אחר העלי' דרצון הקדום בעצמו' ממש לעשות מהעלם העצמו' דים ליבשה וד\"ל.\n<b>ובכל</b> הנ\"ל יובן מ\"ש הפך ים ליבשה בנהר יעברו ברגל כו' דהנה מובן מכל הנ\"ל דבקי\"ס הי' התגלות העצמו' דא\"ס ב\"ה ממש כמ\"ש זה אלי כו' כנ\"ל. והנה מבואר למעלה שרש ב' מיני השתלשלות יש מיש ויש מאין והוא ההפרש בין השכל ומדו' לבחי' נקודת הרצון שבלב הפנימי' שחפץ לחיות ולא למות כו' שזהו בחי' אין של היש דשכל ומדות כו' והשגות בגדולת ה' והמדות שנולדים מזה הם בבחי' לבושים שזהו מיש ליש כו'. והנה בשעת קי\"ס שהי' אז הגילוי מבחי' העצמו' ממש כנ\"ל שאינו נתפס רק בנקודת הלב שנק' רעותא דליבא בחי' האין ולא בשכל ומדות דלמת\"ב כו' כנ\"ל, א\"כ ודאי הי' בכנ\"י בשעת קי\"ס מבחי' נקודת הלב ובאתעדל\"ת ודאי אתעדל\"ע<sup data-n=\"7107\">145</sup> ג\"כ נתעורר למעלה מבחי' עצמו' אוא\"ס שבפנימי' רצה\"ע שלמעלה מבחי' הלבושים דחכ' ומדו' עליונו' שנק' בי\"ע דאצי' כו' שהן יש מאין ולא בחי' אין עצמו כו', ולכך אמר זה אלי ממש והיינו בשעה שעברו ישראל בתוך הים ביבשה שהי' אז גילוי אור העצמו' דא\"ס ב\"ה קבלו כנ\"י אור זה בנפשם עצמיו' ממש לדורות הבאים אחריהם עד ימות המשיח שיוכל כ\"א מישראל לקבל אור העצמו' דא\"ס ב\"ה, והוא במה שיוכל לבא להתפעלות נקודת הלב הפנימי לידבק ולהיכלל בעצמו' א\"ס דוקא שבזה הוא שורה דוקא, שבאמת זהו דבר פלא גדול מה שאנו רואים שיכול גם פחות הערך לעשות תשובה שלימה מקרב ולב עמוק עד שתכלה נפשו מנקודת הלב לאור עצמו' א\"ס ב\"ה, וכן יוכל כ\"א להתפעל באה\"ר בתענוגי' להתענג על ה' בכלות הנפש כמו כלה שארי ולבבי כו', ואין זה כ\"א מצד שכבר קבלו אבותינו בעברם בים ביבשה מאור העצמו' דא\"ס כשהפך ים ליבשה כמ\"ש זה אלי כו'. וראי' לזה שהרי קי\"ס הי' הכנה למ\"ת<sup data-n=\"7108\">146</sup> והיינו מה שבמ\"ת האיר פניו אליהם בי' הדברות שיהי' אור העצמו' ממש שוכן בהם ע\"י תו\"מ לדורות בבחי' שו\"ב כמו במס\"נ דרצוא הנ\"ל וד\"ל. וז\"ש הפך ים כו' שם נשמחה בו כו' והל\"ל שם שמחנו בו דקאי ארישא הפך ים כו' אלא מפני שהי' בקי\"ס עיקר גילוי אור העצמו' בנפשם האלקי' להיות הארה והמשכה זו בקביעות בנפשם לזרעם אחריהם לדורי דורות בכל צל ימינו עלי ארץ<sup data-n=\"7109\">147</sup> כו' ע\"כ א' שם נשמחה בו לשון להבא כלומר שתמיד נשמחה בו בשמחה שמצד העצמו' ממש כמו וישמחו בך<sup data-n=\"7110\">148</sup> ממש כו' שכ\"ז אינו רק מחמת השמחה בעצמו' בשעת קי\"ס כשאמר זה אלי כו' והוא שרש ומקור השמחה בעצמו' לדורי דורות וד\"ל.",[["7107","145","<b>ובאתעדל\"ת. . אתעדל\"ע</b>: נסמן לעיל פ' שמות מא, א."],["7108","146","<b>קי\"ס הי' הכנה למ\"ת</b>: ראה גם לעיל קלח, ג. לקמן קנח, א. קסח, ג. קעז, ג. קפא, ב. קצג, ג. רא, ד. מאמרי אדה\"א ויקרא ח\"א ע' קמז וש\"נ. שם ע' תכט. שה\"א לב, ב ובהערה 9."],["7109","147","<b>צל ימינו עלי ארץ</b>: איוב ח, ט."],["7110","148","<b>וישמחו בך</b>: נוסח תפלת העמידה ליו\"ט."]]],[2300540567,"<b>וז\"ש</b> ראתה שפחה על הים כו' דהנה מבואר למעלה בהפרש יתרון המעלה דנס דקי\"ס על כל הניסי' ונפלאות וגם על הנבואה שבא גילוי העלם אור העליון מבחי' עצמותו ממש שלא במדה ושיעור מצומצם כלל כו' וע\"כ ראתה שפחה כו' לרמז שאין גילוי אלקו' בקי\"ס הי' כשאר גילוי אלקו' גם בנביאים מן ההעלם לגילוי בסדר ומדריגה דהעלא' והמשכה דרוח אייתי רוח<sup data-n=\"7111\">149</sup> כו' והוא לפי הכנת המקבל והשגת אלקו' ומדות דאוי\"ר אלא רק מצד נקודה פנימי' הלב כו' שהכל שווים בזה, ולפי שהי' בקי\"ס גילוי אור העצמו' ממש שלא נתפס בלבושים דשכל ומדות כלל רק בנקודת הלב לבד וע\"כ א' זה אלי לנוכח וכמו לע\"ל שא' הנה אלקינו זה<sup data-n=\"7112\">150</sup> כו' וע\"כ גם השפחה ראתה גילוי אור זה בשוה עם הראשים שבישראל מה שלא ראה יחזקאל במראה הנבואה באמצעות ההכנה שלו באוי\"ר ושכל כו' שזהו בחי' ההשתלשלות מאין ליש ובקי\"ס הי' האור מלמעלה מעלה מן ההשתלשלות עד שההעלם עצמו נעשה בבחי' גילוי שא\"א שיבא זה האור בנביאי' שהוא מאין ליש כמ\"ש ביד הנביאי' אדמה<sup data-n=\"7113\">151</sup> כו' וד\"ל (ומ\"ש על נבואת יחזקאל דוקא<sup data-n=\"7114\">152</sup> לפי שהי' שרש נבואתו בנג\"ה דיצי'<sup data-n=\"7115\">153</sup> אחר העלם האור דבריאה ובקי\"ס הי' העלם האור דמח' דברי' בבחי' גילוי דיצי' כו' וד\"ל).\n<b>והנה</b> להבין לשון שם נשמחה בו<sup data-n=\"7116\">154</sup> מה ענין השמחה לכאן ומה שדקדק לומר שם נשמחה להבא כאשר יעברו ברגל והלא כבר הי' שמחה זו בשעת קי\"ס. אך הנה יש להקדים תחלה שרש ענין שמחה ש\"מ והוא מ\"ש תחת אשר לא עבדת<sup data-n=\"7117\">155</sup> כו' בשמחה ובטוב לבב וי\"ל מה שכפל הדבר שמחה וטוב לבב כמו וילכו לאהליהם שמחים וטובי לב<sup data-n=\"7118\">156</sup> כו' ומהו ענין טוב לבב אם הכוונה שהלב טוב הל\"ל בלב טוב או לב שלם כו', אך פי' טוב לבב הוא בחי' הטוב של הלב שהוא בחי' נקודת הלב הנ\"ל שלמעלה מן הלבושים וכלים דשכל ומדות כו' והיינו בחי' כלות הנפש בעצמו הנ\"ל אך א\"כ למה נק' טוב לבב דמשמעו ענין תענוג וטעם שיטיב לבבו בה' להתענג בטוב לבב ושמחה כו'. הענין הוא דודאי כל שתגדל יותר תשוקת נקודת הלב בכליון הנפש ועוצם הצמאון כמו נכספה וגם כלתה נפשי ממש כו' כמו\"כ לפ\"ע זה ממש תגדל יותר השמחה וטוב לבב אח\"כ כאשר משיג ומצא את שאהבה נפשו וכלתה אליו בתחלה להתענג בו ברוב שמחה וטוב לבב יותר והוא הנק' טוב לבב שלבו נעשה טוב עליו, כמו ותחי רוח יעקב<sup data-n=\"7119\">157</sup> מבשור' יוסף כו' וכמו בשורה טובה ונפלאה שהיתה נפשו כלתה אלי' ביותר והגיע אליו שנק' השבת נפשו ממש ברוח וחיות חדש ממש כו', וכמים קרים על נפש עייפה<sup data-n=\"7120\">158</sup> שמצד החום הגדול שעייפה נפשו עד שתכלה",[["7111","149","<b>דרוח אייתי רוח</b>: נסמן לעיל פ' וארא סג, ג."],["7112","150","<b>הנה אלקינו זה</b>: נסמן לקמן הערה 189."],["7113","151","<b>ביד הנביאי' אדמה</b>: נסמן לעיל פ' בא צט, ב. וראה גם לעיל הערה 25."],["7114","152","<b>נבואת יחזקאל דוקא</b>: ראה מאמרי אדה\"א ויקרא ח\"א ע' שכב. לקמן קצד, ב. פלח הרמון יתרו ע' רנד."],["7115","153","<b>יחזקאל. . נבואתו. . דיציר'</b>: נסמן לעיל פ' בא קיד, ג."],["7116","154","<b>שם נשמחה בו</b>: תהלים סו, ו."],["7117","155","<b>תחת אשר לא עבדת</b>: תבוא כח, מז."],["7118","156","<b>וילכו לאהליהם שמחים וטובי לב</b>: מלכים-א ח, סו."],["7119","157","<b>ותחי רוח יעקב</b>: ויגש מה, כז."],["7120","158","<b>וכמים קרים על נפש עייפה</b>: נסמן לעיל קמא, א."]]],[2300540583,"נפשו כן לפ\"ע זה תהי' תענוג השבת נפשו מן המים הקרים וכן בקיקיון דיונה<sup data-n=\"7121\">159</sup> שהי' החום השמש גובר ותך על ראשו ולפ\"ע זה שש ושמח בקיקיון כו' וכה\"ג נק' השבת הנפש במי שנפשו כלתה להשיג מעץ החיים והשיג וטעם שא' ע\"ז ע\"ח תאוה באה<sup data-n=\"7122\">160</sup> כו', וכן לענין טוב לבב מרוב כל בעבודת ה' שכל שתהי' תשוקת הנפש וצמאונה ביותר לאלקי' חיים בכלות הנפש בבחי' נקודת הלב כמו צמאה לך נפשי כמה לך בשרי כו' וכהנ\"ל בכל עת הכושר בתפלה, כן לפ\"ע זה ממש יגיל וישמח ויטיב לבבו בעבודה דמעשה המצות שזה כמו שמצא והשיג תאות לבו ושאהבה וכלתה נפשו ביותר והוא ענין גילוי עצמו' אא\"ס שברצה\"ע שבכל מעשה המצוה בעשותן שאל זה כלתה נפשו והנה מצאוהו בגילוי גמור, שהרי המצוה נק' מצות הוי'<sup data-n=\"7123\">161</sup> ממש כמו אשר קדשנו במצותיו<sup data-n=\"7124\">162</sup> ממש כידוע ובמצות ציצית הוא פרישו דמלכא<sup data-n=\"7125\">163</sup> שהוא מה שהי' מתעטף בטלית כמ\"ש עוטה אור כשלמה<sup data-n=\"7126\">164</sup> כו' וכן מצות תפילין שם הוי' נק' עליו<sup data-n=\"7127\">165</sup> ממש וכה\"ג בכל המצות שנק' ארחות הוי'<sup data-n=\"7128\">166</sup> ממש כמ\"ש דוד בפקודי' אביטה אורחותיך<sup data-n=\"7129\">167</sup> כו', וע\"כ צ\"ל עבודת ה' בשמחה וטוב לבב דוקא השמחה לפ\"ע התשוקה שהי' תחלה וטוב לבב על התיישב האור בתוכה אשר אהב נפשו כמו כאשר השיג תאות לבו שהוא בטוב לבב מאד כמו וילכו לאהליהם שמחי' וטובי לב מפני שנתיישב בהם האור המקיף דשמחה שבעצמו' ממש וד\"ל. ואם אין התשוקה בכלות הנפש בתפילה כ\"כ אין השמחה וטוב לבב בעבודה דמצוה כ\"כ משום דהא בהא תליא לפ\"ע דוקא כו'. וז\"ש מרוב כל<sup data-n=\"7130\">168</sup> מעצמו' אוא\"ס שבמצות שנק' רוב כל יותר מחיי העוה\"ב שנק' כל<sup data-n=\"7131\">169</sup> ויהי' השמחה וטוב לבב רק מרוב כל זה מפני שאין השמחה וטוב לבב כזה מכל מעלה ומדריגה זולתו שהרי נכלל בזה ממילא כל שמחה ותענוג שבחכ' גם בפנימי' רזין דרזין<sup data-n=\"7132\">170</sup> דאורייתא ונבואה ורוה\"ק שיש בכלל מאתים מנה<sup data-n=\"7133\">171</sup> כו' (וכמ\"ש בע\"ח שמטעם זה זכה האריז\"ל<sup data-n=\"7134\">172</sup> לרוה\"ק וג\"א רק מפני שהי' שמח בשמחה ש\"מ לבד שהוא השמחה שבעצמו' ממש שנק' רוב כל שנכלל בזה הכל כו'). ובזה יתורץ מ\"ש שם נשמחה בו דקאי על להבא לפי שהי' השמחה בקי\"ס בעצמותו ית' ממש כמ\"ש זה אלי כו' ונקבע שמחה זאת לדורות הבאים בכל עת מצוא בתפילה כשיבוקש וימצא תאוות נפשו בנקודת הלב בעבודה דתו\"מ וכן במועדים שישמחו בך ישראל מקדשי שמך (כמשי\"ת). וזהו ונשמחה בו, בו ממש, שנבדל ערך מעלת שמחה זו על כל תענוגי שמחה שבשכל והשגה גם בפנימי' דחכ'",[["7121","159","<b>בקיקיון דיונה</b>: יונה ד, ו ואילך."],["7122","160","<b>ע\"ח תאוה באה</b>: נסמן לעיל קמא, א."],["7123","161","<b>מצות הוי'</b>: ויקרא ד, ב. יג, כב."],["7124","162","<b>אשר קדשנו במצותיו</b>: נוסח ברכת המצות."],["7125","163","<b>ציצית הוא פרישו דמלכא</b>: נסמן לעיל קלח, א."],["7126","164","<b>עוטה אור כשלמה</b>: תהלים קד, ב."],["7127","165","<b>תפילין שם הוי' נק' עליו</b>: תבוא כח, י. ברכות ו, א."],["7128","166","<b>המצות שנק' ארחות הוי'</b>: נסמן לעיל פ' וארא סט, ד."],["7129","167","<b>בפקודי' אביטה אורחותיך</b>: תהלים קיט, טו [ושם: אשיחה ואביטה — ראה גם לקמן קסט, ד. מאמרי אדה\"א בראשית ע' מג וש\"נ. שע\"ת לב, ב ובהערה 8]."],["7130","168","<b>מרוב כל</b>: המשך הכתוב תחת אשר לא עבדת."],["7131","169","<b>העוה\"ב שנק' כל</b>: ראה מאמרי אדה\"ז תקס\"ד ע' כט. תקס\"ז ס\"ע סז ואילך. <a class=\"ft-cite\" href=\"#/read/torah-or/3901370363\" data-slug=\"torah-or\" data-id=\"3901370363\">תו\"א תצוה פא, ב</a>. לקמן פ' משפטים שב, א. תצוה שמג, ד."],["7132","170","<b>רזין דרזין</b>: ראה זהר בראשית מא, א."],["7133","171","<b>שיש בכלל מאתים מנה</b>: בבא קמא עד, א."],["7134","172","<b>וכמ\"ש בע\"ח. . זכה האריז\"ל</b>: נסמן לעיל פ' וארא נה, א."]]],[2300540599,"שאין לו ערך כלל לגבי מהו\"ע ית' וכמו אליו ולא למדותיו<sup data-n=\"7135\">173</sup> כו' וד\"ל.\n<b>אך</b> הנה עדיין יש להבין מ\"ש בנהר יעברו ברגל לשון עתיד וברישא א' הפך ים כו' לשון עבר ושם נשמחה בו משמע לעתיד דוקא ולפי הנ\"ל עיקר השמחה הי' בקי\"ס והל\"ל שם שמחנו כו'. אך הנה י\"ל במ\"ש וישובו ויחנו<sup data-n=\"7136\">174</sup> כו' מה זה שציווה ה' להם לחזור הדרך בכדי שירדופו אחריהם בים כו' ולפי הנ\"ל הי' זה רק כדי שיקבלו בנ\"י בחי' גילוי אור העצמו' דא\"ס ממש עד שיוקבע בנפשם לדורות כנ\"ל (וע\"י מ\"ת דוקא שהי' גילוי אור זה עצמו בבחי' שוב בתו\"מ כנ\"ל), וז\"ש בנהר יעברו ברגל כו' דהנה כתיב עד יעבור עמך הוי'<sup data-n=\"7137\">175</sup> עד יעבור כו' שיהי' העברה שני' בנהר פרת לע\"ל דכתיב והניף ידו על הנהר והכהו לשבע<sup data-n=\"7138\">176</sup> נחלים והדריך בנעלים כו' והיתה למסילה<sup data-n=\"7139\">177</sup> לשאר עמו אשר ישאר כו' שהוא קיבוץ גליות בימוהמ\"ש לבהמ\"ק דלע\"ל, וכדוגמא זו הי' גם גילוי שכינה בהיכל ק\"ק בזמן בית ראשון ושני והי' עולים לרגל ג\"פ בשנה להשתחוות<sup data-n=\"7140\">178</sup> לפני ה' בעזרה כמ\"ש יראה כל זכורך<sup data-n=\"7141\">179</sup> את פני ה' ממש כו', וענין נהר זה הוא כידוע דבחי' בינה דאצי' בחי' ה' ראשונה דשם הוי'<sup data-n=\"7142\">180</sup> נק' נהר<sup data-n=\"7143\">181</sup> כמו ונהר יוצא מעדן<sup data-n=\"7144\">182</sup> שהוא בחי' התענוג העצמי ופשוט שנק' עונג הנעלם ונק' עדן סתימאה<sup data-n=\"7145\">183</sup> ונהר הוא בחי' מרחב ההשגה אלקי' שבו העונג העצמי הנעלם מכל רעיון כו' מורגש בגילוי ההשגה כנשמות נהנין מזיו העליון דע\"י כו' בכל חדש ושבת, ויש בזה מעלה יתירה למעלה מנקודו' דחכ' שנק' אין של היש בבינה בהיותו מתענג על הוי' דחכ' בעצמו' התענוג הנעלם שלמעלה גם מהחכ' כו' וכידוע דעיקר התגלות פנימי' בבינה דוקא ושם המדות דאוי\"ר בבחי' התרחבו' גדולה וכמו אה\"ר בתענוגים כו', וזהו בנהר זה יעברו להיות מקבלי' מעונג העצמי' דא\"ס במורגש דבינה (וכמו העוה\"ב שא' להנחיל אוהבי יש<sup data-n=\"7146\">184</sup> ממש וז\"ש הנה אלקינו זה ממש כו' שלמעלה הרבה מכלים ולבושים דחכ' ובינה הבא רק מצד ההשגה עצמה שמלביש ומסתיר למהו\"ע א\"ס דלמת\"ב כלל כנ\"ל). וזהו עד יעבור עמך הוי' למעלה משם הוי'<sup data-n=\"7147\">185</sup> דחו\"ב כו' עד יעבור סתם כו' דהיינו כל מדריגות דקי\"ס הי' בים העליון שהוא רק בחי' העלם דמח' שבא בבחי' הגילוי לדיבור והוא שנעשה ים ליבשה כנ\"ל, כך יהי' עוד עלי' ב' גם בבינה שהוא העלם העונג שמוסתר בהשגה שיהי' בבחי' הגילוי והוא גילוי עונג הנעלם שההעלם דעונג יבא",[["7135","173","<b>אליו ולא למדותיו</b>: נסמן לעיל עז, א."],["7136","174","<b>וישובו ויחנו</b>: בשלח יד, ב."],["7137","175","<b>עד יעבור עמך הוי'</b>: בשלח טו, טז. ראה גם לעיל פ' שמות מ, ד. וש\"נ."],["7138","176","<b>והניף ידו על הנהר. . לשבע</b>: ישעי' יא, טו (בדילוג. ושם: שבעה)."],["7139","177","<b>והיתה למסילה</b>: ישעי' שם, טז (ושם: מסילה)."],["7140","178","<b>עולים לרגל ג\"פ בשנה להשתחוות</b>: נסמן לעיל קמג, א."],["7141","179","<b>יראה כל זכורך</b>: פ' ראה טז, טז."],["7142","180","<b>בינה. . ה' ראשונה דשם הוי'</b>: נסמן לעיל יב, ד הערה 581."],["7143","181","<b>בינה. . נהר</b>: זהר (אדרא דמשכנא) משפטים קכג, ב."],["7144","182","<b>ונהר יוצא מעדן</b>: בראשית ב, י."],["7145","183","<b>עדן סתימאה</b>: נסמן לעיל ה, ג."],["7146","184","<b>להנחיל אוהבי יש</b>: נסמן לעיל קלח, ד."],["7147","185","<b>עד יעבור. . למעלה משם הוי'</b>: נסמן לעיל קמג, א."]]],[2300540613,"בגילוי ובמורגש כנ\"ל. וזהו עד יעבור סתם עם זו קנית קנין זה הוא בבחי' העצמו'<sup data-n=\"7148\">186</sup> דא\"ס ממש כי הנה בחי' נקודת הלב הנ\"ל הוא בבחי' מקור כל רצון ותענוג דאה\"ר בתענוגי' וא\"א שיבא בכלים ולבושים דחו\"ב כלל, וגם מה שיתגלה עצמו' התענוג הנעלם בבינה גם זה אינו אלא דרך מעבר בלבד כמ\"ש בנהר יעברו ברגל והוא נהר שיוצא מעדן הנ\"ל והעיקר הוא מה שבא לבחי' נקודת הלב שלמעלה גם מהתפעלות רצון ותענוג המורגש אלא הוא בהעלם עצמות הנפש ממש בבחי' ביטול במציאות לגמרי והוא השתחווא' בעזרה לראות פני ה' ממש אחר שעברו בנהר ברגל כו' וד\"ל (וזהו בעבר הנהר ישבו<sup data-n=\"7149\">187</sup> כו' כי מהו' שרש אוי\"ר דאברהם ויצחק בעב\"ר הנהר דבינה והוא בחי' רעותא דליבא הנ\"ל והוא בחי' העדן סתימא' הנ\"ל שלמעלה מנהר זה שיוצא מעדן כו' וד\"ל).\n<b>והנה</b> בקי\"ס שהי' גילוי אור העצמי' בנקודת הלב דכנ\"י כנ\"ל עד שנקבע בנפשם לדורות כנ\"ל ואעפ\"י שהי' רק בים סופא דכל דרגין<sup data-n=\"7150\">188</sup> כנ\"ל מ\"מ הי' זה הכנה רבה להיות ביכולתם לעבור הנהר דבינה ג\"כ ברגל, והוא בכל ג\"פ שעולי' לרגל לקבלת פני ה' ממש בהשתחווא' וביטול במציאות ממש ויכולים לעבור הנהר<sup data-n=\"7151\">*189</sup> שהוא בחי' ההשגה דבינה בעונג מורגש הנ\"ל כ\"ז הוא מפני שכבר קבלו הארה זו העצמו' דא\"ס בשעת קי\"ס כשהפך ים ליבשה. אמנם זה הי' ההתחלה ולע\"ל יהי' שלימו' גילוי אור זה דקי\"ס אעפ\"י שמכח זה דקי\"ס יעברו ברגל לדורות אבל אם לא הי' קי\"ס בגילוי אור זה עליהם לא הי' יכולים לעבור הנהר ברגל לדורות לעלות ולראות את פני ה' ממש כו' כי הגיעו למדריגות דבחי' נקודת הלב הנ\"ל, מ\"מ עיקר השמחה בהגלות נגלות עליהם אור העצמו' דא\"ס יהי' לע\"ל כשיעברו בנהר ברגל שם דוקא נשמחה בו ממש כמ\"ש ואמר ביום ההוא הנה אלקינו זה<sup data-n=\"7152\">189</sup> כו', ועכ\"ז שמחה זו דנשמחה בו באה מכח השמחה שהי' בקי\"ס כשא' זה אלי כו' מטעם הנ\"ל וד\"ל. ופי' הפשוט דשם נשמחה בו קאי ארישא דהפך ים ליבשה שם נשמחה בו בשמחה הבאה לדורות שיוכלו לשמוח בו ממש והוא כמו בכל ג' מועדי' שאו' וישמחו בך ממש אעפ\"י שהמועדי' הם בשמחה דבינה<sup data-n=\"7153\">190</sup> אם הבנים שמחה<sup data-n=\"7154\">191</sup> אבל יש בזה משמחה שבעצמו' התענוג הנעלם הנ\"ל שהוא בעצמו' א\"ס ממש והוא מטעם שהפך ים",[["7148","186","<b>עם זו קנית. . בבחי' העצמו'</b>: ראה גם מאמרי אדה\"א קונטרסים ר\"ע שנ."],["7149","187","<b>בעבר הנהר ישבו</b>: נסמן לעיל קמא, ב."],["7150","188","<b>בים סופא דכל דרגין</b>: נסמן לעיל קלז, ד."],["7151","*189","<b>בכל ג\"פ שעולי' לרגל. . לעבור הנהר</b>: ראה גם ד\"ה הפך ים ליבשה תשכ\"ז (סה\"מ מלוקט ח\"א ע' תק)."],["7152","189","<b>ואמר ביום ההוא הנה אלקינו זה</b>: ישעי' כה, ט."],["7153","190","<b>שהמועדי'. . דבינה</b>: ראה פע\"ח (שער מקרא קדש) ש\"כ בתחלתו. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380123\" data-slug=\"likkutei-torah\" data-id=\"4001380123\">לקו\"ת צו יא, ד</a>. ביאוה\"ז קרח צב, ד ואילך. ומקבילו במאמרי אדה\"ז תקס\"ה ח\"ב ע' תרסו. פרשיות התורה ח\"ב ע' תקכ ואילך. מאמרי אדה\"א נ\"ך ע' שעה."],["7154","191","<b>אם הבנים שמחה</b>: תהלים קיג, ט."]]],[2300540627,"ליבשה ע\"כ גם כשיעברו בנהר ברגל שם נשמחה בו ממש וכנ\"ל וד\"ל."],[2300540069,"<b>בעזר\"ה פ' בשלח</b>\n<span data-k=\"pg\">418</span> ּ<b>וירא</b> ישראל את היד הגדולה<sup data-n=\"7155\">1</sup> [אשר עשה ה'] כו' וייראו העם [את ה'] ויאמינו בהוי'<sup data-n=\"7156\">2</sup> כו'<sup data-n=\"7157\">3</sup>, ויש להבין מ\"ש וייראו העם כו' ואח\"כ ויאמינו כו' איך הקדים היראה לאמונה כי הלא היראה הוא בא מצד ההתגלות אלקות מקרוב<sup data-n=\"7158\">4</sup> כמ\"ש וירא ישראל את היד הגדולה כו', ואיך יתכן שאח\"ז יבאו לבחי' האמונה שהוא למעלה מן ההשגה והשכל שא' אח\"כ ויאמינו בה'. ועוד דמשמע שקודם שראו היד כו'<sup data-n=\"7159\">6</sup> לא הי' להם האמונה<sup data-n=\"7160\">5</sup> ובאמת הי' בהם האמונה מיד בבוא אליהם משה במצרים וכמ\"ש וארשתיך לי באמונה<sup data-n=\"7161\">7</sup> כו' וכאן א' ויאמינו בהוי' ובמשה אחר שהי' בהם היראה דוקא. אך הענין הוא דעיקר האמונה והיראה שא' כאן היינו בשם הוי' דוקא כמ\"ש וייראו את הוי' ויאמינו בה' והוא לאחר שראו היד הגדולה אשר עשה ה' במצרים. ויש להקדים תחלה בדרך כלל שיש ב' מדרגות בשם הוי'<sup data-n=\"7162\">8</sup> [, ה]א' שם הוי' שבהעלם העצמ[י]ו' דאור א\"ס שבכתר שקודם לכל ההשתל', והב' שם הוי' הבא בגילוי משם הוי' הזה הנעלם וכמ\"ש ויקרא הוי' הוי'<sup data-n=\"7163\">9</sup> ב\"פ שקרא והמשיך משם הוי' שבהעלם להיות שם הוי' בגילוי (והוא מ\"ש ושמי הוי' שבעצמות לא נודעתי להם<sup data-n=\"7164\">10</sup> רק במ\"ת נגלה לכנ\"י כשא' אנכי הוי' אלקיך<sup data-n=\"7165\">11</sup> ממש כו') (דאעפ\"י שנגלה שם הוי' לאבות כמו וירא הוי' אל אברם<sup data-n=\"7166\">12</sup> כו' וגם במצרים הרי א' כה תאמר<sup data-n=\"7167\">13</sup> כו' [ה'] אלקי אבותיכם [שלחני] כו' זה שמי לעלם כו' (וגם בש[מו]\"ע אנו או' בא\"י אלקינו ואלקי אבותינו כו', זהו בחי' שם הוי' הב' הבא בגילוי מן ההעלם להיות",[["7155","1","<b>וירא ישראל את היד הגדולה</b>: מיוסד על מאמר ד\"ה זה שנדפס במאמרי אדה\"ז תקס\"ו ע' קמג [הנחת כ\"ק אדה\"א]. <a class=\"ft-cite\" href=\"#/read/torah-or/3901370277\" data-slug=\"torah-or\" data-id=\"3901370277\">תו\"א בשלח סא, ד</a>. והגהות וכו' מהצ\"צ על נוסח התו\"א באוה\"ת בשלח ע' תלא. ועל מאמרי אדה\"ז [שם כרך ז] ע' ב'תערב. וראה גם ד\"ה זה במאמרי אדה\"א הנחות תקע\"ז ע' נא. מלקמן קנ, סע\"א נעתק בחלקו בשינויים וכו' בהמשך תרס\"ו ע' רז ואילך. וראה עוד ע\"ד המאמר להלן ברשימת הכת\"י [ושם מפורט ג\"כ סימני האותיות הבאים להלן בהמראי מקומות]."],["7156","2","<b>וירא ישראל. . בהוי'</b>: בשלח יד, לא."],["7157","3","<b>כו'</b>: ד: ובמשה עבדו. וכ\"ה בהמאמרים שבהערה 1."],["7158","4","<b>היראה. . מקרוב</b>: ראה מאמרי אדה\"א בראשית ע' רמב. קונטרסים ע' רפב ובהנסמן בהנ\"ל. מאמרים שבהערה 1. לעיל פ' בא קב, ד ובהערה 282. לקמן פ' משפטים רפג, סע\"א ואילך."],["7159","6","<b>כו'</b>: ד: הגדולה."],["7160","5","<b>דמשמע שקודם שראו. . האמונה</b>: ראה אור החיים כאן."],["7161","7","<b>וארשתיך לי באמונה</b>: הושע ב, כב."],["7162","8","<b>ב' מדריגות בשם הוי'</b>: ראה הערה הבאה."],["7163","9","<b>ויקרא הוי' הוי'</b>: תשא לד, ו. ראה גם <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380955\" data-slug=\"likkutei-torah\" data-id=\"4001380955\">לקו\"ת ר\"ה נט, סע\"א</a> ואילך. מאמרי אדה\"א נ\"ך ע' רח. וש\"נ. מאמרים שבהערה 1. לקמן פ' תצוה שנח, ב. שס, א."],["7164","10","<b>ושמי הוי'. . לא נודעתי להם</b>: וארא ו, ג. וראה גם לעיל פ' בא קיג, ב הערה 102."],["7165","11","<b>אנכי הוי' אלקיך</b>: יתרו כ, ב."],["7166","12","<b>וירא ה' אל אברם</b>: לך יב, ז. יז, א."],["7167","13","<b>כה תאמר</b>: שמות ג, טו."]]],[2300540107,"מקור להשתלשלו' (כמשי\"ת), אבל שמי הוי' הנעלם בעצמות לא נודעתי גם לאבות רק מלובש בתו\"מ דוקא שנק' תורת הוי'<sup data-n=\"7168\">14</sup> מצות הוי'<sup data-n=\"7169\">15</sup> ולע\"ל יתגלה מהעלמו כו'). וביאור הענין הנה ידוע ששם זה הוי' יש בו ב' ענינים, א' כמו שהוא שם העצם ממש שמורה על בחי' מהו\"ע (כמו שמו' העצמיי' דאדם שקרא שמות<sup data-n=\"7170\">16</sup> כו' כמ\"ש במ\"א), והב' בחי' שם התואר והפעולה דהיינו על שם מה שממנו נמשך בבחי' גילוי והתפשטות דבר מה כהתפשטו' החכ' מן החכם והחסד מאיש החסד וכן בפעולותיו ומדותיו שבאי' בכלים מכלים שונים כך יהי' שמו אשר יקראו לו זולתו כו'. וכך יובן ב' אופנים אלה בשם הוי' א' שם זה כמו שהוא מורה על בחי' העצמו' דא\"ס כמו שהוא בפנימי' ועצמו' בהעלם עצמותו שלמעלה מגילוי התפשטות אורו להיות מקור להשתלשלות העולמות (והוא שם הוי' שבתו\"מ שהן בפנימי' ועצמו' רצונו וחכמתו (כמשי\"ת), והב' שם הוי' הבא בגילוי והתפשטות אור בבחי' שם התואר והפעולה, והוא מה שנק' שם הוי' ע\"ש בחי' ההתהוות<sup data-n=\"7171\">17</sup> של כל העולמות מאין ליש מאור הא\"ס ע\"י התפשטות האורות דע\"ס בכלים מכלים שונים בחו\"ב ומדות ומודו\"מ כו' שנק' שם התואר והפעולה וע\"כ נק' שם הוי' לפי שהוא ית' מהווה את הכל בשם זה דהוי' (אבל מה שנק' הוי' העצמי היינו פי' הענין דהי' הוה ויהי'<sup data-n=\"7172\">18</sup> שכולל עבר הוה ועתיד כא' להיותו מקור הכולל כל ההשתלשלות במח' א' (וגם זה שייך להשתלשלו' רק שהוא בחי' מקיף כללי והוא קוצו ש\"י שהוא בבחי' הכתר<sup data-n=\"7173\">19</sup> שהוא הרצון המוחלט שממנו יבא לגילוי ביו\"ד שמורה לשון עתיד<sup data-n=\"7174\">20</sup> כלומר שעתיד להיות בגילוי מאין ליש ממש (כמשי\"ת), אבל עצמו' דא\"ס שלמעלה גם מבחי' מקור ומקיף הוא שם הוי' שבתו\"מ שיתגלה לע\"ל).\n<b>והנה</b> תחלה יש להבין מהו ענין ההתהוות מאין ליש ולמה דוקא בד' אותיות האלה דשם הוי'<sup data-n=\"7175\">21</sup> יו\"ד ואח\"כ ה\"א כו', והלא אין עוד מלבדו<sup data-n=\"7176\">22</sup> ואין לך דבר חוץ ממנו ית' באין שינוי כלל מקודם <span data-k=\"pg\">רט</span> ּ ההשתלשלות לאח\"כ כמ\"ש אני הוי' לא שניתי<sup data-n=\"7177\">23</sup> כו' ואיך יוכל להיות התהוות דבר נפרד בע\"ג חוץ ממנו כו'. אך הנה ידוע שיש ב' מיני שפע הא' הבאה בדרך והדרגה מעילה לעלול<sup data-n=\"7178\">24</sup> מיש ליש שיכול לבוא השפע כמו שהוא במשפיע כמו צדקה מעשיר לעני כו' וכה\"ג שבא בידי המקבל בלי שינוי המהות כלל, והשפע הב' הבאה בדילוג הערך והמדרגה מן המשפיע למקבל בשינוי המהות לגמרי שזהו הנק' מאין ליש לפי שאין ערך כלל למקבל לגבי המשפיע שאז צריך שיבא השפע מן",[["7168","14","<b>תורת הוי'</b>: בא יג, ט."],["7169","15","<b>מצות הוי'</b>: ויקרא ד, ב. יג. כב. ועוד."],["7170","16","<b>דאדם שקרא שמות</b>: ראה מאמרי אדה\"א דברים ח\"ד ע' א'רסח ואילך."],["7171","17","<b>הוי' ע\"ש בחי' ההתהוות</b>: ראה זהר (רע\"מ) פינחס רנז, סע\"ב. פרדס (שער עשר ולא תשע) ש\"א, פ\"ט. (שער עצמות וכלים) ש\"ד, ספ\"י. שהיחוה\"א פ\"ד. פ\"ז. הערה בסה\"מ ה'ש\"ת ע' 40."],["7172","18","<b>הוי'. . דהי' הוה ויהי'</b>: נסמן לעיל פ' וארא מט, ד."],["7173","19","<b>קוצו ש\"י. . הכתר</b>: ראה זהר ויקרא י, ב. פרדס (שער שם בן ד') שי\"ט, פ\"ב. הנסמן במאמרי אדה\"א קונטרסים ע' תכז."],["7174","20","<b>ביו\"ד שמורה לשון עתיד</b>: ראה שהיחוה\"א פ\"ד (עט, רע\"א). לקמן קפה, ב. פ' תרומה שה, א. תצוה שסז, ב. מאמרי אדה\"ז תקס\"ה ח\"ב ע' תתעח. מאמרי אדה\"א דברים ח\"ג ע' תשצ. וש\"נ. ש\"א יד, א ובהערה 16."],["7175","21","<b>ההתהוות. . בד' אותיות. . הוי'</b>: ראה אגה\"ת פ\"ד. מאמרים שנסמנו בריש המאמר."],["7176","22","<b>אין עוד מלבדו</b>: ואתחנן ד, לה."],["7177","23","<b>אני הוי' לא שניתי</b>: מלאכי ג, ו."],["7178","24","<b>מעילה לעלול</b>: ב<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381108\" data-slug=\"likkutei-torah\" data-id=\"4001381108\">לקו\"ת ברכה צה, ב</a>: הנזכר בספרים. ראה רמב\"ם הל' יסוה\"ת פ\"ב, ה\"ו."]]],[2300540145,"המשפיע ע\"י בחי' צמצום אור עצמותו לגמרי בתחלה כדי שיוכל לבא לפי ערך כלי המקבל לבד. וזהו ענין כח ושפע האור האלקי העליון שהוא בלתי בע\"ג ותכלית ואין ערוך כלל לנברא בע\"ג לבלתי ב\"ג כידוע, וע\"כ כשהוצרך להיות התהוות מציאות נבראים בע\"ג מן הבורא ית' שהוא בלתי בע\"ג א\"א להיות כמו אופן השפע הא' מעצמו' המשפיע בדרך עו\"ע כשאר ההשתלשלו' אלא ע\"י בחי' צמצום האור האלקי בתחלה לגמרי והוא כדי שיוכל להיות אח\"כ שינוי האור לפ\"ע הנצרך להיות מהות התהוות הבריאה בע\"ג כו', וא\"ל לא הי' מציאות ב\"ג אלא הכל הי' בבחי' אלקו' בלתי ב\"ג (וז\"ש בראשית ברא אלקי'<sup data-n=\"7179\">25</sup> שהוא ע\"י שם אלקי' המצמצם האור כידוע). והיינו ג\"כ ענין הד' אותיות דשם הוי' המלובש בשם אלקי' שהוא שם הפעולה דהוי' שמהווה את הכל מאין ליש כנ\"ל, וכידוע דאות היו\"ד דשם הוי' שאינו רק כמו נקודה לבד בלי התפשטות שטח אורך ורוחב מורה על בחי' צמצום<sup data-n=\"7180\">26</sup> אור העצמו' שמעלים ומצמצם בתחלה כל בחי' אור השפע שבעצמותו לגמרי עד שנשאר רק כמו נקודה א' לבד, וענין נקודה זאת זהו רק מה שנשאר בעצם השפע להתצמצם ולהתמשך רק לצורך התהוות הנבראי' בע\"ג בלבד כו' וד\"ל.\n<b>וידוע</b> המשל בזה מן השפעת שכל וחכמה מרב גדול לתלמיד קטן הערך שאין ערך כלל לתלמידו אליו שיוכל לקבל השכל כמו שהוא אצלו ברוחב חכמתו ובינתו ע\"כ ודאי צריך שהרב החפץ להשפיע לצמצם עצם אור שפע שכל זה בלתי יתגלה השכלת עצמו באותו השכל, ומה שמעלים בזה השכל כל עצם חכמתו זהו משל לענין קוצו של יו\"ד שנשאר בהעלם במשפיע, ומה שנשאר עכ\"פ כנקוד' דיו\"ד זהו מה שנשאר בצמצום היותר אחרון להיות מזה כל אופן הילוך השפע לתלמיד המקבל (שנמצא שיש בנקודה זו ב' עניני צמצום, א' שנתעלם עצמו' השכלתו וכלול בה בקיצור, והב' מה שנקודה זו כולל בהעלם וצמצום כל מה שיושפע למקבל באורך ורוחב, שבודאי מה שכלול בנקודה זו כל עצם השכלתו בשכל זה גבוה הרבה ממה שכוללת כל מה שיומשך למקבל, ועכ\"ז הכלל<sup data-n=\"7181\">27</sup> נכלל בנקוד' די', רק שקוץ העליון הוא העלם אור המשפיע בי' וקוץ התחתון שבה הוא שמתמונת הי' שבא בהתפשטות בה\"א (אבל נקודה די' בלא תמונה כלל א\"א לבא בהתפשטו' דה\"א באורך ורוחב אם לא ע\"י הקו שנעשה מריבוי נקודו'<sup data-n=\"7182\">28</sup> זע\"ז כו' וד\"ל, שהוא בקו הנמשך שאין בו אורך ורוחב שקודם לשטח דה\"א",[["7179","25","<b>בראשית ברא אלקי'</b>: בראשית א, א. ראה גם לעיל פ' שמות ל, ב. וש\"נ."],["7180","26","<b>דאות היו\"ד. . צמצום</b>: ראה גם אגה\"ת פ\"ד. מאמרי אדה\"ז תקס\"ו כאן ע' קמג וע' שלה. לקמן פ' תצוה שנו, ג. ויקהל שפז, ג. מאמרי אדה\"א דברים ח\"ב ע' תרנ וע' תרעח."],["7181","27","<b>הכלל</b>: גד: הכל."],["7182","28","<b>הקו שנעשה מריבוי נקודו'</b>: ראה גם שעה\"י קכ, א ובהערה 3."]]],[2300540182,"שזהו ענין נקודה קו שטח<sup data-n=\"7183\">29</sup> בכללות שא\"א לה\"א בלא קו תחלה וענין הוי\"ו שאחר הה\"א זהו ענין הילוך השפע למקבל לעשות בו שטח דה\"א זה עצמו). וענין הה' שאחר הי' הוא בחי' התפשטות <span data-k=\"pg\">420</span> ּ אורך ורוחב בענין השפע הזאת כפי הצריך לבא למקבל דוקא והכל בעצמו' המשפיע עדיין (כמו שמצייר במח' איך להביא הציור או השכל בלשון וכתב). ואח\"כ הוי\"ו שהולך ביושר מלמעלה למטה ראשו כיו\"ד<sup data-n=\"7184\">30</sup> וסופו מתקצר, זהו הילוך השפע דה\"א הנ\"ל שיוכל לבא בגילוי למקבל שהוא גילוי השפעת השכל כאשר בא בבחי' המשכה למטה למקבל, וזהו שנק' המשכה שאחר ההתפשטו' דה\"א שבעצמו' המשפיע לצורך ההשפעה (וע\"כ ראשו יו\"ד שבא בצמצום אחר ההתפשטו' דאורך ורוחב שבמשפיע והולך ומתקצר בירידתו למקבל כמו גילוי השכל במחשבה שבא בדיבור למקבל כו'). ואחר הוי\"ו הזה הנק' המשכה אע\"פ שיש בה בקיצור כל אורך ורוחב דה\"א שבמשפיע עכ\"ז למעלה הוא עדיין מערך כלי המקבל וע\"כ מסוף הוי\"ו הוא שנעשה בחי' התפשטו' השגה ותפיסא בערך צמצום כלי המקבל שזהו ה\"א האחרונה שמתיישבת השפע בכלי המקבל השומע מרבו (וא\"כ יש כאן ד' צמצומים אשר כל א' עושה שינוי המהות, א' צמצום דקוצו של יו\"ד בי' וב' צמצום די' בה' וג' מה\"א לו' וד' מו' לה\"א).\n<b>והנמשל</b> מכ\"ז יובן למעלה בעיקר טעם קריאת שם הוי' ע\"ש בחי' ההתהוות כל בע\"ג מבלתי בע\"ג שאין ערוך כלל ביניהם ע\"כ הוצרך להיות ע\"י ד' אותיות הללו דשם הוי' שהוא יו\"ד צמצום אור העצמות בתחלה שזהו ההעלם וצמצום לגמרי עד שלא נשאר רק [כ]נקוד' די' והוא ענין צמצום החכ' בשביל מע\"ב מאין ליש (כמו שמצמצם עוצם<sup data-n=\"7185\">31</sup> כח שכלו בשביל השכלה קטנה לבנות בנין), וז\"ש בראשית ברא כו' וכן ה' בחכ'<sup data-n=\"7186\">32</sup> כו' ע\"י צמצום עצם החכ', ומה שנשאר נקודה זו די' היינו רק כדי הצריך לשפע זאת דמע\"ב לבד (וגם נקודה זו כוללת בהעלם כל מה שעתיד להשפיע כנ\"ל, ובודאי מה שנעלם בנקודה גבוה הרבה ממה שכוללת כל מה שיומשך ממנה כנ\"ל והיינו בחי' חכ' דמע\"ב דבראשית נמי מאמר הוא<sup data-n=\"7187\">33</sup> שכוללת הכל כא' בזמן ומקום בעש\"נ<sup data-n=\"7188\">34</sup> גם בכללות דאבי\"ע שעתיד להתמשך בו\"א שני'<sup data-n=\"7189\">35</sup> כו', והוא יו\"ד דשם הוי' שמורה ענין עתיד ותמידי כמו יו\"ד דככה יעשה איוב<sup data-n=\"7190\">36</sup> כו' שיהי' בתמידות ולא בגילוי אלא כולל בהעלם ובתמצית עדיין כמו הכלל אל הפרט שנק' מחשבה א' שסוקר הכל בסקירה א' ונק' מח' כללית וזהו ענין הי' הוה ויהי' שכולל עבר הוה ועתיד כא' כידוע, עכ\"ז אין לכל זה ערך לגבי בחי'",[["7183","29","<b>נקודה קו שטח</b>: נסמן לקמן קפה, א."],["7184","30","<b>הוי\"ו. . ראשו כיו\"ד</b>: ראה גם מאמרי אדה\"ז תקס\"ו כאן (ע' קמז). לקמן קנה, ב. מאמרי אדה\"א דברים ח\"ב ע' תרעח. וש\"נ. נ\"ך ע' עט. וש\"נ."],["7185","31","<b>עוצם</b>: ג: ליתא. ד: עצם."],["7186","32","<b>ה' בחכ'</b>: משלי ג, יט."],["7187","33","<b>דבראשית נמי מאמר הוא</b>: ר\"ה לב, א."],["7188","34","<b>בעש\"נ</b>: בעולם שנה נפש. ראה גם לעיל פ' וארא נג, ב. וש\"נ."],["7189","35","<b>בו\"א שני'</b>: ר\"ה לא, א. ראה הנסמן במאמרי אדה\"א בראשית ע' נג."],["7190","36","<b>דככה יעשה איוב</b>: איוב א, ה. וראה לעיל הערה 20."]]],[2300540219,"ההעלם דכתר דחכ' שנעלם לגמרי בנקודה זו ולא נשאר ממנו רק כנקודה כנ\"ל שנחשב מבחי' אור העצמו' (והוא ההפרש באמת בין נקודה לבד בי' בלא תמונת אות היו\"ד שלא יבא לכלל התפשטות דה\"א כלל כנ\"ל ובין אות יו\"ד שיש בו בהעלם ובמלוי ו\"ד שזהו קו ושטח הכלול בנקודה די' שבא יבא מן ההעלם לגילוי עכ\"פ להיות בתמונת ה\"א (וזהו נקודה קו שטח דמילוי יו\"ד שעי\"ז נמשך הה\"א מקוץ התחתון די' כשהוא בתמונת אות יו\"ד דוקא דו\"ד הוא הקו ושטח שיכול להתמשך מן הנקודה דחכ' משא\"כ נקודה די' עצמו בלי ציור תמונה דאות היו\"ד אין בו קו ושטח דו\"ד אפילו בהעלם ונק' שכל הנעלם מכ\"ר<sup data-n=\"7191\">37</sup> שלא בא לגילוי כלל (ואמנם באמת גם מן העלם עצמות הרצון שלמעלה גם מטעם כמוס לרצון נמשך לגילוי בנקודה די' להיות ממנו מקור כללי להשתלשלו' בקו ושטח דו\"ד שבו (כמשי\"ת), שהרי מקוצו ש\"י נמשך הי' בתמונת <span data-k=\"pg\">רי</span> ּ אות עכ\"פ משום דגם נקודה שנשאר מהעלם עצמותו נעשה יו\"ד בקו ושטח) (וראי' לזה גם מענין צמצום הראשון שנשאר רושם אחר ההעלם דאוא\"ס בעצמותו (והוא בקיעת יו\"ד דס\"ג בטה\"ע<sup data-n=\"7192\">38</sup> כו' כמ\"ש בס' עמק המלך), ומן הרושם שהוא רק כמו נקודה נמשך בחי' הקו\"ח<sup data-n=\"7193\">39</sup> ומן הקו נמשך בנין כלל<sup data-n=\"7194\">40</sup> ההשתלשלו' דאצי' ובי\"ע באו\"כ שבכלל זהו בחי' שטח וה\"ז בכלל נקודה קו שטח, ובודאי מה שנקודה זו שבקו\"ח כוללת הכל אין לזה ערך לגבי ההעלם דעצמות שנשאר בנקודה זו שעכ\"ז נעשה ממנה קו ושטח שנק' חי העולמים<sup data-n=\"7195\">41</sup> אע\"פ שא' כי עמך מקור חיים<sup data-n=\"7196\">42</sup> וכך א' הוא מקומו ש\"ע<sup data-n=\"7197\">43</sup> ואין העולם מקומו, אבל מ\"מ דוקא ממה שנשאר מבחי' ההעלם בנקודה זו הוא שנמשך מנקודה זו בקו ושטח (וכמו במשל המצמצם ומעלים כל עצם השכלתו בשכל זה עד שלא נשאר ממנו רק הנקודה שהיא כוללת בהעלם מכל האריכות שבעצמו' שכלו דוקא עכ\"ז מנקודה זו עצמה הוא שנמשך כל מה שצריך לבא בהשפעה למקבל משום דהא בהא תליא וממקור א' יצא שהוא מעצם כח החכמה שבמשפיע רק שבא ע\"י צמצום והעלם אור העצמות להיות נמשך למקבל דוקא וד\"ל) (וכך הוא בענין צמצום והתפשטות שברצון שלמעלה מן השכל כמשי\"ת) גם בפנימי' הרצון העליון דמצות כו' (ומ\"ש למתב\"כ<sup data-n=\"7198\">44</sup> אפי' מח' הכללי' להיותו למעלה מבחי' הכלל לפרט עכ\"ז ממנו נמשך מחשבה זו הכללי' כמ\"ש כי עמך מקור חיים הכללי עמך דוקא כו' (ובדרך פרט יש ד' אותיות דשם הוי' בעצמות יו\"ד וה\"א צמצום דרושם והתפשטות דמח' הכללי' שנק' טה\"ע וקו\"ח זהו הוי\"ו וה\"א אחרונה טה\"ת וזהו ב\"פ הוי' מן ההעלם לגילוי כמו מן הרצון המוחלט לטעם דרצון בהעלם כו' כמשי\"ת, וכמו\"כ",[["7191","37","<b>שכל הנעלם מכ\"ר</b>: נסמן לעיל פ' שמות מז, ג."],["7192","38","<b>בקיעת יו\"ד דס\"ג בטה\"ע. . בס' עמק המלך</b>: ראה שם ש\"ג. לקמן קפג, ב. פ' יתרו רעו, ב. תצוה שסח, א. מאמרי אדה\"א נ\"ך ע' רלא. וש\"נ. שער היחוד קכ, ב ובהערה 10. סה\"מ תרנ\"ט ע' עז בהערה."],["7193","39","<b>ומן הרושם. . הקו\"ח</b>: ראה מאמרי אדה\"א קונטרסים ע' ח בשם הע\"ח. וש\"נ. שער היחוד קיד, ריש ע\"ב ובהערה 19. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300670582\" data-slug=\"torat-chaim\" data-id=\"2300670582\">תו\"ח נח עה, סע\"ד</a> ואילך ובהערה 42."],["7194","40","<b>כלל</b>: ד: כל."],["7195","41","<b>חי העולמים</b>: ראה תויו\"ט סוף תמיד."],["7196","42","<b>כי עמך מקור חיים</b>: תהלים לו, י."],["7197","43","<b>הוא מקומו ש\"ע</b>: ראה ב\"ר פס\"ח, ט. הנסמן ב<a class=\"ft-cite\" href=\"#/read/torat-chaim/2300670491\" data-slug=\"torat-chaim\" data-id=\"2300670491\">תורת חיים בראשית מג, א</a> הערה 2."],["7198","44","<b>למתב\"כ</b>: ת\"ז בהקדמה (יז, א)."]]],[2300540251,"בקדושת המצות בפנימי' רצה\"ע הרי מעצמות קדושתו כמו שהוא למעלה ממקיף דאבי\"ע נמשך קדוש' להיות קדוש הוי'<sup data-n=\"7199\">45</sup> לגבי העולמות כו').\n<b>(ונמצא</b> שיש נקודה קו שטח בב' אופנים בכל שם הוי' גם בשם הוי' שבגילוי דהיינו בהעלם ובגילוי דהיינו בי\"ה שנק' נסתרות<sup data-n=\"7200\">46</sup> הרי מן הנקודה די' נמשך ו' וממנו הה\"א (ע\"י ו\"ד שבי' כנ\"ל והיינו<sup data-n=\"7201\">47</sup> בחי' עלמא דאתכסייא<sup data-n=\"7202\">48</sup> בכלל כמ\"ש כי בי\"ה<sup data-n=\"7203\">49</sup> כו' וכמשל השפע שבאה במשפיע לאורך ורוחב אחר הצמצום והעלם עצמו' השכלתו לצורך ההשפעה כנ\"ל), והב' וי\"ו וה\"א הנגלות<sup data-n=\"7204\">50</sup> ויש<sup data-n=\"7205\">51</sup> נקוד' בוי\"ו למעלה ושרשו בוי\"ו רגל הקצר שבה\"א ראשונה דאושיט פסיעה לבר<sup data-n=\"7206\">52</sup> כידוע) להיות שטח בעלמא דאתגלייא<sup data-n=\"7207\">53</sup> כו'), ונמצא מובן עכ\"פ שמבחי' ו\"ה זהו עיקר הסיבה להתהוות בע\"ג שהמשכה דוי\"ו מתקצר ונמשך לבא אח\"כ בהתפשטו' דה\"א אחרונה שבה\"א בראם<sup data-n=\"7208\">54</sup> מאין ליש ממש וד\"ל. וזהו הטעם שהכל יכולים לשבח ולהלל לשם הוי' אפי' מלאכים וברואים התחתונים ביותר בשמים<sup data-n=\"7209\">55</sup> וארץ וכל צבאם שא' יהללו את שם הוי'<sup data-n=\"7210\">56</sup> כו' לפי שבשם הוי' בד' אותיות הללו הוא שנמשך מכח האלקי הבלתי בע\"ג ונתצמצם להיות בחי' מקור להתהוותם מאין ליש בבחי' כח הפועל בנפעל ממש בה\"א אחרונה שבראם מאין ליש גמור, ולכך או' כל הנבראי' שירה<sup data-n=\"7211\">57</sup> לשם הוי' שהוא מקור כל הויות הנמצאי' כנ\"ל (אע\"פ שעיקר כח האלקי המלובש בהם הוא שם אלקי' שמסתיר ע\"ש הוי' או שם אד' כמ\"ש אד' בם<sup data-n=\"7212\">58</sup> כו' וכתיב בראשית ברא אלקי' כידוע וכנ\"ל, היינו מה שכבר מלובש בצמצום גמור בתוך כל נברא שנק' כח הפועל שבנפעל<sup data-n=\"7213\">59</sup> מריש כל דרגין דעולם <span data-k=\"pg\">422</span> ּ הבריאה עד סוף דצח\"מ דעשי' וארמ\"ע הגשמיי', אבל שם הוי' זהו למעלה מצמצום זה כי אינו אלא סדר ההילוך של השפע האלקי מן המשפיע מלמעלה למטה עד שיוכל להיות מקור להתהוות כל בע\"ג בה\"א אחרונה שהוא בא בצמצום בתוך כ\"ע כו' וד\"ל) (ומ\"ש כי הוי' הוא האלקי' דכולא חד<sup data-n=\"7214\">60</sup>, משום דגם צמצום זה האחרון דאלקי' הוא מתייחד בשם הוי' בלי שום הסתר כלל כידוע).\n<b>אך</b> הנה עדיין יש להבין מ\"ש כי הוא צוה ונבראו<sup data-n=\"7215\">61</sup> ולא א' כי שם הוי' ציוה כו' ומהו ונבראו ממילא כו', אך הנה אע\"פ שמבואר למעלה ששם הוי' הנ\"ל ישנו בכללות כל ההשתל' דכל העולמות כי כל בחי' התהוות מאין האלקי לבחי' יש בע\"ג א\"א כ\"א ע\"י ד' אותיות הללו דשם הוי' צמצום והתפשטות המשכה",[["7199","45","<b>קדוש ה'</b>: ישעי' ו, ג."],["7200","46","<b>בי\"ה שנק' נסתרות</b>: נסמן לעיל פ' בא קג, ג."],["7201","47","<b>והיינו</b>: ד: וזהו."],["7202","48","<b>עלמא דאתכסיא</b>: נסמן לעיל פ' שמות לג, א."],["7203","49","<b>כי בי\"ה</b>: ישעי' כו, ד."],["7204","50","<b>וי\"ו וה\"א הנגלות</b>: נסמן לעיל פ' בא קג, ג."],["7205","51","<b>הנגלות ויש</b>: ד: אחרונ' יש. ואוצ\"ל: הנגלות (ויש."],["7206","52","<b>רגל הקצר שבה\"א. . לבר</b>: נסמן לעיל יח, ד."],["7207","53","<b>בעלמא דאתגלייא</b>: נסמן לעיל לג, א."],["7208","54","<b>שבה\"א בראם</b>: נסמן לעיל לד, א."],["7209","55","<b>בשמים</b>: ד: כשמים."],["7210","56","<b>יהללו את שם הוי'</b>: תהלים קמח, ה."],["7211","57","<b>או' כל הנבראי' שירה</b>: ראה פרק שירה. מאמרי אדה\"ז תקס\"ה ח\"א ע' רל."],["7212","58","<b>אד' בם</b>: תהלים סח, יח."],["7213","59","<b>כח הפועל שבנפעל</b>: נסמן לעיל עה, א."],["7214","60","<b>כי הוי' הוא האלקי' דכולא חד</b>: נסמן לעיל פ' וארא ס, א."],["7215","61","<b>כי הוא צוה ונבראו</b>: המשך הכתוב יהללו את שם ה'."]]],[2300540282,"והתפשטות (ואפי' עולם הנאצל מאחר שגם הוא בא ע\"י צמצום ודילוג הערך מעצמו' המאציל דלאו מכא\"מ כלל<sup data-n=\"7216\">62</sup> ובו א'<sup data-n=\"7217\">63</sup> ע\"ס בלי מ\"ה בלי מהות<sup data-n=\"7218\">64</sup> רק כניצוץ מן השלהבת וכה\"ג גם זה צ\"ל ע\"י ד' אותיות דשם הוי' בכל ספירה וספירה כידוע), אבל יש עוד שם הוי' שלמעלה מזה שאינו נק' הוי' ע\"ש התהוות דבר מה כלל ככח האלקי בעולמות כנ\"ל, אלא הוא רק בבחי' ההעלם בעצמו' המשפיע ממש טרם שמהווה עדיין שום דבר וקודם שיבא לכלל צמצום בעצמו להיות בבחי' כח הפועל בנפעל כו' וע\"ז א' כי הוא צוה דהיינו ברצונו הפשוט והקדום כתי' בראשית בקדמין ברא, ואז ונבראו בשם הוי' ממילא כנ\"ל.\n<b>וביאור</b> הענין הנה ידוע שעיקר המקור<sup data-n=\"7219\">66</sup> להשתלשלו' העולמות הוא בחי' הרצה\"ע ונק' רצה\"פ כמ\"ש כד סליק ברעותי'<sup data-n=\"7220\">67</sup> למברי עלמא, וכמו\"כ כשעלה ברצונו הפשוט להאציל<sup data-n=\"7221\">68</sup> כו', ורצון זה הוא בבחי' ההעלם עדיין בעצמות המאציל ונק' רצון המוחלט וכאשר יוצא לגילוי מהעלם העצמו' ממש גם טרם שבא הרצון לפ\"מ יש בזה ד' אותיות דשם הוי' ממש כמו שיש ד' אותיות דהוי' בגילוי השפע מן המשפיע להיות התהוות העולמות מאין ליש כנ\"ל, וכאשר יצא מן הרצון הזה לגילוי אור<sup data-n=\"7222\">69</sup> להשפיע ממש זהו רק שיצא מן ההעלם וכח אל הפועל בהתגלות לבד, שהרצון אע\"פ שבא בגילוי מהעלם עצמותו ממש הי' בהעלם בלתי בא לידי פ\"מ עדיין אמנם כשבא לידי פ\"מ אין כל חדש בפרט שבו רק כפי שעלה ברצונו תחלה ממש בלי תוס' ובלי מגרעת כלל, וזהו שאו' ברוך שאמר והי' העולם, פי' שאמר ברצונו<sup data-n=\"7223\">70</sup> ומחשבתו ואח\"כ ממילא יצא לגילוי בהתהוות ממש מאין ליש בלי שינוי כלל וזהו והי' העולם ממילא, וזהו כי הוא ציוה ברצונו תחלה ונבראו מאין ליש ממילא כמו שמוציא אדם מחשבתו ורצונו מן ההעלם לגילוי בלבד, וזהו ענין ב\"פ הוי' כנ\"ל (וז\"ש בזהר בריש הורמנא דמלכא<sup data-n=\"7224\">71</sup> גליף גליפו כו' כמשי\"ת). ויובן זה עד\"מ אדם שחפץ ורוצה לבנות בנין גדול או לצייר דבר מה או לכתוב דבר וכיוצא שבודאי תחלה עולה במחשבתו ורצונו איכות אופן ציור הבנין בכל פרטיו באיזה אופן יהי' בנין חדריו ועליותיו וכן באופן פרטי מעשה הציור והכתב וכיוצא וכפי האופן שעולה ברצונו ומח[שבתו], כן ממש יבא לגמור זה בפועל ובגילוי, וא\"כ הרי אין כל דבר חדש בזה כלל אלא רק במה שהוציא מכח אל הפועל בלבד אבל עצם גופו של אופן הבנין או הציור וכתב <span data-k=\"pg\">ריא</span> ּ אין בו חידוש שכבר הכל הועלה בכל פרטיות ברצון ומח' בתחלה דסוף מעשה עבמח\"ת,",[["7216","62","<b>דלאו מכא\"מ </b>[גד: מכל אינון מדות]<b> כלל</b>: ראה ת\"ז בהקדמה (יז, ב)."],["7217","63","<b>ובו א'</b>: ד: ובס\"י אמר."],["7218","64","<b>ע\"ס. . בלי מהות</b>: ס\"י פ\"א, מ\"ב ובמפרשים שם."],["7219","66","<b>המקור</b>: ד: ראשית המקור."],["7220","67","<b>כד סליק ברעותי'</b>: ראה זהר לך פו, סע\"ב."],["7221","68","<b>כשעלה ברצונו הפשוט להאציל</b>: ראה ע\"ח (דרוש עגו\"י) ש\"א, ענף ב. מאמרי אדה\"א דברים ח\"ב ע' תקפז בהערה. שעה\"י קטו, א הערה 2."],["7222","69","<b>אור</b>: ד: ליתא."],["7223","70","<b>ברוך שאמר. . ברצונו</b>: נסמן לעיל פ' בא קכו, ב."],["7224","71","<b>בריש הורמנא דמלכא</b>: ראה זהר בראשית טו, א."]]],[2300540310,"אלא שהי' בעצמות הרצון בהעלם ובכח עדיין ובבואו מן ההעלם הרצון ומח' אל הפועל זהו רק שבא בהתגלות מן ההעלם לבד (כמו המחשבה שבהעלם שבא בגילוי לדבור כידוע). וא\"כ לפ\"ז<sup data-n=\"7225\">73</sup> כמו שבבוא השפע מן המשפיע לגילוי א\"א כ\"א ע\"י בחי' ד' אותיות דצמצום והתפשטות והמשכה והתפשטות כנ\"ל כך ברצון עצמו בהעלם א\"א להיות כ\"א ע\"י ד' אותיות כאלה ממש. ויובן זה למעלה כשעלה ברצונו הפשוט להאציל ולברוא כו' שהי' שם בבחי' ההעלם ובכח בעצמותו עדיין בכל פרטי אופני ההמשכה שיהי' בהתגלות ממש הכל קדם לבא ברצון העליון שעלה כן בעצמות המשפיע (והוא מ\"ש בריש הורמנא כו' כשעלה רשות ורצון הפשוט בעצמו' שעשועי המלך<sup data-n=\"7226\">74</sup> להאציל כו' גליף גליפו בטה\"ע דהיינו מה ששיער בעצמו בכח<sup data-n=\"7227\">75</sup> והעלם הרצון מה שעתיד להיות בפועל כו'), וכמו\"כ יובן שכמו שא\"א בגילוי אור השפע רק ע\"י ד' אותיות דשם הוי' כנ\"ל, כך גם בהעלם הרצון הוצרך להיות ע\"י ד' אותיות דשם הוי' ונק' שם הוי' שבהעלם עדיין וז\"ש הוי' הוי' כנ\"ל וד\"ל.\n<b>וביאור</b> ענין ד' אותיות דיו\"ד וה\"א כו' ברצון שבהעלם הנה כמו שמבואר למעלה בענין היו\"ד וקוצו ש\"י שכל עיקר הכח של עצמו' נתעלם תחלה בעצמותו ולא נשאר רק רושם כמו נקודה די' שכלול בו הכל וגם כלול בנקודה זאת כל מה שעתיד להשפיע כו', כך הוא גם ברצון כי הרצון הרי הוא בחי' הטיית בעל הרצון להיות בא לכלל רצון בגילוי לעצמו שצריך להיות תחלה צמצום עצמותו שברצון זה, והוא ענין הרצון המוחלט שכבר נשאר ונכלל בעצמותו בכללו' ולא בא לגילוי עדיין כלל גם בעצמו והוא שלא נשאר רק כנקודה אפס קצה מהרצון המוחלט הזה להיות בגילוי רצון מכל אשר כלול בעצמו ממש ונקודה זו כוללת כל התפשטו' הרצון הזה לאורך ורוחב בעצמו איך שיהי' אופן התגלות הרצון במעשה בפו\"מ כו' כנ\"ל (והוא שנק' שיעור שמשער בעצמו מה שעתיד להיות בפועל כמו שמשער המשפיע איך ובאיזה אופן יהי' השפעתו למקבל כנ\"ל, וז\"ש גליף גליפו חקיק' אותיות בטה\"ע שזהו שטח דה\"א ראשונה שנמשך מי' דרושם שנשאר מהעלם וצמצום הראשון כנ\"ל, ואח\"כ נמשך הקו\"ח שהוא הוי\"ו ומתעגל<sup data-n=\"7228\">76</sup> בבחי' טה\"ת שהוא ה\"א אחרונה כנ\"ל), וכמו שמבואר למעלה בנקוד' די' שיש בו ו\"ד קו ושטח בהעלם ונעשה ה\"א ונקוד' די' עצמו למעלה מזה כו', כך הוא גם ברצון הפשוט שהוחלט בעצמו' ממש שנשאר ממנו רק כי'<sup data-n=\"7229\">77</sup> שהוא ודאי גבוה הרבה מן בחי' טעם כמוס ונעלם לרצון הפשוט עצמו שבלתי מורכב אפי' בטעם כמוס כי אין טעם לרצון כלל<sup data-n=\"7230\">78</sup> שמתפשט בקו ושטח דו\"ד להיות",[["7225","73","<b>לפ\"ז</b>: ד: מכ\"ז יובן."],["7226","74","<b>שעשועי המלך</b>: נסמן לעיל פ' בא צב, ד."],["7227","75","<b>ששיער בעצמו בכח</b>: נסמן לעיל קב, א."],["7228","76","<b>הקו\"ח. . ומתעגל</b>: נסמן לעיל פ' שמות כט, א."],["7229","77","<b>כי'</b>: כיו\"ד. ג: כו'. ד: כנקודה."],["7230","78","<b>אין טעם לרצון כלל</b>: נסמן לעיל פט, ד."]]],[2300540335,"בטעם כמוס עכ\"פ בה\"א ראשונה שהוא חקיק'<sup data-n=\"7231\">79</sup> בטה\"ע כנ\"ל, ואחר ה\"א זה שעדיין הוא בכח והעלם מתפשט בבחי' קו ממש ומשם מקור לחיות<sup data-n=\"7232\">80</sup> כל בנין עולם אצי' ונק' חי העולמים כנ\"ל, ונעשה בבנין התפשטו' או\"כ בגילוי מע\"ס דא\"ק שנק' מח' הקדומה<sup data-n=\"7233\">81</sup> בחי' טה\"ת<sup data-n=\"7234\">82</sup> מח' הכללי' דפרט המוגבל כנ\"ל. וזהו ד' אותיות דשם הוי' הא' שבהעלם הרצון בכלל, הי' היינו כשעלה ברצונו הפשוט צמצם כל עצמו כנקודה די' זה טרם שיוכל להיות <span data-k=\"pg\">424</span> ּ התפשטות הרצון בטעם כמוס כנ\"ל ואח\"כ עלה ברצונו זה בהתפשטו' אורך ורוחב הה\"א ואח\"כ להיות נמשך הרצון למטה ממש נעשה נקודה וקו בוי\"ו להיות שטח דה\"א במקבלים כנ\"ל וד\"ל.\n<b>וזהו</b> שם הוי' שברצון העליון בכללות (אך גם בחי' רצון המוחלט עצמו שנק' רצון הפשוט שכלול בפשיטו' דעצמו' אוא\"ס ממש גם הוא עלה מן ההעלם שבעצמו' להתעורר ולבא לגילוי כמו שאדם שהי' לו רצון המוחלט שנשאר כלול בעצמותו ממש ונתעורר לבא לגילוי שהוא הנק' עליי' שעלה ברצונו הפשוט כו', וכן מ\"ש בריש הורמנא כו', אבל עצמות רצון הפשוט כמו שהוא הי' בעצמות ממש זהו למעלה משם הוי' דכתר שהוא הרצון<sup data-n=\"7235\">83</sup> (והוא נק' שם אהי' אנא זמין לאתגלאה<sup data-n=\"7236\">84</sup> מן ההעלם להיות בשם הוי' בהעלם ובגילוי ואהי' אשר אהי' ב\"פ בימות המשיח ועוה\"ב<sup data-n=\"7237\">85</sup>, והוא ענין הפנימי' דרצה\"ע שבתו\"מ שלמעלה גם ממקור הרצון וחכ' דמע\"ב וכמא' בראשית בשביל התורה שנק' ראשית<sup data-n=\"7238\">86</sup> כו', דגם בחי' מא' סתום דרצון דמע\"ב שבא מהעלם דרצון הפשוט כנ\"ל הי' רק בשביל רצון וחכ' דתו\"מ דוקא שהוא שם אהי' דאנא זמין לאתגלאה בימוהמ\"ש בטעמי מצות שנק' טעם כמוס לרצון העצמי הזה ואשר אהי' בעוה\"ב שהוא גילוי עצמו' הרצון הפשוט שבתו\"מ דוקא שלמעלה גם מטעמי מצות די' דחכ' הקדומה דתוה\"ק כו', וז\"ש עד יעבור עמך הוי'<sup data-n=\"7239\">87</sup> דתו\"מ עם זו קנית<sup data-n=\"7240\">88</sup> בעוה\"ב כו' וד\"ל) (והענין הוא דגם רצון הפשוט טרם שעלה בגילוי והי' כלול בעצמו' ונק' רצון המוחלט כנ\"ל ה\"ז רק ענין מקור ראשון לרצון למע\"ב כמו הרצון המוחלט לבנות בנין וכה\"ג שאינו בבחי' פנימי' ועצמו' כ\"כ רק שיש חסד הפשוט ועצמי ברצון פשוט זה כמ\"ש כי אמרתי עולם חסד יבנה<sup data-n=\"7241\">89</sup>, וזהו בחי' חפץ חסד שמצד עצמו ומתגלה בחסד דרצון וחכ' דמע\"ב כנ\"ל, אבל עצמות רצונו הפשוט שבמצות ששרשן בעצמותו ממש כמ\"ש רחבה מצותך מאד<sup data-n=\"7242\">90</sup> ונק' אורחותיך<sup data-n=\"7243\">91</sup> ממש וכמו ה' מניח תפילין<sup data-n=\"7244\">92</sup> ומתעטף בציצית<sup data-n=\"7245\">93</sup> וכה\"ג שנק' מצותי<sup data-n=\"7246\">94</sup> ממש זהו בבחי' קדושה הפנימי' ועצמ[י'] שאין גם לרצון הפשוט ומוחלט דמע\"ב",[["7231","79","<b>חקיק'</b>: ד: חקיקו' האותיו'."],["7232","80","<b>לחיות</b>: ד: להיות."],["7233","81","<b>דא\"ק שנק' מח' הקדומה</b>: ראה מאמרי אדה\"א דברים ח\"ג ס\"ע תתפז ואילך ובהנסמן שם ובע' תתפח."],["7234","82","<b>דא\"ק שנק'. . טה\"ת</b>: ראה הערה בסה\"מ תרנ\"ט ע' עז."],["7235","83","<b>דכתר שהוא הרצון</b>: נסמן לעיל פ' וארא עט, א."],["7236","84","<b>אהי' אנא זמין לאתגלאה</b>: שמות ג, יד. ראה זהר ויקרא יא, א. אחרי סה, ב."],["7237","85","<b>ואהי'. . בימות המשיח ועוה\"ב</b>: נסמן לעיל א, ב."],["7238","86","<b>בראשית בשביל התורה שנק' ראשית</b>: נסמן לעיל פא, ג."],["7239","87","<b>עד יעבור עמך הוי'</b>: בשלח טו, טז [בדילוג]."],["7240","88","<b>עם זו קנית</b>: ד: עד יעבור עם זו כו' עלי' הב'."],["7241","89","<b>כי אמרתי עולם חסד יבנה</b>: תהלים פט, ג."],["7242","90","<b>רחבה מצותך מאד</b>: תהלים קיט, צו."],["7243","91","<b>אורחותיך</b>: תהלים קיט, טו."],["7244","92","<b>ה' מניח תפילין</b>: ראה גם לעיל פ' וארא נו, ד. וש\"נ."],["7245","93","<b>ומתעטף בציצית</b>: נסמן לעיל ז, ד."],["7246","94","<b>מצותי</b>: תולדות כו, ה. ראה גם הנסמן במאמרי אדה\"א דברים ח\"א ע' סד."]]],[2300540358,"ערוך אליו כלל, עד שכל הרצון וחכ' דמע\"ב הי' רק בשביל גילוי פנימי' ועצמ[י'] דרצונו העצמי שבתו\"מ בעוה\"ב כמ\"ש ה' קנני ראשית דרכו<sup data-n=\"7247\">95</sup> כו' וכתיב אם לא בריתי<sup data-n=\"7248\">96</sup> כו' חוקות שמים כו' שציוה ברצונו המוחלט לא שמתי כו' כידוע, וזהו שם אהי' אנא זמין כו' כנ\"ל. דאע\"פ שיש גם שם הוי' בתו\"מ ונק' תורת הוי' ומצות הוי' היינו לפי שגם בחי' רצה\"ע שבפנימי' בתו\"מ גם זה יורד ע\"י ד' אותיות דצמצום והתפשטות והמשכה והתפשטות שמאחר שנק' בחי' שפע עכ\"פ למקבלים כו', וע\"כ יש בתו\"מ נסתרות לה' אלקינו בבחי' עלמא דאתכסייא בי\"ה דשם הוי' בתו\"מ והנגלות לנו כו' בו\"ה וכללותם אנכי הוי' אלקיך כו' אלקיך דוקא בבחי' פנימי' ועצמו' השפע לכנ\"י לבד כמו שיש שם הוי' בבחי' חיצוני' השפע דרצון וחכ' גם במקורם ברצון המוחלט כו', דגם שהי' הוא ושמו בלבד<sup data-n=\"7249\">97</sup> ואמנם זהו שמו גימ' רצון<sup data-n=\"7250\">98</sup> הוא רצון המוחלט ונעלם בעצמו' טרם שעלה ברצונו להאציל ולברוא כו', אבל שמו גימ' רצון העצמו' ממש זהו רצון הפשוט ועצמי שבתו\"מ שהי' כלול בשעשועי המלך <span data-k=\"pg\">ריב</span> ּ בבחי' פנימי' ועצמו' שלו ממש שהוא השם העצמי שלמעלה משם התואר והפועל כמ\"ש ושמי הוי' לא נודעתי כו', אע\"פ שיש בזה שם הוי' אבל הוא שמי הוי' ממש, ולמעלה מזה שם אהי' דאנא זמין לאתגלאה בימוהמ\"ש והעוה\"ב כנ\"ל, ובמ\"ת לא הי' נגלה רק שם הוי' דתו\"מ מאנכי סדכ\"ס שבהעלם עצמו' הרצון דתו\"מ כו', והיינו ג\"כ שם הוי' שא' הוי' אלקי אבותיכם שלחני<sup data-n=\"7251\">99</sup> כו' זה שמי לעולם כו' בחי' שם הוי' הפנימי' דתו\"מ ברוחניות שנודע גם לאבות שקיימו כל התו\"מ ברוחניות<sup data-n=\"7252\">100</sup> רק תו\"מ בגשמיות דסוף מעשה הוא שעבמ\"ת לרצון דתו\"מ ברוחניות לא נודעתי כו' כמ\"ש במ\"א וד\"ל. וז\"ש אשר אהי' בעוה\"ב בשכר המצות בגשמיות שז\"ש עם זו קנית כנ\"ל (וז\"ש יהא שמי' רבא<sup data-n=\"7253\">101</sup> שהוא שם העצם דרצון המוחלט שבתו\"מ שעתיד להגלות בעוה\"ב וכן ברוך אתה הוי' וכה\"ג, ומ\"ש ויקרא הוי' הוי' היינו משם הוי' העצמי שברצון העצמי שלמעלה גם מרצון וחכ' דתו\"מ שנק' רעוא דכ\"ר<sup data-n=\"7254\">102</sup> לסליחת העוונות שיתגלה זה לעוה\"ב שהוא למעלה מן המצות שנא' בו חנם בלא מצות<sup data-n=\"7255\">103</sup> רק יהי' בא מצד שכר הבירורי' דתומ\"צ בעוה\"ז וזהו ביו\"כ דוקא שהוא מעין העוה\"ב<sup data-n=\"7256\">104</sup> שנא' שם נשמחה בו<sup data-n=\"7257\">105</sup> ממש כמשי\"ת. ובדרך כלל עכ\"פ יובן שיש ב' מדרגות בשם הוי' עצמו בחי' י\"ה בבחי' עלמא דאתכסייא שהוא שם הוי' שברצון ומח' סתימאה ונק' שם הוי' בהעלם, והב' שם הוי' בגילוי להיות התהוות העולמות שנק' עלמא דאתגלייא להאציל ולברוא כו', והיינו ענין ב' מיני רצון הנ\"ל רצון המוחלט ורצון הב' בגילוי בחכ' ומדות והיינו בב' מדריגות ג\"כ בחיצוני' לרצון וחכ'",[["7247","95","<b>ה' קנני ראשית דרכו</b>: משלי ח, כב."],["7248","96","<b>אם לא בריתי</b>: ירמי' לג, כה."],["7249","97","<b>שהי' הוא ושמו בלבד</b>: נסמן לעיל נג, ב הערה 6."],["7250","98","<b>שמו גימ' רצון</b>: ראה מאמרי אדה\"ז תקס\"ד ע' רלו בשם הפרדס. פע\"ח (שער הק\"ש) ש\"ח, ספכ\"ח. מאמרי אדה\"א דברים ח\"ב ע' שסח. וש\"נ."],["7251","99","<b>ה' אלקי אבותיכם שלחני</b>: שמות ג, טו [בדילוג]."],["7252","100","<b>לאבות. . התו\"מ ברוחניות</b>: נסמן לעיל פ' וארא סג, ג."],["7253","101","<b>יהא שמי' רבא</b>: נוסח הקדיש."],["7254","102","<b>רעוא דכ\"ר</b>: נסמן לעיל פ' שמות ה, ג."],["7255","103","<b>לעוה\"ב. . חנם בלא מצות</b>: נסמן לעיל א, ב הערה 23."],["7256","104","<b>ביו\"כ. . מעין העוה\"ב</b>: נסמן לעיל פ' וארא עה, ד."],["7257","105","<b>שם נשמחה בו</b>: תהלים סו, ו."]]],[2300540380,"דמע\"ב ובפנימי' השפע בתו\"מ דמ\"ת ובהעלם דעצמו' הרצון שיהי' בגילוי לעוה\"ב כנ\"ל וד\"ל.\n<b>ואחר</b> כל הנ\"ל יובן מ\"ש וירא ישראל את היד הגדולה אשר עשה הוי' במצרים כו', דהנה כתיב כימי צאתך מאמ\"צ<sup data-n=\"7258\">106</sup> אראנו נפלאות לע\"ל שזהו שא' שמזכירים יצ\"מ גם לימות המשיח וגם לעוה\"ב שנא' למען תזכור<sup data-n=\"7259\">107</sup> כו' כל ימי חייך כו', והענין הוא דמה שיהי' לע\"ל בא בגילוי מהעלם דעצמות רצונו העצמי שבתו\"מ שנק' נפלאות ב'<sup data-n=\"7260\">108</sup> מהעלם שאחר ההעלם דעצמו' ממש כנ\"ל שז\"ש אהי' אשר אהי' כו' זה הי' ביצ\"מ שנגלה עליהם מלך מלכי כו' בכבודו ובעצמו<sup data-n=\"7261\">109</sup> והוא מה שראו את היד הגדולה למטה ממש אשר עשה הוי' במצרים דוקא בשעת קי\"ס כו'. דהנה מבואר למעלה שיש ב' מדרגות בהוי' א' בבחי' העלם הרצון העליון ומח' סתימאה שבא ג\"כ כסדר ד' אותיות דהוי' מעצמות רצון המוחלט ע\"י צמצום ביו\"ד וה\"א התפשטות כו', שזהו בחי' פנימי' הכתר בכלל, והב' שם הוי' שבא בגילוי ממש להיות התהוות ד' עולמות עולם האצי' מעצמות המאציל ומאצי' לבריאה כו' כנ\"ל. והנה בחי' פרעה למעלה היינו בחי' חיצוניות ואחוריי' דרצון העליון בחי' עורף<sup data-n=\"7262\">110</sup> כידוע שיש לו שם יניקה ושרש באחוריים דכתר דאצי' שזהו אחוריים דשם הוי' דאצי' בכלל, מאחר שגם בחי' האצי' בא בדרך שפע ע\"י צמצום והתפשטות כנ\"ל יש בזה ג\"כ חיצוניות דחיצוניות כו' וכ\"ש מאצי' לבי\"ע, אבל בשם הוי' <span data-k=\"pg\">426</span> ּ דפנימית הכתר שהוא בחי' העלם הרצון דעצמות המאציל כשעלה ברצונו הפשוט להאציל כו' שהי' כלול בעצמו' המאציל ממש ולא נתגלה לבא למטה בד' אותיות דהוי' דאצי' עדיין שם לא הי' לפרעה העליון שום שרש ויניקה כלל מאחר שהוא בהעלם העצמו' דרצון המאציל ולא נתגלה למטה בפועל ההתהוות דאצי' רק הוא בכח והעלם (ששיער בעצמו כנ\"ל), וע\"כ אמר פרעה שלמטה מי הוי' אשר אשמע בקולו כו' לא ידעתי את הוי'<sup data-n=\"7263\">111</sup> כו', כי משה ואהרן אמרו לו כה אמר הוי' אלקי ישראל<sup data-n=\"7264\">112</sup> כו' שזהו בחי' פנימי' דשם הוי' שבהעלם הרצון העליון כנ\"ל שלא הי' לפרעה שם ידיעה כלל כי אין לו שרש שם זה<sup data-n=\"7265\">113</sup> כלל רק בשם הוי' דלתתא שנמשך מן המאציל לאצי' כנ\"ל, וע\"כ לא האמין כלל בשם הוי' זה הנעלם שברצון העליון שבפנימי' הכתר בכלל שנק' הוי' אלקי ישראל דוקא והוא שם הוי' אלקי אברהם כו' כנ\"ל, ולזה א[מר] מי הוא זה שם הוי' זה אשר אשמע בקולו לא ידעתי את הוי' כו' כי רק בשם הוי' דלתתא שבא בגילוי מן ההעלם דרצה\"ע דכתר הי' יודע מצד שרש אחיזתו באחוריי' ועורף דכ\"ע כנ\"ל ולא בשם הוי' דלעילא זה כו' וד\"ל (וזהו שקודם הי' מכות א[מר] וידעו",[["7258","106","<b>כימי צאתך מאמ\"צ</b>: מיכה ז, טו."],["7259","107","<b>שמזכירים יצ\"מ. . למען תזכור</b>: נסמן לעיל פ' בא קיא, ד הערה 617."],["7260","108","<b>נפלאות ב'</b>: נסמן לעיל פ' שמות כא, א."],["7261","109","<b>שנגלה עליהם. . בכבודו ובעצמו</b>: נסמן לעיל פ' בא קט, ג."],["7262","110","<b>פרעה. . עורף</b>: נסמן לעיל יט, ב."],["7263","111","<b>מי הוי'. . לא ידעתי את הוי'</b>: שמות ה, ב."],["7264","112","<b>כה אמר הוי' אלקי ישראל</b>: שמות ה, א."],["7265","113","<b>שרש שם זה</b>: ד: שם שרש. ואוצ\"ל: שרש בשם זה."]]],[2300540400,"מצרים<sup data-n=\"7266\">114</sup> כי אני הוי' כו' כי שרש אחיזתם בחיצוני' ואחוריים דשם אלקי' שמסתיר על שם הוי' ע\"כ לא נודע להם שם הוי' העליון הנ\"ל כלל, כידוע שיש בחי' פרסא המפסיק בין פנימי' הכתר שנק' קדה\"ק לחיצוניות הכתר שהוא הרצון הבא בגילוי בשם הוי' דאצי' ומאצי' לבי\"ע, וגם לישראל הי' שם הוי' זה העליון דפנימי' הכתר רק בבחי' אמונה בהעלם שלמעלה מן השכל כשא' להם משה הוי' אלקי אבותיכם כו', אך ורק בקי\"ס דוקא הוא שראו בראי' מקרוב לשם הוי' זה העליון כמ\"ש וירא ישראל כו' כמשי\"ת וד\"ל.\n<b>והנה</b> בשעת קי\"ס ראו ישראל והשיגו בבחי' שם הוי' זה העליון שברצון העליון בהעלם שהוא למעלה משם הוי' הבא בבחי' מקור להשתלשלו' דאבי\"ע כנ\"ל, וז\"ש וירא ישראל כו' אשר עשה הוי' במצרים בחי' הוי' העליון הזה שלא הי' אצלם תחלה רק בבחי' ההעלם באמונה כו' עתה ראו בראי' והשגה מקרוב למטה ממש והוא אשר עשה הוי' דוקא במצרים כו'. ובאמת ראו והשיגו ב' השגות זו למעלה מזו, הא' בבחי' שם הוי' שבהעלם הרצון העליון שנק' בחי' פנימי' הכתר כנ\"ל, והב' למעלה גם מזה והוא מה שיכולים לעשות לשם הוי' זה שברצון הנעלם מלמעלה מן הרצון (גם מרצון המוחלט כמו שאו' יהי רצון מלפניך<sup data-n=\"7267\">115</sup> כו' שהרצון אינו אלא בחי' ההמשכה מן העצמו' שזהו בחי' דבר התפשטו'<sup data-n=\"7268\">116</sup> מה ואינו אלא חלק קטן מן העצמו' כו'), והיינו ע\"י מעשה התחתוני' באתעדל\"ת בסו\"מ וע\"ט בשס\"ה ל\"ת ורמ\"ח מ\"ע<sup data-n=\"7269\">117</sup> שעושים בזה התעוררו' העצמות דא\"ס ב\"ה להמשיך שם הוי' העליון הזה שברצון הנעלם (וכמ\"ש בע\"ח שבתחלת ההשתל' הי' ההתעוררות בעצמו' הא\"ס לצמצם אורו ולהיות מקור להשתלשלו' העולמות <span data-k=\"pg\">ריג</span> ּ מצד שהוא חפץ חסד בעצמו שטבע הטוב להטיב<sup data-n=\"7270\">119</sup> ע\"כ עלה ברצונו הפשוט כו' ואח\"כ תלוי במעשה התחתונים<sup data-n=\"7271\">118</sup> ), ובחי' השגה זו למעלה מראי' והשגה דשם הוי' שכבר נמשך ברצון ולזה א[מר] אשר עשה הוי' במצרים בקי\"ס דוקא שהוא מעין דלע\"ל דכתיב הפך ים ליבשה<sup data-n=\"7272\">120</sup> כו' שם נשמחה בו ממש שהוא העוה\"ב.\n<b>והענין</b> הוא כידוע דבמצרים היו ישראל בתכלית השפלות ומרירות והי' להם לב נשבר ונדכה באמת מקושי השעבוד בחומר ובלבנים ויצעקו אל ה' בצר להם<sup data-n=\"7273\">121</sup> בתשובה שלימה מן המיצר והדוחק כו' עד שהיו בתכלית הביטול בנפשם להיות סו\"מ בתכלית ולא נשתקעו בנש\"ט דמצרים כלל ומזה הי' להם הכח לקבלת התו\"מ במ\"ת להיות סו\"מ בשס\"ה ל\"ת",[["7266","114","<b>וידעו מצרים</b>: וארא ז, ה."],["7267","115","<b>שאו' יהי רצון מלפניך</b>: בברכות השחר. ועוד."],["7268","116","<b>דבר התפשטו'</b>: ג: התפשטו' דבר. ד: התפשטו'."],["7269","117","<b>בשס\"ה ל\"ת ורמ\"ח מ\"ע</b>: מכות כג, סע\"ב."],["7270","119","<b>בע\"ח. . שטבע הטוב להטיב</b>: נסמן לעיל פ' שמות לד, ג."],["7271","118","<b>בע\"ח שבתחלת. . במעשה התחתונים</b>: ראה שם (שער דרושי נקודות) ש\"ח, ספ\"ו. הנסמן במאמרי אדה\"א בראשית ע' תקסו."],["7272","120","<b>הפך ים ליבשה</b>: תהלים סו, ו."],["7273","121","<b>ויצעקו אל ה' בצר להם</b>: תהלים קז, ו. כח."]]],[2300540420,"שכלולים בלא יהי' לך כו', וכן היו מוכנים בנפשם לבחי' ועשה טוב לקיים רצון העליון במ\"ע במ\"ת בשמעם אנכי<sup data-n=\"7274\">122</sup> כו', וזהו ענין שם הוי' שנעשה למטה ע\"י סו\"מ וע\"ט דל\"ת ומ\"ע בכל דור <sup data-n=\"7275\">123</sup>כו' בחי' היו\"ד למטה הוא ענין הצמצום אשר האדם מצמצם א\"ע וכובש יצרו ומבטל רצונו מפני רצון ה' וגזירתו להיות סו\"מ בל\"ת, שזהו בחי' ביטול עצמותו בתכלית ע\"י כפיה שכופה לבבו ומבטל תאוות יצרו לגמרי שהוא כמו נקודה די' שהוא ענין הצמצום למעלה כנ\"ל (וכן ע\"י השפלות והכנעה במרירות כעני ודל בתשובה מן המיצר בתכלית שצר לו מח\"נ כו', כמו במצרים שמפני זה נק' לחם עני<sup data-n=\"7276\">124</sup> ואו' הא לחמא עניא די ביו\"ד<sup data-n=\"7277\">125</sup>, וכה\"ג א' בזהר ע\"פ שחורה אני כו' בגלותא דאזעיר' גרמה<sup data-n=\"7278\">126</sup> ואתעבידת כנקודה חדא כו'), ואח\"כ מן הצמצום הזה נעשה בחי' התפשטות אורך ורוחב שהוא הה\"א דשם הוי' כנ\"ל. וזהו במעשה המצות שהן בחי' גילוי התפשטות רצה\"ע באורך ורוחב כמו רחבה מצותך מאד כו' ברצה\"ע שבמצות תפילין וציצית ושבת וכה\"ג ובצדקה וגמ\"ח יש התפשטות יותר מפני שזהו בחי' חסד עליון, וגם בת\"ת שהוא ביו\"ד<sup data-n=\"7279\">127</sup> נעשה התפשטות רצה\"ע בגילוי הדיבור באיכות רצה\"ע בכל מצוה ומצוה שלומד כו', והעיקר הוא במצות ת\"ת הוא הוי\"ו שהוא בחי' המשכה בקול<sup data-n=\"7280\">129</sup> הדיבור<sup data-n=\"7281\">128</sup>, וה\"א האחרונה דשם הוי' הוא בחי' התפשטו' ממש דרצה\"ע בפו\"מ במעשה זאת דכל מצוה בעשותה שמתפשטת אור האלקי דרצה\"ע לשכון למטה בדבר מעשה זו שנעשה בחי' כלי לשכון בו אור ה' ונק' מצות הוי' ממש, וכידוע דמטעם זה נק' רמ\"ח פקודין רמ\"ח אברים דמלכא<sup data-n=\"7282\">130</sup> כאברי האדם שהן בבחי' התפשטות כו' או כמשל הנר לאור כמ\"ש כי נר מצוה<sup data-n=\"7283\">131</sup> כו' וד\"ל.\n<b>ונמצא</b> עכ\"פ נעשה שם הוי' למטה ע\"י מעשה המצות בגשמיות בסדר ד' אותיות די' וה\"א<sup data-n=\"7284\">132</sup> כו' שזהו בחי' צמצום והתפשטות והמשכה והתפשטות וע\"כ ע\"י אתעדל\"ת זו למטה שהוא בבחי'<sup data-n=\"7285\">133</sup> רצה\"ע שנעשה שם הוי' דלעילא בזה ממש בבחי' העלם דרצה\"ע הפנימי' ועצמיות הנ\"ל מלמעלה למטה, והיינו להיות נמשך מהעלם עצמו' המאציל צמצום הראשון להיות עולה ברצונו להאציל ואח\"כ גילוי התפשטות דרצון באורך ורוחב דה\"א כו' כנ\"ל שזהו ג\"כ ענין ד' אותיות הללו דהוי' יו\"ד בחי' צמצום העצמו' בתחלה כו' (והיינו בבחי' פנימי' השפע דתו\"מ שמזה נעשה <span data-k=\"pg\">428</span> ּ מקור להמשכות הרצון וחכ' דרצון המוחלט למע\"ב כנ\"ל). וז\"ש אשר עשה בחי' הוי' דלעילא בהעלם רצה\"ע דמצות שהן פנימי' רצה\"ע במצרים דוקא ע\"י אתעדל\"ת דמיצר וצמצום בסו\"מ והתפשטות דמ\"ע כו' לפי שבמצרים הי'",[["7274","122","<b>בשס\"ה ל\"ת. . בלא יהי'. . במ\"ע. . אנכי</b>: נסמן לעיל פ' שמות יז, ג הערה 722."],["7275","123","<b>כו'</b>: ד: כי."],["7276","124","<b>לחם עני</b>: פ' ראה טז, ג. פסחים קטו, סע\"ב."],["7277","125","<b>הא לחמא עניא די ביו\"ד</b>: נסמן לעיל פ' בא קא, ב."],["7278","126","<b>שחורה אני. . דאזעיר' גרמה</b>: נסמן לעיל פ' בא קטו, ב."],["7279","127","<b>בת\"ת שהוא ביו\"ד</b>: ראה גם לקמן רכט, א. מאמרי אדה\"א שמות ח\"ב ע' תפג. וש\"נ. ש\"א לד, א. מ, א."],["7280","129","<b>בקול</b>: ד: בכלי."],["7281","128","<b>ת\"ת הוא הוי\"ו. . בקול הדיבור</b>: ראה גם שע\"ת עג, סע\"ב. מאמרי אדה\"א שם."],["7282","130","<b>רמ\"ח. . אברים דמלכא</b>: ראה גם מאמרי אדה\"ז תקס\"ה ח\"ב ע' תתעו. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380053\" data-slug=\"likkutei-torah\" data-id=\"4001380053\">לקו\"ת פקודי ג, ב</a> ואילך. הנסמן לעיל פ' שמות מו, ב."],["7283","131","<b>כי נר מצוה</b>: משלי ו, כג."],["7284","132","<b>די' וה\"א</b>: ד: דשם הוי'."],["7285","133","<b>שהוא בבחי'</b>: ד: נעשה אתעדל\"ע למעלה שהוא למעלה מבחי'."]]],[2300540440,"התחלת שרש ענין המיצר וצמצום שלמטה להיות כח בכנ\"י לכבוש רצונם בסו\"מ, וידוע ששרש הל\"ת בי\"ה שלמעלה ממ\"ע שהן בו\"ה כמא' שמי עם י\"ה שס\"ה ל\"ת וזכרי עם ו\"ה רמ\"ח מ\"ע<sup data-n=\"7286\">134</sup> כו' משום דבחי' הלאו דל\"ת בשב ואל תעשה לכבוש ולבטל רצון זר גבוה יותר מבחי' הן דקיום רצה\"ע במ\"ע כמבואר הטעם במ\"א (בפ' פקודי<sup data-n=\"7287\">135</sup> ), וא\"כ העיקר מה שממשיכי' לשם הוי' שברצה\"ע בא תחלה מן המיצר וצמצום שמצמצם אדם לבטל רצונו בסו\"מ שהוא הלאו שקודם להן. וכך גם למעלה הוא יו\"ד שקודם לה\"א ובכלל י\"ה קודם לו\"ה כנ\"ל (וטעם לזה הוא מפני שמן המיצר העולה למעלה הוא בבחי' או\"ח חוזר לקדמותו<sup data-n=\"7288\">136</sup> ממש שהוא לעורר גם לרצון הפשוט שבעצמו' <sup data-n=\"7289\">137</sup>ממש (וכמ\"ש במ\"א ע\"פ הרא[י]ני את מראיך<sup data-n=\"7290\">138</sup> שבבחי' או\"ח הכתר קודם לבא שהוא קוצו ש\"י כו'). אך מ\"ש אשר עשה הוי' במצרים בקי\"ס דוקא, הענין הוא דגם שהעיקר של המיצר ודוחק הי' במצרים כנ\"ל, אבל בחי' גילוי אור דשם הוי' שנעשה למעלה עי\"ז בהעלם דפנימי' רצה\"ע הוא שראו והשיגו בקי\"ס דוקא לפי שהוא מעין דלע\"ל בעוה\"ב שא' שם נשמחה בו ממש כמ\"ש במ\"א (וית' בסמוך), וזהו וירא ישראל כו' שראו בקי\"ס בראיה והשגה מקרוב לשם הוי' העליון הזה שנעשה ע\"י אתעדל\"ת במצרים דוקא מטעם הנ\"ל וד\"ל. וזהו כימי צאתך מאמ\"צ אראנו נפלאות לע\"ל בימות המשיח והעוה\"ב, וע\"כ מזכירים יצ\"מ גם לע\"ל כנ\"ל לפי שביצ\"מ הי' התחלת אתעדל\"ת לעשות לשם הוי' בביטול הרצון בתכלית בסו\"מ וקיום רצה\"ע בוע\"ט כנ\"ל, עד שזהו יהי' יסוד חזק גם לגילוי אור דהוי' לע\"ל ממקורא דכולא שהוא מ\"ש אהי' אשר אהי' כו' שזהו התגלות פנימי' ועצמו' דרצה\"ע בטעם כמוס דמצות בימות המשיח ולמעלה מזה בעוה\"ב כנ\"ל, וז\"ש אראנו נפלאות אראנו כמו שהוא למעלה בסדכ\"ס אשר ראו זה בקי\"ס למטה אשר עשה הוי' במצרים כנ\"ל וע\"כ א' כימי צאתך מאמ\"צ דוקא אראנו משום דהיינו הך והא בהא תליא וז\"ש עד יעבור עם זו קנית בעוה\"ב כנ\"ל וד\"ל.\n<b>אך</b> הנה לפ\"ז עדיין יש להבין מ\"ש וירא ישראל את היד הגדולה כו', מהו היד הגדולה הזאת, ומה זה ענין למ\"ש אשר עשה הוי' שזהו בחי' הוי' העליון שברצון שהוא נק' יד הגדולה אשר עשה כו', וגם יש להבין דמשמע שזה שראו היד הגדולה היינו בקי\"ס דוקא והוא מ\"ש וירא ישראל את מצרים מת על שפת הים<sup data-n=\"7291\">139</sup> וירא ישראל כו'. אמנם הנה תחלה יש להבין",[["7286","134","<b>שמי עם י\"ה. . ו\"ה רמ\"ח מ\"ע</b>: נסמן לעיל פ' בא קיד, א."],["7287","135","<b>בפ' פקודי</b>: ראה לקמן תמב, סע\"ד ואילך. תנב, ד."],["7288","136","<b>או\"ח חוזר לקדמותו</b>: נסמן לעיל פ' שמות מ, סע\"ד."],["7289","137","<b>ממש</b>: אוצ\"ל: ממש)."],["7290","138","<b>הר א[י]ני את מראיך</b>: שה\"ש ב, יד. ראה מאמרי אדה\"ז תקס\"ו ע' קלה. לקו\"ת שה\"ש כ, ב."],["7291","139","<b>וירא ישראל. . שפת הים</b>: בשלח יד, ל."]]],[2300540460,"בשרש ענין קי\"ס, דהנה סיבת ענין קי\"ס מבואר למעלה במ\"ש ויט משה את ידו על הים ויולך ה' את הים ברוח קדים עזה כל הלילה וישם את הים לחרבה<sup data-n=\"7292\">140</sup> כו', ופי' לחרבה היינו לתכלית היבשות<sup data-n=\"7293\">141</sup> בלי לחלוחית מים כלל וכלל. והענין הוא כידוע בשרש בחי' ים ויבשה למעלה שזהו בחי' עדאת\"כ שנק' ים ועדאת\"ג נק' ארץ<sup data-n=\"7294\">142</sup>, וידוע מארז\"ל דכל מה <span data-k=\"pg\">ריד</span> ּ שיש ביבשה<sup data-n=\"7295\">143</sup> יש בים כו'. וביאור הדברים, הנה לכאורה יש להבין בענין קי\"ס זה שהי' נס נפלא גדול מה חידוש הי' בו הלא כבר הי' לעולמי' כן בתחלת הבריאה שא' יקוו המים<sup data-n=\"7296\">144</sup> מתחת השמים אל מקום א' ותראה היבשה הרי הארץ היתה מובלעת בתוך המים דתהום העליון שתחת השמים כמ\"ש ורוח אלקי' מרחפת ע\"פ המים<sup data-n=\"7297\">145</sup> שהי' רק מים בלבד וציוה ה' שיקוו המים כו' וירדו מלמעלה למטה לארץ (שגער בהן בנזיפה<sup data-n=\"7298\">146</sup> כמ\"ש במדרש) ותראה היבשה למעלה וכמ\"ש לרוקע הארץ על המים<sup data-n=\"7299\">147</sup> ולא נשאר שום לחלוחית מים בארץ<sup data-n=\"7300\">148</sup> וא\"כ מה זה החידוש שהי' בקי\"ס ששם הים לחרבה כו'. אך הנה ידוע דמה שהי' ענין ירידת המים עליונים למטה הוא כדי שתראה היבשה שמן היבשה יוכל להיות התהוות כל בריאה וכל הנמצאי' דצח\"מ הכל הי' מן הארץ דוקא כמ\"ש תדשא הארץ דשא<sup data-n=\"7301\">149</sup> כו' תוצא הארץ נפש חי'<sup data-n=\"7302\">150</sup> כו' עד שגם האדם מן עפר הארץ נברא<sup data-n=\"7303\">151</sup> כידוע. וז\"ש הכל הי' מן העפר<sup data-n=\"7304\">152</sup> דוקא וכמ\"ש בזהר דארץ אוליד' ועביד' פירין<sup data-n=\"7305\">153</sup> כו' (ולפי שבחי' התחדשות הבריאה יש מאין אינו אלא בארץ<sup data-n=\"7306\">154</sup> דוקא שמתחדשי' שם הד\"י מאין שאין זה בכח הים לפי שנתחב\"ס דוקא כמ\"ש במ\"א). אבל אם לא היו המ\"ע נקווי' למטה לא הי' יוצא מן המים כל מציאות דדצח\"מ מאין ליש בפו\"מ בגשמיות כלל (ועכ\"ז גם לאחר שהורדו המ\"ע למטה ונק' ימים<sup data-n=\"7307\">155</sup> הרי א' שיש כל הברואי' דדצח\"מ בים כמו שיש ביבשה וכידוע לפי שגם במ\"ע הי' הכל רק שהי' בבחי' הרוחניות בהעלם ולא בגילוי בגשמיות (וגם עכשיו כל מה שיש ברואי' בים אינם דומים לברואי' דיבשה כו'), ולכך א' יקוו המים כו' ותראה היבשה דהיינו שיתצמצמו ויתעלמו למקום א' ואז ותראה היבשה שיוכל להיות בחי' הגילוי דמציאות דצח\"מ וד\"י ארמ\"ע<sup data-n=\"7308\">156</sup> בארץ שתוציא הארץ כל הנמצאים ע\"י מא' האלקי כו' וד\"ל.\n<b>ודוגמא</b> כזאת הי' בבחי' ים ויבשה העליונים שנק' עלמא דאתכסיי' ועלמא דאתגלייא כנ\"ל עד שא' יקוו המים כו' כמו משל המח' והדיבור<sup data-n=\"7309\">157</sup> באדם למטה, שהמחשבה היא הכל",[["7292","140","<b>ויט משה את ידו. . לחרבה</b>: בשלח שם, כא."],["7293","141","<b>לחרבה היינו לתכלית היבשות</b>: ראה מכילתא כאן ובפי' זה ינחמנו. בדרושים שנסמנו בריש המאמר כאן."],["7294","142","<b>עדאת\"כ שנק' ים ועדאת\"ג נק' ארץ</b>: נסמן לעיל קלח, ג."],["7295","143","<b>דכל מה שיש ביבשה</b>: נסמן לעיל פ' שמות יח, ג."],["7296","144","<b>יקוו המים</b>: בראשית א, ט."],["7297","145","<b>ורוח אלקי' מרחפת ע\"פ המים</b>: בראשית שם, ב."],["7298","146","<b>שגער בהן בנזיפה</b>: נסמן לעיל פ' שמות כ, ב."],["7299","147","<b>לרוקע הארץ על המים</b>: תהלים קלו, ו."],["7300","148","<b>ולא נשאר שום לחלוחית מים בארץ</b>: ראה בסמוך (ריד, ב): שנשאר עכ\"פ מחלקי המים בארץ וא\"ל לא הי' צומח כלום."],["7301","149","<b>תדשא הארץ דשא</b>: נסמן להלן הערה 158."],["7302","150","<b>תוצא הארץ נפש חי'</b>: נסמן להלן הערה 159."],["7303","151","<b>האדם מן עפר הארץ נברא</b>: בראשית ב, ז."],["7304","152","<b>הכל הי' מן העפר</b>: קהלת ג, כ."],["7305","153","<b>דארץ אוליד' ועביד' פירין</b>: ראה זהר בהקדמה יב, א. בראשית מו, א."],["7306","154","<b>יש מאין אינו אלא בארץ</b>: ראה גם מאמרי אדה\"א במדבר ח\"ד ע' א'שצב ואילך. שה\"א נג, א ובהערה 7. פיה\"מ קיד, א. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300680178\" data-slug=\"torat-chaim\" data-id=\"2300680178\">תו\"ח ויגש רלב, ב</a>."],["7307","155","<b>המ\"ע. . ונק' ימים</b>: בראשית א, י."],["7308","156","<b>וד\"י ארמ\"ע</b>: נסמן לעיל פ' שמות ה, ד."],["7309","157","<b>עלמא דאתכסיי' ועלמא דאתגלייא. . המח' והדיבור</b>: נסמן לעיל פ' בשלח קמג, ד."]]],[2300540479,"בהעלם אע\"פ שמתחלקי' בה צירופי אותיות רבים ושונים ונמשך מבחי' ההעלם דמח' לגילוי באותיות הדיבור בלי שינוי כלל, רק שבמחשבה היו כל הצירופי' ברוחניות דהעלם המח' והן עצמן באי' בגילוי באותיות הדיבור שבאים במורגש בה\"מ הפה כידוע. אך הנה כל זמן שהמח' משוטטת לחשוב לעצמו לא יוכל לבוא בדיבור בגילוי רק כשמסלק המח' לצד א' אז יוכל להביא בגילוי בדבור עד שנראה הדיבור ליש ודבר בפ\"ע, אבל בעודנו טרוד בהעלם המח' אז הדיבור נכלל במחשבה ולא נגלה שום דבר למקבלים כלל כידוע. וכך הוא בים וארץ העליוני' שהן בחי' מו\"ד העליונים שכל מה שבא בבחי' צירופי אותיות הדיבור העליון נתהווה מזה כל הברואי' שבארץ ע\"י מא' ודיבור האלקי דייקא כמ\"ש ויאמר אלקי' תדשא הארץ<sup data-n=\"7310\">158</sup> וי\"א תוצא הארץ<sup data-n=\"7311\">159</sup> כו' ואם לא בחי' אותיות דבר הוי' זה לא הי' כח בארץ כלל להוציא הכל מאין ליש (משום דדבר מלך שלטון<sup data-n=\"7312\">160</sup> כו' כמ\"ש במ\"א), והן הי' מאמרות עד דגם אור ורקיע במא' <span data-k=\"pg\">430</span> ּ נבראו כמ\"ש ויאמר אלקים יהי אור<sup data-n=\"7313\">161</sup> ויהי אור ויאמר יהי רקיע<sup data-n=\"7314\">162</sup> כו' וכמ\"ש בדבר ה' שמים נעשו<sup data-n=\"7315\">163</sup> כו' והוא הנק' עלמא דאתגליא למעלה ומקבל מבחי' העלם המחשבה העליונה שנק' ים כמו שמן המח' נמשך לדיבור, אבל צריך שיקוו המ\"ע שהוא בחי' המח' ואז ותראה היבשה כו' בחי' הדיבור בגילוי כנ\"ל, וכל זמן שהמח' עליונה במקומה לא יוכל להיות בחי' הגילוי באותיות הדיבור העליון ולכך א' יקוו המים כו' וד\"ל. וכך יובן בבחי' העלם וגילוי דים ויבשה שהוא בחי' מו\"ד למעלה מעלה עד רום המעלות, הרי כל השתלשלות העולמות עליונים הכל הוא בא בבחי' העלם וגילוי כמו מו\"ד ע\"ד הנ\"ל דוקא, וכמו שהי' למטה בים ויבשה גשמיי' שא' יקוו המים בתחלה דוקא ואח\"כ ותראה היבשה מטעם הנ\"ל וד\"ל.\n<b>והנה</b> ע\"ד הנ\"ל בים ויבשה העליונים שהן כמו מו\"ד העלם וגילוי יש בחי' העלם וגילוי בכללות יותר והוא בחי' העלם הרצון (שנק' מח' סתימאה כמו אשר חשב שזהו רצון<sup data-n=\"7316\">164</sup> כידוע) שאינו בא בגילוי כלל אפי' בטעם ושכל כי אין טעם לרצון כנ\"ל כמו שרוצה אדם לבנות ולצייר שזהו רק בהעלם הרצון עדיין. וכך הוא בבחי' העלם דרצה\"ע למע\"ב כד סליק ברעותי' וכן כשעלה ברצונו הפשוט להאציל כו' וכת\"א בקדמין ברא כו' וכן ומקדם אשר לא נעשה<sup data-n=\"7317\">165</sup> כמ\"ש במ\"א והוא בחי' שם הוי' העליון הנ\"ל שנק' פנימי' הכתר וכאשר הוצרך לבוא בגילוי [להיות התהוות כל העולמות מאין ליש ע\"י ד' אותיות דשם הוי' דלתתא צריך שיהי' בחי' צמצום והסתלקות דרצה\"ע כמו שצ\"ל התעלמות והסתלקות המח' כשצריך לבא בגילוי] הדיבור כנ\"ל בפי' יקוו המים כו', וכמו שחושב לצייר",[["7310","158","<b>ויאמר אלקי' תדשא הארץ</b>: בראשית א, יא."],["7311","159","<b>וי\"א </b>[ ויאמר אלקים]<b> תוצא הארץ</b>: בראשית א, כד."],["7312","160","<b>דדבר מלך שלטון</b>: קהלת ח, ד. וראה גם לעיל פ' בא ק, ב."],["7313","161","<b>ויאמר אלקים יהי אור</b>: בראשית א, ג."],["7314","162","<b>ויאמר יהי רקיע</b>: בראשית א, ו [בדילוג]."],["7315","163","<b>בדבר ה' שמים נעשו</b>: תהלים לג, ו."],["7316","164","<b>אשר חשב שזהו רצון</b>: ירמי' מט, כ. נ, מה. אסתר ח, ג. ט, כה. ראה מאמרי אדה\"א דברים ח\"ב ע' שע. וש\"נ. שה\"א קד, א ובהערה 4. ש\"א פ, ב. שע\"ת קיז, ג. קכה, ב."],["7317","165","<b>ומקדם אשר לא נעשה</b>: ישעי' מו, י [ושם: נעשו]. ראה גם שעה\"י קיח, סע\"א. אמ\"ב שער הק\"ש כא, א. מאמרי אדה\"א דברים ח\"ד ע' א'שסה."]]],[2300540497,"הרי כשבא לצייר בפו\"מ מסתלק המח'<sup data-n=\"7318\">166</sup> רק נשאר רושם בעלמא לצייר כפי שעלה תחלה במח' כו', וכן<sup data-n=\"7319\">167</sup> מח' שבדבור כידוע) כנ\"ל בענין עדאת\"כ ועדאת\"ג במו\"ד וים ויבשה בפרטי' שהן ב' הויות דהעלם וגילוי העלם ברצון בחכ' וגילוי בדיבור<sup data-n=\"7320\">168</sup> בי\"מ בכללות יותר וד\"ל. אך הנה זהו כפי סדר ההשתל' דבחי' העלם וגילוי בפרט ובכלל כנ\"ל, אבל בקי\"ס חידוש גדול הי' בו ורבותא יתירה שלמעלה מסדר ההשתל' דכל העלם וגילוי דמע\"ב כי הרי א' הפך ים ליבשה כו' דהיינו שהים עצמו נהפך להיות במהות יבשה וכמ\"ש וישם את הים לחרבה שהים עצמו נעשה חרבה ויבשה בלי רושם לחלוחית מים [כלל] כנ\"ל, וזהו פלא גדול שלא הי' כן בתחלת הבריאה דגם שא' יקוו המים כו' הרי לא נשתנו מהות המ\"ע להיות נהפך ליבשה רק שירדו ונסתלקו וממילא נגלה היבשה כמו גילוי הדיבור שאחר הסתלקות והתעלמות המח' דוקא כנ\"ל, אבל בקי\"ס הי' היפוך הים שהוא בחי' ההעלם עצמו הוא שנהפך להיות בבחי' גילוי דיבשה כמו שיבא כל העלם המח' עצמה להיות בבחי' גילוי אותיות הדיבור בלי צמצום והסתלקות כלל בתחלה כו' וזה הי' בקי\"ס לפי שהוליך ה' ברוח קדים עזה כל הלילה בתחלה כו'. והענין הוא דגם בחי' העלם הרצה\"ע נהפך להיות הוא עצמו בבחי' גילוי ולא נשאר מבחי' ההעלם כלל (כמ\"ש וישם הים לחרבה ממש בלי לחלוחית מים כלל דגם חלקי המים שבארץ נתייבשו שלא הי' כן כמ\"ש<sup data-n=\"7321\">169</sup> יקוו המים כו' שנשאר עכ\"פ מחלקי המים בארץ וא\"ל לא הי' צומח מן הארץ כלום<sup data-n=\"7322\">170</sup> כו'), וזהו פלא יותר דגם שלא נקוו המים דים למטה כמו במא' יקוו המים כו' אלא הי' עומד במעמדו על הארץ כמ\"ש <span data-k=\"pg\">רטו</span> ּ והמים להם חומה<sup data-n=\"7323\">171</sup> כו' ונצבו כמו נד<sup data-n=\"7324\">172</sup> כו' ועכ\"ז נעשה דרך בים עצמו ביבישו' בלי לחלוחית מים כלל, וכל זה אות ומופת על בחי' שרש הים ויבשה שלמעלה שהוא בחי' ההעלם וגילוי בכללו' ובפרטות כנ\"ל שהי' למעלה מכפי ההשתלשלו' דהעלם וגילוי, עד שבחי' ההעלם עצמו דרצון ומחשבה נהפך להיות בבחי' הגילוי הכל עד שלא נשאר רשימו בעלמא מבחי' ההעלם דרצון ומח' הכללית ופרטי' כו' רק הכל בא בבחי' הגילוי דיבשה שנק' עד\"א<sup data-n=\"7325\">173</sup> כמו כל העלם הרצון ומחשבה שבא הכל בגילוי בדיבור כו' כנ\"ל, וזה הי' עיקר החידוש דנס דקי\"ס שהוא מעין דלע\"ל דוקא שע\"ז אמר בנהר יעברו ברגל שם נשמחה בו ממש כמשי\"ת וד\"ל.\n<b>אך</b> הנה זה גופא יש להבין איך היה יכול להיות בקי\"ס להפוך ים ליבשה להיות מבחי' ההעלם דרצון עצמו בחי' הגילוי אחר שאין זה כפי סדר ההשתל' דהעלם וגילוי כו', הנה לזה א' ויולך ה' ברוח קדים עזה<sup data-n=\"7326\">174</sup> כו' שהוא בחי' רוח קדמון",[["7318","166","<b>מסתלק המח'</b>: א: צריך שיסתלק המחשבה. ד: מסתלק המוחי'."],["7319","167","<b>וכן</b>: ד: ונק'."],["7320","168","<b>בחכ' וגילוי בדיבור</b>: ג: וחכ' וגילוי בדיבור. אד: וגילוי בחכ' ודיבור."],["7321","169","<b>כמ\"ש</b>: אד: במ\"ש."],["7322","170","<b>שנשאר עכ\"פ. . כלום</b>: ראה לעיל הערה 148."],["7323","171","<b>והמים להם חומה</b>: בשלח יד, כב. כט."],["7324","172","<b>ונצבו כמו נד</b>: שם טו, ח."],["7325","173","<b>עד\"א</b>: גד: עלמא דאתגלייא."],["7326","174","<b>ויולך ה' ברוח קדים עזה</b>: נסמן לעיל קמא, ג."]]],[2300540515,"מקדמונו ש\"ע<sup data-n=\"7327\">175</sup> שנק' רוח קדים עזה כמו ורוח אלקי' מרחפת ע\"פ המים שהוא למעלה מבחי' ההעלם וגילוי גם ברצון ומקור הרצון, עד שבחי' ההעלם עצמו נעשה גילוי כי בחי' העלם וגילוי לא שייך כ\"א בענין הצמצום והתפשטות שהוא כדי להשפיע לזולתו, אבל אור קדמון היינו האור דא\"ס עצמו כמו שהוא טרם ש[מ]תצמצם עצמו להיות בבחי' ההעלם שנק' חושך סתרו<sup data-n=\"7328\">177</sup> שעליו א' וגם חשך לא יחשיך<sup data-n=\"7329\">178</sup> ממך כחשיכה כאורה שגם בחי' החשך והעלם העליון נק' גילוי, וז\"ש בקי\"ס ויהי הענן והחשך<sup data-n=\"7330\">179</sup> ויאר את הלילה שהחושך וההעלם עצמו האיר את הלילה בבחי' גילוי אור כמ\"ש במ\"א. וזהו ענין בחי' רוח קדים העליון דמזרח שהוא עז וחזק מאד, דהיינו שכאשר האיר מעצמות רוח האלקי' שלמעלה מים הקדמוני<sup data-n=\"7331\">180</sup> הי' בכחו לעשות מהעלם דים העליון בחי' גילוי דיבשה כמ\"ש הים ראה בחי' רוח קדים זה וינוס<sup data-n=\"7332\">181</sup> שנעשה יבשה (וכמו שלמטה הרי טבע הרוח החזק לגבור על המים ההולכים בשאנן להחזירם לאחור בגלי הים שחוזרים לאחור מפני רוח סערה או לעלות הגלים למעלה ביותר ולהיפך ע\"י הרוח ישקיטם לנוח ולירד למטה כמ\"ש בשוא גליו אתה תשבחם<sup data-n=\"7333\">182</sup> וכתי' ויעבר רוח על הארץ<sup data-n=\"7334\">183</sup> וישוכו המים וכ\"ש שיש ביכולת רוח קדים להעמיד ולהציב למי הים כמו נד ולעשות דרך בים בחרבה שז\"ש ויבקעו המים, וכך הוא למעלה בבחי' רוח קדים דקדמונו ש\"ע שחזק הרבה יותר ממ\"ע דים הקדמוני ויכול לעשות הים לחרבה שזהו שבחי' העלם עצמו נעשה גילוי), (ורוח זה הוא בחי' רוח דחכמה דתורה הקדומה בבחי' הפנימי' כמו רוח חכ' שיהי' במשיח<sup data-n=\"7335\">184</sup> שיגלה טעמי תורה שע\"ז א' ורוח אלקים כו' זהו רוחו של משיח<sup data-n=\"7336\">185</sup> (כמו שהי' במ\"ת שהי' גילוי רוח ה' בקול השופר הולך וחזק<sup data-n=\"7337\">186</sup> כו'). וראי' מרוח נבואה שמביא כל העלם לגילוי כמו ואשפוך רוחי על כל בשר ונבאו בניכם<sup data-n=\"7338\">187</sup> כו' שגם שאין ערך לכלי הילדים קטנים לקבל בחי' גילוי אלקות כזה מ\"מ ע\"י הרוח האלקי יבא כל העלם לגילוי גם בנמוך ביותר, וכמו שבימות המשיח יהי' גילוי אלקות הנעלם בכל בשר וכמ\"ש ונגלה כבוד ה'<sup data-n=\"7339\">188</sup> וראו כל בשר וכתיב כולם ידעו אותי<sup data-n=\"7340\">189</sup> כו'. וכך הי' באדה\"ר ודורו[ת] שאחריו עד דור המבול <span data-k=\"pg\">432</span> ּ שא' לא ידון רוחי עוד<sup data-n=\"7341\">190</sup> כו', וכך הי' בקי\"ס שראתה שפחה על הים<sup data-n=\"7342\">191</sup> מה שלא ראה יחזקאל כו' מחמת עוצם גילוי ההעלם מרום המעלות שיורד לנמוך ביותר גם לשפחה כו' (וזהו טבע הרוח להיות מתפשט וגובר על כל מונע ומבדיל להיותו בא מבחי' העצמו' ממש ע\"כ מגלה כל העלם ואין מעצור לרוח כלל. ודוגמא כזו יש",[["7327","175","<b>ברוח קדים עזה. . מקדמונו ש\"ע</b>: נסמן לעיל קמג, ב."],["7328","177","<b>ש[מ]תצמצם. . חושך סתרו</b>: נסמן לעיל פ' בא קכג, ג."],["7329","178","<b>וגם חושך לא יחשיך</b>: נסמן לעיל פ' וארא סד, א."],["7330","179","<b>ויהי הענן והחשך</b>: נסמן לעיל קמג, ג."],["7331","180","<b>מים הקדמוני</b>: ראה גם שער האמונה לג, א. לעיל פ' שמות מד, א. וש\"נ."],["7332","181","<b>הים ראה. . וינוס</b>: תהלים קיד, ג."],["7333","182","<b>בשוא גליו אתה תשבחם</b>: תהלים פט, י. ראה גם ד\"ה זה במאמרי אדה\"ז תקס\"ג ח\"ב ע' תשלד."],["7334","183","<b>ויעבר רוח על הארץ</b>: נח ח, א [בדילוג]."],["7335","184","<b>רוח חכ' שיהי' במשיח</b>: ישעי' יא, ב."],["7336","185","<b>ורוח אלקים. . רוחו של משיח</b>: נסמן לעיל פ' שמות מז, ב."],["7337","186","<b>בקול השופר הולך וחזק</b>: יתרו יט, יט."],["7338","187","<b>ואשפוך רוחי. . בניכם</b>: נסמן לעיל כב, ג."],["7339","188","<b>ונגלה כבוד ה'</b>: ישעי' מ, ה."],["7340","189","<b>כולם ידעו אותי</b>: ירמי' לא, לג."],["7341","190","<b>לא ידון רוחי עוד</b>: בראשית ו, ג [בהוספת תיבת ”עוד\". וראה גם לקמן פ' ויקהל תא, ב. מאמרי אדה\"א דברים ח\"ג ע' א'ס]. ראה גם להלן קס, ד."],["7342","191","<b>שראתה שפחה על הים</b>: נסמן לעיל קלט, א. ראה גם לקמן קצד, ב."]]],[2300540533,"גם בשמחת הנפש ביותר או בשמחת היין שאז יגלה כל העלם ומצפון כמו אגברי חמרא אדרדקי<sup data-n=\"7343\">192</sup> כו' ולא יוכל לעצור רוחו כלל כי רוח הנפש עצמ[ה] גובר אז ע\"י השמחה כו'. וזהו מבחי' גבורות שברוח כמו רוח דתחה\"[מ] שיחי' עצמו' יבישות כו' כמ\"ש מד' רוחות כו' ופחי בעצמות<sup data-n=\"7344\">193</sup>, וכן יש ברוח להיפוך לעצור ולכבוש כעסו ולהיות ארך אפים כו' וכן להעלים כל דבר סוד דוקא כידוע. וכ\"ז מפני שיש ברוח עלי' וירידה וכתקפו וכגבורתו בצמצום ועלי' והסתלקות למעלה דוקא כמו כי רוח האדם העולה<sup data-n=\"7345\">194</sup> בעילוי אחר עילוי כו', כך תקפו וגבורתו לירד למטה כרוח הים שמוריד הגלים ומעלה אותם וכאן א' ויולך ה' רוח בירידה למטה כו' (<sup data-n=\"7346\">195</sup>וכאן הי' ברוח קדים זה ב' רוחות הפכיים בבקיעה זו ממזרח שהרי נצבו כמו נד מימין ומשמאל וכמ\"ש והמים להם חומה כו' שזה הרוח שהעמיד למים כחומה לצד דרום הי' היפוך רוח הב' שהעמיד המים לצד צפון שהוא הלך מדרום לצפון וזה הלך מצפון לדרום ושניהם כלולים היו ברוח קדים דמזרח שבקע הים ממזרח למערב לפי שרוח קדים דמזרח כולל ב' רוחות דצו\"ד ומטעם הנ\"ל וד\"ל).\n<b>והנה</b> אחר שראו ישראל בקי\"ס הארה זאת מעצמות א\"ס ב\"ה שיכול לעשות מבחי' ההעלם דים העליון להיות בבחי' גילוי שלא כפי ההשתל' אז ראו והשיגו ג\"כ שיכול להיות גם מבחי' דרצה\"ע הפנימי' שבתו\"מ לבא הוא עצמו לידי גילוי בלי הסתר וצמצום העצמות כלל כמו לע\"ל דכתיב ולא יכנף עוד מוריך<sup data-n=\"7347\">196</sup> כו', והוא מה שיהי' גילוי סודות וטעמי מצות מההעלם לגילוי בימות המשיח וכמ\"ש כולם ידעו אותי כו' שזהו אהי' אנא זמין לאתגלאה מבחי' ההעלם דפנימי' הרצון וחכ' דתוה\"ק כו' אשר אהי' בעוה\"ב שיתגלה אור העצמות דא\"ס ב\"ה כמו שהוא ממש בלי לבוש והעלם כלל ע\"י המצות בעוה\"ז בפו\"מ כנ\"ל, וכמ\"ש הנה אלקינו זה<sup data-n=\"7348\">197</sup> לנוכח וכתי' להנחיל אוהבי יש<sup data-n=\"7349\">198</sup> יש האמיתי מקורא דכולא<sup data-n=\"7350\">199</sup> כידוע בענין שיוציא חמה מנרתקה<sup data-n=\"7351\">200</sup> כו', וכל זה ראו והשיגו מענין הגילוי דהעלם מים עצמו ליבשה בקי\"ס שהי' מעין דלע\"ל כמ\"ש שם נשמחה בו ממש. וז\"ש וירא ישראל את היד הגדולה, פי' יד הגדולה הוא בחי' התפשטות דרב חסד העליון שלמעלה מן הרצון וחכ' שיורד מגבוה גבוה לנמוך ביותר כמו המגביהי לשבת המשפילי<sup data-n=\"7352\">201</sup> כו' כמו שיד הגדולה מתפשטת למטה ביותר כו', והיינו כמו שלגדולתו אין חקר<sup data-n=\"7353\">202</sup> בעצמותו דאוא\"ס למעלה מעלה עד אין קץ<sup data-n=\"7354\">203</sup>, כך תוקף ירידתו",[["7343","192","<b>אגברי חמרא אדרדקי</b>: נסמן לעיל פ' בא צו, א."],["7344","193","<b>מד' רוחות [א: ניתוסף: </b>בואי]. . בעצמות [אד: כו']: יחזקאל לז, ט [ושם: בהרוגים — ראה מאמרי אדה\"א נ\"ך ע' קנב. וש\"נ]."],["7345","194","<b>כי רוח האדם העולה</b>: נסמן לעיל פ' וארא עט, ב."],["7346","195","<b>וכאן</b>: אד: וכך."],["7347","196","<b>ולא יכנף עוד מוריך</b>: ישעי' ל, כ."],["7348","197","<b>הנה אלקינו זה</b>: ישעי' כה, ט."],["7349","198","<b>להנחיל אוהבי יש</b>: נסמן לעיל קלח, ד."],["7350","199","<b>מקורא דכולא</b>: זהר בראשית לג, א."],["7351","200","<b>שיוציא חמה מנרתקה</b>: נסמן לעיל פ' שמות לט, ב."],["7352","201","<b>המגביהי לשבת המשפילי</b>: תהלים קיד, ה. ו."],["7353","202","<b>שלגדולתו אין חקר</b>: תהלים קמה, ג."],["7354","203","<b>דאוא\"ס למעלה מעלה עד אין קץ</b>: נסמן לעיל פ' שמות ד, ד."]]],[2300540551,"והשפלתו למטה מאד עד שמעלה ומטה שוין ממש עד שהעלם וגילוי שוין כחשיכה כאורה כו'. וז\"ש אשר עשה הוי' העליון במצרים שהוא בחי' ההעלם דרצה\"ע שהוא עצמו נעשה בבחי' גילוי, וזה הי' מצד בחי' יד הגדולה דוקא שהוא אשר עשה הוי' הנעלם לגילוי, וע\"ז א' <span data-k=\"pg\">רטז</span> ּ כימי צאתך מאמ\"צ אראנו נפלאות לע\"ל כנ\"ל דמה שראו היד הגדולה זו בירידתו למטה לעשות מהעלם גילוי אראנו לע\"ל נפלאות דסדכ\"ס שיהי' בגילוי בעוה\"ב כנ\"ל וד\"ל (ומ\"ש תחלה וירא ישראל את מצרים מת על שפת הים כו' דהיינו מה שהובדלו ישראל להיות בבחי' הפנימי' דאוא\"ס שבשפע הפנימי' דרצה\"ע שבתו\"מ, וע\"כ הלכו ביבשה בתוך הים שההעלם עצמו נגלה להם ומצרים נטבעו בים שלא יכלו לקבל את האור הפנימי והושלכו על שפת הים, בזה ראו שגם בעצמות הרוממות דא\"ס לע\"ל יובדלו ישראל לבד בקבלת שפע הפנימי' וזהו עיקר בחי' היד הגדולה שעשה ה' במצרים דוקא, שזהו ענין שביקש משה שלא תשרה שכינה באוה\"ע<sup data-n=\"7355\">204</sup> וכמ\"ש או הנסה אלקי'<sup data-n=\"7356\">205</sup> לבוא לקחת לו גוי מקרב גוי להבדיל פנימי' מחיצוני' גם במקום דכחשיכה כאורה (וכמו גם ברדיפת [מצרים] בים הי' הענן וחושך<sup data-n=\"7357\">206</sup> אור לישראל וחושך למצרים כמ\"ש במ\"א) (וכטענת מדה\"ד מה נשתנו אלו מאלו<sup data-n=\"7358\">207</sup> ) דשם א' אם צדקת כו'<sup data-n=\"7359\">208</sup> שזהו ענין שביקש משה שלא תשרה שכינה באוה\"ע<sup data-n=\"7360\">209</sup>, אבל שם דוקא יבחר לנו את נחלתינו<sup data-n=\"7361\">210</sup> כמ\"ש במ\"א וד\"ל).\n<b>וזהו</b> וייראו העם את הוי' ויאמינו בהוי' כו', ולכאורה אין זה מובן דאיך שייך האמונה אחרי היראה שהוא אותיות ראיה<sup data-n=\"7362\">211</sup> מקרוב כנ\"ל שבדבר הנראה לעין א\"צ לאמונה כו'. אך הנה מבואר למעלה בענין ב' הויות בחי' הוי' העליון שבהעלם הרצון והב' הוי' התחתון שבא בגילוי להאציל ולברוא כו', והנה בקי\"ס ראו ישראל והשיגו שיכול להיות מהעלם דרצה\"ע עצמו גילוי כאשר הפך ים העליון להיות הוא עצמו יבשה כו' כנ\"ל, וזהו וייראו העם את הוי' פי' יראה זו הוא יראה פנימית שהוא בחי' ביטול במציאות ממש כמו הרואה את המלך מקרוב כל שקרוב קרוב יותר יותר יבא לידי יראה וביטול כל עצמותו, שכל שהתגלות המלך יותר מקרוב יותר יפול היראה ובושה עד שמתבטל בעצם מציאותו לגמרי וכל שאינו רואה מקרוב כ\"כ לא שייך היראה בושת בביטול פנימי כ\"כ, ולכך יראה אותיות ראיה דהא בהא תליא דראי' מביאה לידי יראה דענין א' הוא דכל שהוא בא [לבחי' ראי' מקרוב יותר בא] ליראה פנימית יותר וכאשר המלך מוסתר בהיכלו אין היראה נופל כ\"כ כו', ודוקא כשהדבר הנסתר ונעלם בא להתגלות במלך בהיכלו שגדולתו",[["7355","204","<b>שביקש משה שלא תשרה שכינה באוה\"ע</b>: ראה לעיל פ' שמות לא, א. וש\"נ."],["7356","205","<b>או הנסה אלקי'</b>: ואתחנן ד, לד."],["7357","206","<b>הענן וחושך</b>: ראה מאמרי אדה\"ז תקס\"ח ח\"א ע' קפ."],["7358","207","<b>מה נשתנו אלו מאלו</b>: נסמן לעיל פ' בא פח, ד."],["7359","208","<b>אם צדקת כו' </b>[א: מה תתן לו]: איוב לה, ז."],["7360","209","<b>שזהו. . באוה\"ע</b>: א: ליתא. וראה לעיל שו\"ה דוקא."],["7361","210","<b>יבחר לנו את נחלתינו</b>: נסמן לעיל לה, ג."],["7362","211","<b>היראה שהוא אותיות ראיה</b>: ראה סידור שער הל\"ג בעומר שו, א. ש\"א מ, א ובהערה 19."]]],[2300540568,"נעלה מאד ובא בהתגלות תפול אימתו ביותר, וכמו לע\"ל דכתיב ובאו כו' מפני פחד ה' והדר גאונו<sup data-n=\"7363\">212</sup> לפי שיתגלה מאור א\"ס שהי' בהסתר בבחי' הכתר שהוא העלם הרצון שאז נק' נורא כמשי\"ת אז יהי' פחד ה' על כל הברואים אפי' על חיות ובהמות בבחי' ביטול גדול כמו שאו' וייראוך כל המעשים כי שמך נורא<sup data-n=\"7364\">213</sup> על כל כו', והוא מצד בחי' ההתגלות העצום שיהי' אור האלקי בא בגילוי מקרוב לכל בשר כמ\"ש ונגלה כבוד ה' וראו כ\"ב כו', וכל בחי' התגלות מקרוב מביא היראה והביטול כמו בהגלות נגלות אור פני מלך כו' בבחי' שם הוי' התחתון שמהווה את הכל מאין שיבא בבחי' ראיה מקרוב בהשגה ותפיסא לכל הנבראי' שאז ודאי יפול היראה על כל בריא' אפי' בהמות וחיות כמו היראה וביטול דארי' <span data-k=\"pg\">434</span> ּ ושור במרכבה העליונה, וכמו שהי' בפרות גשמיות שנשאו הארון שא' שירה ביראה עליונה דפני שור ממש כמ\"ש הלוך וגעה<sup data-n=\"7365\">214</sup> כו', וכך ממש יהי' לע\"ל בגילוי ההעלם דפנימי' הכתר דרצה\"ע הנ\"ל למטה ע\"י שיהי' פחד ה' העליון על כל הברואים כמ\"ש וגר זאב<sup data-n=\"7366\">215</sup> כו' וארי' כבקר<sup data-n=\"7367\">216</sup> כו' (דזהו גילוי אור הכתר במל' כמ\"ש כוס\"י רוי\"ה גימט' אר\"ך<sup data-n=\"7368\">217</sup> כו' והוא מל' דמשיח שיתגלה אז מפנימי' וסודות התורה שבהעלם אור הרצה\"ע הפנימי' שזהו בחי' שם אהי' אנא זמין לאתגלאה בימות המשיח כו' כנ\"ל וד\"ל.\n<b>וזהו</b> וייראו העם את הוי' פי' יראה זו הוא בבחי' יראה עילאה בשם הוי' העליון הנעלם שבא אליהם בבחי' ראיה והשגה מקרוב ממש כמו שם הוי' שלמטה כמו שיהי' בימוהמ\"ש, והוא לפי שבקי\"ס ראו והשיגו איך שנעשה מהעלם דהוי' העליון עצמו גילוי למעלה מסדר ההשתל' דהעלם וגילוי כנ\"ל והוא בחי' היד הגדולה אשר עשה הוי' העליון במצרים שבא הוא עצמו בגילוי מקרוב שאז שייך ענין היראה שהיראה וראי' ענין א' הוא כנ\"ל וד\"ל (ומ\"ש תחלה וירא ישראל ישראל סבא<sup data-n=\"7369\">218</sup> כו' ובסוף א' וייראו העם כו' דבחי' יש\"ס הוא במדות דחכ' הקדומה שברצון הנעלם שבתו\"מ ראה זה למעלה את היד כו' כמו שלע\"ל א' אראנו לישראל זה<sup data-n=\"7370\">219</sup> נפלאות שהן רזי' וסודות טעמי התו\"מ, אך בקי\"ס ירד האור הגדול הזה עצמו למטה במל' דאצי' בבי\"ע שנק' מלך על עם כידוע בבחי' ראי' מקרוב כמלך שמתגלה שיפול פחדו על עמו כמו לע\"ל כמלך על עם וז\"ש וייראו העם את ה' העליון וד\"ל). וכ\"ז הוא רק בבחי' יראה שנתעלו בקי\"ס להגיע בבחי' ראי' מקרוב לבחי' הוי' העליון להיות יראה עילאה כמו יר\"ת כמלך על עם כו' שזהו רק בימוהמ\"ש כנ\"ל, אבל למעלה גם מזה הוא בחי' עצמות דאוא\"ס שנק' סדכ\"ס דלמת\"ב כלל שלא שייך שם בחי' ראי' והשגה כלל אפי' מח' דתורה וחכ' הקדומה כו'",[["7363","212","<b>ובאו. . והדר גאונו</b>: ישעי' ב, יט [ושם: ומהדר — ראה לקמן קפב, א. פ' תצוה שכה, ב [ושם הוגה מגוכתי\"ק]."],["7364","213","<b>וייראוך. . כי שמך נורא</b>: תפלת העמידה לימים נוראים."],["7365","214","<b>הלוך וגעה</b>: שמואל-א ו, יב [ושם: וגעו]."],["7366","215","<b>וגר זאב</b>: ישעי' יא, ו."],["7367","216","<b>וארי' כבקר</b>: ישעי' שם, ז."],["7368","217","<b>כוס\"י רוי\"ה גימט' אר\"ך</b>: תהלים כג, ה. יומא עו, א. ראה גם לקמן קסא, א. פ' משפטים רצז, ב. הנסמן במאמרי אדה\"א דברים ח\"א ע' כג. שע\"ת כב, ג ובהערה 23. ש\"א לג, ב."],["7369","218","<b>וירא ישראל ישראל סבא</b>: ראה זהר בשלח נג, א. ב\"ר פצ\"ב, ב. רש\"י תענית ה, ב ד\"ה אף הוא בחיים."],["7370","219","<b>שלע\"ל א' אראנו לישראל זה</b>: ראה גם לעיל פ' שמות כא, א. וש\"נ."]]],[2300540584,"שהן רזין וסודות התורה דאין טעם לרצון העצמי שבמצות מצד עצמן אפי' טעם כמוס כו', והוא העוה\"ב שז\"ש אשר אהי' שיתגלה כמו שהוא במהו\"ע ממש שלמעלה הרבה מימוהמ\"ש כנ\"ל והוא [ה]עדן דתענוג הפשוט ועצמי שבשעשועי המלך מצד עצמו ממש שלמעלה הרבה מתענוג שמורכב בטעם כמוס דחכ' דתורה שאינו רק הארה בעלמא כמ\"ש על התורה ואהי' אצלו כו' שעשועי'<sup data-n=\"7371\">220</sup> וכן א' אני תורתך שעשעתי<sup data-n=\"7372\">221</sup> כו'. אמנם אע\"פ שבעוה\"ב יתגלה גם זה בנשמות הצדיקים שקיימו התורה בעוה\"ז ואשר עמדו בה\"ס וקיבלו התו\"מ, אבל בקי\"ס לא ראו זה בראי' מקרוב כמו בעוה\"ב ממש רק האמינו באמונה שלימה וחזקה שיכול להיות גם זה לבא בגילוי מהעלם דעצמו' א\"ס ב\"ה שנק' סדכ\"ס, כי אחר שראו היד הגדולה שיכול לעשות מהעלם דרצה\"ע עצמו להיות בבחי' גילוי א\"כ זה ודאי בא מכח העצמו' דא\"ס שלפניו שוין העלם וגילוי כנ\"ל, ע\"כ האמינו גם זה שכל יכול הוא והן הן גבורותיו<sup data-n=\"7373\">222</sup> שממקום גדולתו העצמי ברוממו' דשעשועי' העצמיי' יבא בגילוי למטה בלי העלם כלל כמ\"ש ולא יכנף עוד כו' וכמ\"ש הנה אלקינו זה לנוכח כו', רק שלא יכלו לראות זה בקי\"ס בראי' מקרוב כמו שראו להוי' העליון דרצה\"ע שכבר בא <span data-k=\"pg\">ריז</span> ּ העלמו לגילוי כשהפך ים ליבשה כנ\"ל שז\"ש אשר עשה הוי' במצרים כו', אבל באמונה שלמעלה מן ההשגה וראי' האמינו בהוי' העצמי דעצמות הרצון ותענוג הפשוט שבמצות עצמן שיתגלה בראי' מקרוב בעוה\"ב כמ\"ש בעדן עין לא ראתה<sup data-n=\"7374\">223</sup> אלקים זולתך כו' וזהו ויאמינו בהוי' כו' גם אחר שראו אשר עשה הוי' [העליון] וייראו העם כו', אבל באמתת עצמות א\"ס ב\"ה ממש לא ראו כ\"א באמונה ואמונה זו תבוא לגילוי ראי' (לפי שראו את היד הגדולה כנ\"ל) ע\"י משה עבדו (כמשי\"ת). וזהו כימי צאתך מאמ\"צ אראנו לישראל זה נפלאות שני נפלאות זו למעלה מזו והוא ימות המשיח והעוה\"ב כנ\"ל בענין עם זו קנית וז\"ש הפך ים כו' שם נשמחה בו בעוה\"ב בגילוי [מ]קרוב מה שהי' בקי\"ס באמונה וד\"ל.\n<b>וזהו</b> ויאמינו בהוי' כו' דבחי' סדכ\"ס עצמו שאינו נראה ומושג כלל לא הי' להם רק בחי' אמונה שלמעלה מן ההשגה אבל בהוי' דכתר הי' להם ראי' כנ\"ל, ואין זה מתיישב עדיין דהרי א' וירא ישראל כו' הרי הכל הי' להם בבחי' ראי' כו'. אך יובן זה בהקדים ענין א' הידוע במה שא' הגדו\"ל הגבו\"ר והנור\"א<sup data-n=\"7375\">224</sup> דהזכיר וא\"ו בנורא ולא בגבור כו', שיש בזה ב'",[["7371","220","<b>ואהי' אצלו כו' שעשועי'</b>: משלי ח, ל."],["7372","221","<b>אני תורתך שעשעתי</b>: תהלים קיט, ע."],["7373","222","<b>והן הן גבורותיו</b>: נסמן לעיל כא, ג."],["7374","223","<b>בעדן עין לא ראתה</b>: ראה ברכות לד, ב. ישעי' סד, ג."],["7375","224","<b>שא' הגדו\"ל הגבו\"ר והנור\"א</b>: במאמרי אדה\"ז תקס\"ו כאן (ע' קמז): שאנו אומרים בש\"ע. וראה עקב י, יז."]]],[2300540600,"דברים הפכיי', הא' וי\"ו<sup data-n=\"7376\">225</sup> דוי\"ו זה דוהנורא הוא בחי' צמצום ההמשכה בוי\"ו שראשו יו\"ד והולך ונמשך בקוצר כידוע. והענין הוא לפי שבחי' ההתגלות מקרוב מביא לידי יראה דיראה אותיות ראי' כנ\"ל וכאשר המלך מתגלה מהיכלו בקרוב דוקא נק' נורא שיריאי[ם] ממנו ביותר כשבא מקרוב ונופל פחדו ואימתו מתפשט[ת] ביותר ע\"כ נק' נורא (פארכטיג) שממשיך יראה על העומדי' לפניו, ואמנם מה שנק' נורא לגבי עבדיו ושריו זהו צמצום גדול לגבי רוממות ההתנשאות שלו שמצד עצמו כשיושב בהיכלו מוסתר כולו או[מר] כבוד כו'. וכך יובן למעלה שכדי שהוא ית' נק' נורא שזהו בחי' ההתגלות דמל' דא\"ס עצמו לבא בירידת המדריגה להיות נורא בהתפשטו' אימתו לנאצלים ע\"כ יש וי\"ו בוהנורא שוי\"ו זה הוא בחי' צמצום לגבי עצמו' רוממותו והתנשאו[ת] שמצד עצמו שנק' מלך הקדוש<sup data-n=\"7377\">226</sup> מלך יחיד לבדו<sup data-n=\"7378\">227</sup> כו', ומה שנק' מלך בהתנשאו[ת] אימ[ה] למקבלים זהו גיאות לבש<sup data-n=\"7379\">228</sup> כו' (אבל הגדול הגבור הן חו\"ג דא\"ס<sup data-n=\"7380\">229</sup> איך שהוא למעלה עד אין קץ ולמטה כו' אינו בא ע\"י צמצום כלל) וזהו פחד ה' שמתפשט גם על המלאכים דבי\"ע. ואמנם יש עוד ענין ב' בוי\"ו זה דוהנורא להיפוך שהוא למעלה<sup data-n=\"7381\">230</sup> יתירה יותר מהגדול כו', להיות דוי\"ו זה אע\"פ שבא דרך צמצום ביו\"ד וי\"ו כו' זהו בחי' הקו\"ח<sup data-n=\"7382\">*231</sup> שנק' קו המדה<sup data-n=\"7383\">231</sup> בכלל אבל יש בו מבחי' עצמו' אוא\"ס שלפני הצמצום הראשון דוקא וע\"כ יש ביכולתו להחליף<sup data-n=\"7384\">232</sup> מקו הימין לשמאל כו', ויכול לעשות מהעלם גילוי כו', והוא בחי' ת\"ת קו האמצעי שהוא בפנימי' הכתר<sup data-n=\"7385\">233</sup> בכלל בלי שינוי והעלם כלל והוא שם הוי' דגם הכלי שבו מאיר כמו האור כידוע במ\"ש מי כמוך באלים הוי'<sup data-n=\"7386\">234</sup> כו', ע\"כ יש בו בחי' אין דכתר בגילוי כמו הניסים שלמעלה מן הטבע בעלמא דאתכסיי' בא<sup data-n=\"7387\">235</sup> בדרך הטבע כו' דהעלם וגילוי שוין בו כו' כמ\"ש במ\"א בענין ה' אלקיו עמו<sup data-n=\"7388\">236</sup> כו', וא\"כ הרי בוי\"ו זה<sup data-n=\"7389\">237</sup> מתגלה מבחי' התנשאו' דמל' דא\"ס עצמו כמו שהוא בלי צמצום ולבוש כלל. וזהו והנורא שמתגלה מהעלמו כמו שהוא הוא ע\"י <span data-k=\"pg\">436</span> ּ וי\"ו דוקא (אבל חו\"ג באים ע\"י צמצום ולבוש דפרסא המפסיק כו'). וזהו בחי' פחד הוי' דמל' דא\"ס הנעלם שיתגלה על כל כו' והוא מל' דא\"ס התנשאות העצמו' שיאיר במשיח וכמ\"ש ימלוך לע\"ו<sup data-n=\"7390\">238</sup>, וע\"כ דוד מ\"י חי וקיים<sup data-n=\"7391\">239</sup> כמ\"ש חיים נתת לו<sup data-n=\"7392\">240</sup> כו', וז\"ש בקי\"ס כי אה גאה כו' וברוב גאונך<sup data-n=\"7393\">242</sup><sup data-n=\"7394\">241</sup> כמו לע\"ל וכן תפול עליהם אימתה<sup data-n=\"7395\">243</sup> דמל' דא\"ס כו' לפי שהי' בבחי' שם הוי' דת\"ת שבכתר כמ\"ש זה אלי ואנוהו<sup data-n=\"7396\">244</sup> כו' והוא מה שראתה שפחה כו' לפי",[["7376","225","<b>הא' וי\"ו</b>: א: הא'. ד: ליתא."],["7377","226","<b>מלך הקדוש</b>: נסמן לעיל פ' בא ק, ג הערה 181."],["7378","227","<b>מלך יחיד לבדו</b>: ראה גם לעיל שם."],["7379","228","<b>גיאות לבש</b>: ראה לעיל פ' וארא עה, א ובהערה 189."],["7380","229","<b>חו\"ג דא\"ס</b>: ראה לעיל צ, ב. וש\"נ."],["7381","230","<b>למעלה</b>: א: במעלה."],["7382","*231","<b>דוי\"ו. . בחי' הקו\"ח</b>: ראה גם לקמן קסז, ד. קצ, ד."],["7383","231","<b>הקו\"ח שנק' קו המדה</b>: נסמן לעיל מא, א."],["7384","232","<b>הקו\"ח. . עצמו' אוא\"ס. . ביכולתו להחליף</b>: ראה גם לעיל פ' שמות מח, ב. וש\"נ."],["7385","233","<b>ת\"ת קו האמצעי. . הכתר</b>: ראה השמטות לזח\"א רנז, א. ש\"א (לר\"י גיקטיילא) שער ה' (ע' סג ואילך)."],["7386","234","<b>מי כמוך באלים הוי'</b>: בשלח טו, יא. ראה מאמרי אדה\"ז על פרשיות התורה ח\"א ע' סג ואילך. מאמרי אדה\"א דברים ח\"ג ע' תשפד. וש\"נ."],["7387","235","<b>בעלמא דאתכסיי' בא</b>: א: שהוא בא. ד: במל' דא\"ס שבא."],["7388","236","<b>ה' אלקיו עמו</b>: בלק כג, כא. ראה גם <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300670590\" data-slug=\"torat-chaim\" data-id=\"2300670590\">תו\"ח נח עו, ד</a>."],["7389","237","<b>בוי\"ו זה</b>: א: בחי' זו. ד: בגילוי זה."],["7390","238","<b>ימלוך לע\"ו</b>: בשלח טו, יח. ראה גם לקמן רכז, ב."],["7391","239","<b>דוד מ\"י חי וקים</b>: ר\"ה כה, א. נוסח קידוש לבנה."],["7392","240","<b>חיים נתת לו</b>: תהלים כא, ה [בדילוג — ראה מאמרי אדה\"א בראשית ע' שס. וש\"נ]."],["7393","242","<b>וברוב גאונך</b>: שם טו, ז."],["7394","241","<b>כי גאה גאה</b>: בשלח טו, א."],["7395","243","<b>תפול עליהם אימתה</b>: בשלח שם, טז. ראה גם לקמן קנח, ג. פ' תצוה של, ד."],["7396","244","<b>זה אלי ואנוהו</b>: שם שם, ב."]]],[2300540614,"שבא בגילוי ההעלם למטה כמו למעלה וכמו ולא ילמדו<sup data-n=\"7397\">245</sup> כו' קטן וגדול שוין<sup data-n=\"7398\">246</sup>. אך זהו רק בשם אהיה הא' שיגלה כל סוד הנעלם וכ[מ]\"ש עושה פלא<sup data-n=\"7399\">247</sup> דפלא דכתר<sup data-n=\"7400\">248</sup> עצמו נעשה גילוי באלף<sup data-n=\"7401\">249</sup> כו', אבל למעלה מזו הוא אהיה הב' דעוה\"ב שנק' סדכ\"ס דלמחת\"ב כלל דאפי' אור צח כו' אוכם<sup data-n=\"7402\">250</sup> כו' וז\"ש נפלאות כנ\"ל ע\"ז א' וירא ישראל כו' אשר עשה הוי' מהעלם לגילוי שזה בא מכח העצמו' דא\"ס ממש שנק' שעשועי המלך בעצמו שלמעלה גם מבחי' התנשאו' דמצד עצמו הנק' מל' דא\"ס לבד כו'. וע\"ז אמר ויאמינו בהוי' שהוא שם הוי' העצמי שבמצות הוי' שיתגלה לעוה\"ב מקיום המצות בפו\"מ דוקא כמא[מר] כ\"י יש להם<sup data-n=\"7403\">251</sup> כו' כידוע, וע\"ז הי' להם אמונה שלמעלה מן ההשגה וראי' כי לא ראו רק בחי' היד הגדולה שמתפשטת מכח העצמו' דא\"ס לעשות מהעלם גילוי למטה לבד וד\"ל.\n<b>וזהו</b> ויאמינו בה' ובמשה עבדו, דהנה לפי הנ\"ל באמונה זאת שהאמינו בה' היינו באמיתת מהו\"ע ית' שלמעלה גם מבחי' התגלות דמל' דא\"ס שנק' נורא שיהי' בעוה\"ב דוקא כנ\"ל, א\"כ מהו שא' ובמשה עבדו האיך יתכן להשוות למשה עבד ה' למהו\"ע שיאמינו במשה כמו בה' עצמו כו'. אך הענין הוא משום דבחי' משה הוא בחי' דעת<sup data-n=\"7404\">252</sup> שהוא בחי' ההתקשרות<sup data-n=\"7405\">253</sup> שמביא ומחבר ומקשר למשפיע עצמו כמו שהוא עם המקבל וע\"כ נק' שושבינא דמלכא<sup data-n=\"7406\">254</sup> והוא במה שהי' משה ממוצע להביא גילוי עצמות דא\"ס ממש בתו\"מ בפו\"מ במ\"ת כמ\"ש משה ידבר<sup data-n=\"7407\">255</sup> כו', וכמ\"ש משה אנכי עומד<sup data-n=\"7408\">256</sup> כו', ולפי שהי' המביא ומקשר לגילוי אור א\"ס שברצון וחכ' דתו\"מ בגשמיות דוקא כמ\"ש תורה צוה לנו משה<sup data-n=\"7409\">257</sup> כו' וכמ\"ש הנסתרות לה' אלקינו והנגלות לנו ולבנינו לשמור ולעשות<sup data-n=\"7410\">258</sup> בפו\"מ כידוע בכמה כתובי', הנה זהו שרשו גבוה יותר גם מבחי' פנימית סודות וטעמי תו\"מ שיתגלו ע\"י משיח<sup data-n=\"7411\">259</sup> גואל אחרון<sup data-n=\"7412\">260</sup>. דאע\"פ דמשה הוא משיח כא'<sup data-n=\"7413\">261</sup> יבא טוב ויקבל טוב<sup data-n=\"7414\">262</sup> בפנימי' התורה דאוריי' סתים וגליא<sup data-n=\"7415\">263</sup> אבל יש יתרון מעלה בנגלה שבתו\"מ בפו\"מ שנק' נובלות חש\"מ<sup data-n=\"7416\">264</sup> יותר מפנימי' דח\"ע כמ\"ש במ\"א משום דנתחב\"ס<sup data-n=\"7417\">265</sup> דוקא וסוף<sup data-n=\"7418\">266</sup>",[["7397","245","<b>ולא ילמדו</b>: ירמי' לא, לג."],["7398","246","<b>קטן וגדול שוין</b>: ראה שמו\"ר פי\"ז, ב. פ\"מ, ד. תנחומא תשא יג."],["7399","247","<b>עושה פלא</b>: בשלח טו, יא."],["7400","248","<b>דפלא דכתר</b>: ראה תיקונים לז\"ח צח, ד."],["7401","249","<b>דפלא. . באלף</b>: נסמן לעיל פ' וארא עח, ב."],["7402","250","<b>אור צח כו' אוכם</b>: נסמן לעיל פ' שמות יב, ב."],["7403","251","<b>כ\"י יש להם</b>: סנהדרין ר\"פ חלק (צ, א)."],["7404","252","<b>משה. . דעת</b>: נסמן לעיל פ' שמות פה, ד."],["7405","253","<b>דעת שהוא בחי' ההתקשרות</b>: ראה <a class=\"ft-cite\" href=\"#/read/tanya/3401310008\" data-slug=\"tanya\" data-id=\"3401310008\">תניא</a> פ\"ג. פמ\"ב. לקמן פ' תצוה שנח, ב. שעז, ג. ויקהל תלז, ד. שעה\"י קט, סע\"ב. מאמרי אדה\"א נ\"ך ע' צז. וש\"נ."],["7406","254","<b>משה. . שושבינא דמלכא</b>: נסמן לעיל יא, ג."],["7407","255","<b>משה ידבר</b>: יתרו יט, ט. ראה גם לקמן פ' תצוה שכג, ג. וש\"נ."],["7408","256","<b>אנכי עומד</b>: ואתחנן ה, ה."],["7409","257","<b>תורה צוה לנו משה</b>: ברכה לג, ד."],["7410","258","<b>הנסתרות. . לשמור ולעשות</b>: נסמן לעיל פ' בא קיד, ב הערה 178."],["7411","259","<b>משה. . שרשו גבוה יותר. . משיח</b>: ראה גם בסמוך קנו, ד. ראה גם מאמר ד\"ה הרכבת אנוש לר\"ה, יודפס בע\"ה בספרו פלח הרמון פ' בהעלותך."],["7412","260","<b>משיח גואל אחרון</b>: ראה גם שה\"א פט, א. מאמרי אדה\"א קונטרסים ע' שנב. וש\"נ."],["7413","261","<b>כא'</b>: אד: כמאמר."],["7414","262","<b>יבא טוב ויקבל טוב</b>: נסמן לעיל פ' שמות מג, ד."],["7415","263","<b>דאוריי' סתים וגליא</b>: ראה זהר אחרי עא, ב. עג, א."],["7416","264","<b>נובלות חש\"מ</b>: ב\"ר פי\"ז, ה. פמ\"ד, יז. ראה מאמרי אדה\"א דברים ח\"ד ע' א'רכ ואילך. וש\"נ. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300670304\" data-slug=\"torat-chaim\" data-id=\"2300670304\">תו\"ח נח סג, ב</a> ובהערה 26."],["7417","265","<b>דנתחב\"ס</b>: ראה ס\"י פ\"א, מ\"ז."],["7418","266","<b>וסוף</b>: א: בסוף."]]],[2300540628,"מעשה כו' כמ\"ש לעושיהם<sup data-n=\"7419\">267</sup> כו' ומזה יהי' דוקא שכר העוה\"ב שלמעלה מימוהמ\"ש כנ\"ל (ומטעם הנ\"ל דאין טעם לרצון העצמו' הפשוט אפי' טעם כמוס והוא שם אהי' הב' כנ\"ל). ולכך נק' משה עבד הוי'<sup data-n=\"7420\">268</sup> דוקא דהיינו מה שנמשך רצה\"ע בתו\"מ מבחי' שם הוי' העצמי' שבעצמו' א\"ס ממש (שלא נודע גם לאבות כנ\"ל כי טעמי וסודות דתו\"מ נודע ונגלה גם לאבות שקיימו כל התו\"מ ברוחניות עכ\"פ ע\"פ סוד הוי' שבהם כמו שהוא למעלה בפנימי' דח\"ע כו') בבחי' עבודה בקיום <span data-k=\"pg\">ריח</span> ּ בגשמיות בפו\"מ. וז\"ש במשה לא כן עבדי משה בכל ביתי נאמן הוא<sup data-n=\"7421\">269</sup> דהיינו בכל בית דח\"ע שהן התו\"מ כמו שהן במהו\"ע ממש שנק' הון ביתו<sup data-n=\"7422\">270</sup> [נאמן הוא להביא ולהמשיך למטה<sup data-n=\"7423\">271</sup> דברים גשמיים דווקא, ולזה נקרא עבד הוי' ממש שלמעלה גם מבחי' בן דמשיח שאמר בו אני היום<sup data-n=\"7424\">272</sup> כו', וכמו עבד הנאמן בכל ביתו] שכרצונו עושה כמו בעה\"ב עצמו ממש שאין כח זה גם לבן כו' והן כל דיני התורה שע\"י משה דוקא שאין כל נביא<sup data-n=\"7425\">273</sup> כו' וכמ\"ש אין משגיחין<sup data-n=\"7426\">274</sup> כו'. ומזה הטעם יובן שאמונה זו שהאמינו באמתת עצמו' א\"ס ב\"ה הוא עצמו גורם שהאמינו במשה עבדו שניתן על ידו התו\"מ בפו\"מ שהוא דוקא בחי' הממוצע להמשיך בגילוי מהעלם דמהו\"ע ית' ממש וד\"ל.\n<b>ויובן</b> זה ממה שמצינו שמשה נק' רעיא מהימנא<sup data-n=\"7427\">275</sup> רועה נאמן<sup data-n=\"7428\">276</sup> והלא גם האבות נק' רועי'<sup data-n=\"7429\">277</sup> כידוע, אבל הענין ידוע ומבואר בענין ורעה אמונה<sup data-n=\"7430\">278</sup> שיש רועה הזן ומפרנס את האמונה בכנ\"י, והענין הוא כידוע בענין המא' דאיהו אמת ואיהי אמונה<sup data-n=\"7431\">279</sup> שיש ב' מדרגות באמונה א' האמונה בשם הוי' כאברהם שהי' המאמין הראשון<sup data-n=\"7432\">280</sup> בשם הוי' כמ\"ש והאמין בה'<sup data-n=\"7433\">281</sup> כו' והוא בשם הוי' הבא בגילוי באבי\"ע וגם בשם הוי' דהעלם הרצון (שבפנימי' הכתר כנ\"ל) כמ\"ש וארא אל אברהם<sup data-n=\"7434\">282</sup> כו' באל שדי שהוא חג\"ת שבכתר ונק' ימי קדם כמ\"ש אשר נשבעת לאבותינו<sup data-n=\"7435\">283</sup> כו' והן עלדא\"ת ועלד\"א בכלל, אבל שמי הוי' בבחי' הוי' העצמו' דתו\"מ בפו\"מ כנ\"ל לא נודעתי להם רק במ\"ת לבד שא' אנכי הוי' אלקיך וכן בק\"ש שמע ישראל<sup data-n=\"7436\">284</sup> הוי'",[["7419","267","<b>לעושיהם</b>: תהלים קיא, י [ושם: לכל עושיהם]. ראה ברכות יז, א [גי' המובא עה\"ג שם]."],["7420","268","<b>משה עבד הוי'</b>: ברכה לד, ה."],["7421","269","<b>לא כן. . נאמן הוא</b>: בהעלותך יב, ז. ראה מאמרי אדה\"א בראשית ע' נד. וש\"נ. שמות ח\"ב ע' שלב. לקמן פ' תצוה שע, א. ויקהל שצז, ב."],["7422","270","<b>הון ביתו</b>: שה\"ש ח, ז. ראה גם לקמן רכד, ג. ויקהל שצז, ב. <a class=\"ft-cite\" href=\"#/read/torah-or/3901370038\" data-slug=\"torah-or\" data-id=\"3901370038\">תו\"א נח ט, ב</a>. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300670264\" data-slug=\"torat-chaim\" data-id=\"2300670264\">תו\"ח נח סב, ג</a>. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300680327\" data-slug=\"torat-chaim\" data-id=\"2300680327\">ויחי רמח, א</a>. מאמרי אדה\"א נ\"ך ע' ערב."],["7423","271","<b>למטה</b>: ניתוסף ע\"פ א."],["7424","272","<b>אני היום</b>: נסמן לעיל א, ג."],["7425","273","<b>שאין כל נביא</b>: שבת קד, א."],["7426","274","<b>אין משגיחין</b>: ב\"מ נט, ב."],["7427","275","<b>שמשה נק' רעיא מהימנא</b>: נסמן לעיל פ' וארא עז, ב."],["7428","276","<b>שמשה. . רועה נאמן</b>: ראה פדר\"א פמ\"ב. אסת\"ר פ\"ז, פסוק יג. פתיחתא דאיכ\"ר כד. זהר שמות כא, א."],["7429","277","<b>האבות נק' רועי'</b>: ראה סוכה נב, ב. מאמרי אדה\"א שמות ח\"ב ע' תרכב. וש\"נ. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300680062\" data-slug=\"torat-chaim\" data-id=\"2300680062\">תו\"ח וישלח קפא, א</a> ובהערה 13. לקמן פ' משפטים רכב, ב. ויקהל (תיא, ג. וש\"נ). תל, ב."],["7430","278","<b>ורעה אמונה</b>: תהלים לז, ג. ראה הנסמן בסמוך הערה 287."],["7431","279","<b>דאיהו אמת ואיהי אמונה</b>: נסמן לעיל י, ד."],["7432","280","<b>כאברהם שהי' המאמין הראשון</b>: ראה שמו\"ר פכ\"ג, ה. שהש\"ר פ\"ד, ח. ג."],["7433","281","<b>והאמין בה'</b>: לך טו, ו."],["7434","282","<b>וארא אל אברהם</b>: וארא ו, ג."],["7435","283","<b>ימי קדם. . אשר נשבעת לאבותינו</b>: ראה גם לעיל פ' בא צ, ג הערה 178."],["7436","284","<b>שמע ישראל</b>: ואתחנן ו, ד."]]],[2300540641,"אלקינו הוי' אחד באח\"פ ממש, וזהו בחי' אמונה בהוי' שבעצמות ממש שע\"ז א' ורעה אמונה שהוא מ\"ש איהו אמת אמיתת העצמו' דא\"ס כמו שהוא ממש ואיהי אמונה דכנ\"י מקבלים בתוכם אמונה זאת ע\"י משה שנק' ר\"מ שהוא בחי' הממוצע להמשיך לכנ\"י אמונה זאת באמתת מהו\"ע ית' שלמעלה מאמונה דאבות שממשיכים לכנ\"י בדרך ירושה שנק' אומנים<sup data-n=\"7437\">285</sup> כאומן המגדל את היונק<sup data-n=\"7438\">286</sup> כו' (כמ\"ש במ\"א בפ' כי תשא<sup data-n=\"7439\">287</sup> שז\"ש חדשים לבקרים רבה אמונתך<sup data-n=\"7440\">288</sup> כו' והוא ענין תו\"מ בפו\"מ שכללותם אמונה זו שנא' וצדיק באמונתו יחי'<sup data-n=\"7441\">289</sup> שמזה יש לכנ\"י כח למס\"נ על התו\"מ שלמעלה מכח אה\"ר שבנפשם בירושה מאבות<sup data-n=\"7442\">*290</sup> כו' שקיבלו במ\"ת וכמ\"ש במ\"א ע\"פ קימו וקבלו<sup data-n=\"7443\">290</sup> כו'), וזהו שא' בזהר דמשה אוליף להו רזא דמהימנותא<sup data-n=\"7444\">291</sup> שהוא אח\"פ שלמעלה גם ממקור הרצון להאציל ע\"ס כו' וד\"ל.\n<b>וז\"ש</b> עבדי משה בכל ביתי נאמן לשון נפעל לפי שממוצע הוא לקבל מאור אמתת מהו\"ע ית' התו\"מ וממשיך לישראל בחי' אמונה זו שבהעלם רצון העצמו' להיות באה לידי גילוי אור וחיות בנפשם ממש, וכמ\"ש אלה המצות כו' וחי בהם<sup data-n=\"7445\">292</sup> וכן<sup data-n=\"7446\">293</sup> למען תהי'<sup data-n=\"7447\">294</sup> כו' כי הוא חייך<sup data-n=\"7448\">295</sup> ממש עד שיכולים למס\"נ על קדה\"ש על התו\"מ כידוע בנסיון זה ג\"א<sup data-n=\"7449\">296</sup> שנה כו', ומאחר שמביא וממשיך אמונה רבה זו שבמהו\"ע ית' שבמצות לכנס\"י להיות להם למזון וחיות ממש לנשמתם בכל דור ודור הרי מה שהי' בכנס\"י בבחי' אמונה בהעלם בשם הוי' העצמי (שלא נודע לאבות כנ\"ל) המשיך בבחי' גילוי באור וחיות ממש, שזהו כמו העוה\"ב ממש שיבא אור העלם העצמו' דא\"ס ממש לבחי' גילוי גמור בנשמות הצדיקי' שקיימו התו\"מ בפו\"מ בעוה\"ז דוקא כנ\"ל שזהו למעלה הרבה מפנימי' התורה שיתגלה ע\"י משיח כנ\"ל (אע\"פ שנא' בו ישכיל עבדי<sup data-n=\"7450\">297</sup> ירום כו' וגבה מאד הכל הוא בבחי' ח\"ע הפנימי' כמ\"ש ישכיל כו').\n<b>ונמצא</b> מובן עכ\"פ שמשה הי' בחי' ממוצע לקשר ולחבר לשם הוי' שבעצמו' הרצון שבתו\"מ להיות בא בגילוי שאין זה <span data-k=\"pg\">438</span> ּ מתגלה כלל אפי' בהוי' הא' דח\"ס דא\"א כטעמי' וסודות",[["7437","285","<b>דאבות. . שנק' אומנים</b>: ראה מאמרי אדה\"א שמות ח\"ב ע' תרכא. וש\"נ. נ\"ך ע' כט. לעיל פ' בא קיח, ב. וש\"נ."],["7438","286","<b>כאומן המגדל את היונק</b>: ראה בהעלותך יא, יב."],["7439","287","<b>בפ' כי תשא</b>: ראה מאמרי אדה\"א שמות ח\"ב ע' תרכא ואילך ובהנסמן לעיל פ' בא צב, א הערה 247."],["7440","288","<b>חדשים לבקרים רבה אמונתך</b>: איכה ג, כג."],["7441","289","<b>וצדיק באמונתו יחי'</b>: חבקוק ב, ד."],["7442","*290","<b>אה\"ר שבנפשם בירושה מאבות</b>: ראה תניא פי\"ח."],["7443","290","<b>קימו וקבלו</b>: אסתר ט, כז. ראה גם שערי אורה בהקדמה. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300670139\" data-slug=\"torat-chaim\" data-id=\"2300670139\">תו\"ח בראשית לה, ג</a> הערה 41."],["7444","291","<b>דמשה אוליף להו רזא דמהימנותא</b>: ראה זהר תרומה קסא, א."],["7445","292","<b>אלה המצות כו' וחי בהם</b>: נסמן לקמן קעה, ד."],["7446","293","<b>וכן</b>: א: כו'."],["7447","294","<b>למען תהי'</b>: ד: לאהבה את ה'."],["7448","295","<b>כי הוא חייך</b>: נצבים ל, כ."],["7449","296","<b>ג\"א</b>: אד: ג' אלפים."],["7450","297","<b>משיח. . ישכיל עבדי</b>: נסמן לעיל ה, ג."]]],[2300540653,"התורה והוא שם אהיה הב' שיתגלה בעוה\"ב כנ\"ל וד\"ל. וא\"כ הרי בחי' האמונה שהאמינו בהוי' העצמי בא בכנ\"י בגילוי והוא בהשג' וראי' מקרוב (וע\"כ אנו רואים שבקי\"ס הי' כמו בעוה\"ב ממש שנא' בהם שם נשמחה בו ממש וכמ\"ש עד יעבור כו' עם זו קנית <sup data-n=\"7451\">298</sup>כו' ומאחר שהאמונה באה בבחי' התגלות דראי' והשגה מקרוב א\"כ איך א' ויאמינו בה' ובמשה כו' דמשמע דאמונה זו קאי על משה והרי משה המשיך להם אמונה זו מן ההעלם לגילוי גמור בנפשם לדורות כנ\"ל (ועוד יש להבין דהלא גם בימות המשיח יהי' עיקר קיום התו\"מ בפו\"מ ואדרבה יהי' אז אחר שלימות הבירורים דעה\"ד טו\"ר כו' וע\"כ אנו או[מרים] ושם נעשה כמצות רצונך<sup data-n=\"7452\">299</sup> כו' וכמו שא' הלכתא למשיחא<sup data-n=\"7453\">300</sup> כו' כמ\"ש במ\"א, וז\"ש ואלה דברי דוד<sup data-n=\"7454\">301</sup> האחרוני' כו' נאם הגבר הקים על<sup data-n=\"7455\">302</sup> עולה של תו\"מ דוקא שמפני זה יהי' עליי' משיח במדרגה הנעלה ביותר<sup data-n=\"7456\">304</sup> והוא בחי' כתר ש\"ט שעולה ע\"ג ג' הכתרים<sup data-n=\"7457\">303</sup> כו' מפני שמזה יהי' יתרון האור מן החשך כו' שהוא בחי' ס\"ג דתוהו שלמעלה מבחי' מ\"ה<sup data-n=\"7458\">305</sup> דתיקון כידוע במ\"ש א\"ח עט\"ב<sup data-n=\"7459\">306</sup> כו' לפי שנתחב\"ס וסוב\"ת כו' וא\"כ איך א' כאן ויאמינו בה' ובמשה עבדו שע\"י קיום התו\"מ בעוה\"ז ע\"י משה יהי' למעלה מימות המשיח כו').\n<b>אך</b> הענין הוא כידוע שיש במצות ב' מדרגות<sup data-n=\"7460\">307</sup> א' מצות שנעשי' בכוונה ורעותא דלבא והוא כמ\"ד מצות צריכות כוונה<sup data-n=\"7461\">308</sup> והיינו ענין הבירורי' דרפ\"ח ניצוצי'<sup data-n=\"7462\">309</sup> שנפלו בשבה\"כ דמ\"ה מברר לב\"ן<sup data-n=\"7463\">310</sup> כו' דבחכמה דוקא אתברירו<sup data-n=\"7464\">311</sup> כידוע, ובכל מצוה ומצוה יש אופן מיוחד לענין המכוון בבירורי' והעלאות שעי\"ז נעשה בחי' יחוד עליון באצי' שזהו להוסיף אורות באצי'<sup data-n=\"7465\">312</sup> בכלל, וזהו כללות ענין המצות שהן יחוד קוב\"ה ושכינתי'<sup data-n=\"7466\">313</sup> שם מ\"ה וב\"ן הוי' ואלקים<sup data-n=\"7467\">314</sup> כידוע בענין יב\"ק<sup data-n=\"7468\">315</sup> יחוד ברכה וקדושה שבמצות, וזהו שמצות צריכות כוונה לכוין באופן היחו\"ע שבה דוקא והוא ע\"פ סוד ה' שיש במצות, וכללות ענין שלימות הבירורים דרפ\"ח כו' ע\"י המצות יהי' בימות המשיח דעה\"ד טו\"ר יתעבר<sup data-n=\"7469\">316</sup> כו' ולא יהי' ענין המצות להבדיל בין טו\"ר כעכשיו אלא יהיו המצות כמו שהן למעלה",[["7451","298","<b>כו'</b>: אוצ\"ל: כו')."],["7452","299","<b>ושם נעשה כמצות רצונך</b>: נסמן לעיל פ' שמות כב, ג."],["7453","300","<b>הלכתא למשיחא</b>: נסמן לעיל שם."],["7454","301","<b>ואלה דברי דוד</b>: שמואל-ב כג, א. ראה במדב\"ר פי\"ח, כא. מאמרי אדה\"א שמות ח\"א ע' רכה. וש\"נ."],["7455","302","<b>הקים על</b>: ד: הוקם על הקים."],["7456","304","<b>הנעלה ביותר</b>: א: פנימי' ביותר. ד: היותר נעלה."],["7457","303","<b>משיח. . כתר ש\"ט שעולה ע\"ג ג' הכתרים</b>: ראה אבות פ\"ד, מי\"ג. מאמרי אדה\"א נצבים ח\"ד ע' א'שפה. וש\"נ. נ\"ך ע' רטו. וש\"נ. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300670292\" data-slug=\"torat-chaim\" data-id=\"2300670292\">תו\"ח נח סג, א</a> ובהערה 9. לקמן קסט, ג."],["7458","305","<b>ס\"ג. . שלמעלה מבחי' מ\"ה</b>: נסמן לעיל מ, ד."],["7459","306","<b>א\"ח עט\"ב</b>: משלי יב, ד. ראה גם לעיל ח, ג."],["7460","307","<b>במצות ב' מדרגות</b>: ראה לקמן קסט, ג. מאמרי אדה\"א נ\"ך ע' א ואילך. וש\"נ. שע\"ת יב, ב ובהערה 12."],["7461","308","<b>מצות צריכות כוונה</b>: עירובין צה, ב."],["7462","309","<b>דרפ\"ח ניצוצי'</b>: נסמן לעיל לו, ג."],["7463","310","<b>דמ\"ה מברר לב\"ן</b>: נסמן לעיל ד, ב."],["7464","311","<b>דבחכמה. . אתברירו</b>: נסמן לעיל י, ג."],["7465","312","<b>מצוה. . להוסיף אורות באצי'</b>: לקמן קסט, ג בשם הפע\"ח. ראה פע\"ח בהקדמה. ע\"ח (שער מ\"ן ומ\"ד) של\"ט, דרוש יא כלל טז. מאמרי אדה\"א דברים ח\"ד ע' א'תסז. וש\"נ. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300670063\" data-slug=\"torat-chaim\" data-id=\"2300670063\">תו\"ח לך פ, ג</a> ובהערה 31. לקמן רח, ד. פ' תצוה שלו, ב. ויקהל תיז, ב. תכב, ג. פקודי תנ, א."],["7466","313","<b>יחוד קוב\"ה ושכינתי'</b>: ראה גם לעיל פ' וארא נא, ג. נד, ד. מאמרי אדה\"א ויקרא ח\"ב ע' תקא ואילך."],["7467","314","<b>מ\"ה וב\"ן הוי' ואלקים</b>: ראה גם מאמרי אדה\"א נ\"ך ס\"ע יט. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300670540\" data-slug=\"torat-chaim\" data-id=\"2300670540\">תו\"ח וירא קיט, ב</a>."],["7468","315","<b>יב\"ק</b>: ראה לקמן קס, ד. מאמרי אדה\"א שמות ח\"ב ע' תיג ואילך. דברים ח\"ד ס\"ע א'תקטז ואילך. וש\"נ. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300680464\" data-slug=\"torat-chaim\" data-id=\"2300680464\">תו\"ח תולדות קסב, ג</a> הערה 43."],["7469","316","<b>דעה\"ד טו\"ר יתעבר </b>[א: ניתוסף: מעלמא]: נסמן לעיל פ' שמות כב, ג."]]],[2300540665,"אחר תשלום הכוונה בבירורי' דרפ\"ח כו', והיינו מה שיהי' יתרון מן החשך העליון דתהו כמו קודם השבירה כו' וכמ\"ש אז יאמרו בגוים<sup data-n=\"7470\">317</sup> דוקא הגדיל ה' כו' והיינו ענין טעמים וסודות התורה שיתגלה אז לקטן כגדול כו' (וזה יהי' יותר גבוה מבחי' העבודה דאדה\"ר בג\"ע לעבדה ולשמרה<sup data-n=\"7471\">319</sup> קודם חטא עה\"ד<sup data-n=\"7472\">318</sup> כו' מצד שיהי' יתרון האור מן הבירורי' דעה\"ד כו', וז\"ש שיעשה סעודה לצדיקי' מלויתן ושור הבר<sup data-n=\"7473\">320</sup> כו' וכה\"ג כידוע וד\"ל). והוא בחי' כתר ש\"ט דמשיח שא' בו וגבה מאד לפי שהקים עולה של תו\"מ דהיינו שהקים דבר ה' שבא במצות לברר בירורי' דעה\"ד ע\"י עול תורה ביראה בקבלת עומ\"ש שלימה במל' דא\"ס<sup data-n=\"7474\">321</sup> כמו שהוא למעלה בהעלם דפנימי' הכתר שנק' תר\"ך עמודי'<sup data-n=\"7475\">322</sup> כו'. וזהו ישכיל עבדי כמו שחכמתו עמדה לו לתקן דבר המקולקל כמ\"ש לעשות לתקן<sup data-n=\"7476\">324</sup> רפ\"ח, וז\"ש ורוח אלקי' מרחפת רפ\"ח מ\"ת<sup data-n=\"7477\">325</sup> שזהו רוחו של משיח שנק' עובד אלקי' בחי' ב\"ן<sup data-n=\"7478\">326</sup> כו'. <span data-k=\"pg\">ריט</span> ּ אבל מדרגה הב' במצות הוא מצד עצם מעשה המצוה לבד גם שלא בכוונה וטעם וסוד כמ\"ד מצות א\"צ כוונה כלל והיינו לא בשביל בחי' תיקון ובירור דרפ\"ח כו' כלל אלא רק מפני שא' ונעשה רצונו לבד שזהו <sup data-n=\"7479\">327</sup>רק מצד עצם הרצון שאין טעם לרצון כלל אפי' טעם כמוס כנ\"ל, והוא בחי' הרצון והתענוג הפשוט שבשעשועי' העצמי' שלא יוכל לבא בהתלבשות והרכבה בטעם וסוד לברר בירורים וכה\"ג שזהו המצוה עצמה אע\"פ שנעשי' בלא אוי\"ר שמלובש בה מעצמות הרצון הפשוט שנק' כתר שבכתר שלמעלה מחכ' שבכתר בכלל, וזהו כתר דנעשה שבמ\"ת כו' והוא שם הוי' שבעצמות א\"ס ממש שיתגלה לע\"ל [ב]עוה\"ב (דמצוה בחילוף דא\"ת ב\"ש<sup data-n=\"7480\">328</sup> הוא שם הוי') ונק' מצות הוי' ממש שלמעלה מבחי' הבירורים לגמרי (והוא העוה\"ב שהוא למעלה מבחי' הבירורי' שהוא יום הז' דשבת שנק' ברכת ה' תעשיר<sup data-n=\"7481\">329</sup> שלא ע\"י עבודה ותיקון כלל, משא\"כ בימות המשיח שבא ע\"י הבירורים דשם ב\"ן כמ\"ש הקים על בעול מ\"ש שנק' מצות המלך אע\"פ שיתעלה לבחי' מל' דא\"ס שהוא ההתנשאות שמצד עצמו אין לזה ערך כלל לבחי' השעשועי' העצמיי' מצד עצמו' א\"ס ב\"ה ממש שלמעלה הרבה מבחי' התענוג שבמדת מל' דא\"ס כמ\"ש לך ה' הממלכה<sup data-n=\"7482\">330</sup> כו' וד\"ל).",[["7470","317","<b>אז יאמרו בגוים</b>: תהלים קכו, ב. ראה לעיל פ' שמות לז, א. מא, ב."],["7471","319","<b>דאדה\"ר בג\"ע לעבדה ולשמרה</b>: בראשית ב, טו."],["7472","318","<b>יותר גבוה. . דאדה\"ר. . קודם חטא עה\"ד</b>: ראה גם לקמן פ' ויקהל תכח, ב. שע\"ת ח, א. שה\"א ס, א. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300670186\" data-slug=\"torat-chaim\" data-id=\"2300670186\">תו\"ח בראשית לב, ג</a>. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300680133\" data-slug=\"torat-chaim\" data-id=\"2300680133\">ויחי רלז, ג</a>."],["7473","320","<b>שיעשה סעודה. . ושור הבר</b>: נסמן לעיל ו, ד."],["7474","321","<b>במל' דא\"ס</b>: א: כידוע."],["7475","322","<b>הכתר שנק' תר\"ך עמודי'</b>: נסמן לעיל ח, א."],["7476","324","<b>לעשות לתקן</b>: נסמן לעיל קלט, ד."],["7477","325","<b>ורוח אלקי' מרחפת רפ\"ח מ\"ת</b>: נסמן לעיל לו, ד."],["7478","326","<b>אלקי' בחי' ב\"ן</b>: ראה לעיל הערה 314. לעיל יט, ג. וש\"נ."],["7479","327","<b>רק</b>: אד: ליתא."],["7480","328","<b>דמצוה בחילוף דא\"ת ב\"ש</b>: נסמן לעיל פ' בא קיד, א."],["7481","329","<b>ברכת ה' תעשיר</b>: משלי י, כב [ושם: היא תעשיר]. ראה שע\"ת סו, א ואילך ובהנסמן במ\"מ לשם."],["7482","330","<b>לך ה' הממלכה</b>: דהי\"א כט, יא."]]],[2300540677,"<b>וזהו</b> ענין מדרגת משה שהי' עבד הוי' דהיינו לבחי' שם הוי' שבעצמו' ממש שלמעלה מבחי' הבירורי' דמצות בתיקון דשם אלקי' בחי' ב\"ן כו' והוא לפי שהי' בחי' ממוצע להביא ולהמשיך לבחי' שעשועי' העצמיי' דמהו\"ע א\"ס ב\"ה במצות בפו\"מ שלמעלה מן הכוונה וטעם. וז\"ש בכל ביתי נאמן הוא לחבר להוי' העצמו' בכנ\"י במצות מצד עצמן כמו שהן למעלה במהו\"ע ממש כמ\"ש לכל תכלה ראיתי קץ<sup data-n=\"7483\">331</sup> שיש קץ וגבול לכל עונג שנק' תכלה כמו כלתה נפשי<sup data-n=\"7484\">332</sup> כו' אבל רחבה מצותך מאד<sup data-n=\"7485\">333</sup> בלי קץ וגבול לשעשועי' שבה כלל מטעם הנ\"ל שהמצות מצד עצמן הן בעצמו' השעשועי' כו' רק אפס קצה מזה נמשך גם בתורה כמ\"ש אני תורתך שעשעתי כו' (וכמובן באשרי תמימי דרך<sup data-n=\"7486\">334</sup> כו' שמדבר רק במעלת וחיבוב המצות מצד עצמן דוקא) (ונמצא<sup data-n=\"7487\">335</sup> שבחי' משה למעלה מבחי' מדרגת דמשיח (ואע\"פ שמשה בבחי' פנימי' אבא ומשיח בפנימי' ע\"י<sup data-n=\"7488\">336</sup> זהו בבחי' אור<sup data-n=\"7489\">337</sup> החכ' דתורה גם למעלה<sup data-n=\"7490\">338</sup> אבל במה שירדה חכ' דתורה במעשה המצות בפו\"מ שנק' נובלות זהו למעלה מפנימי' ח\"ע דמשיח כנ\"ל<sup data-n=\"7491\">339</sup>, וזהו דמשה הוא מ\"ש מה שמו מה שם בנו<sup data-n=\"7492\">341</sup> דמ\"ה שמו הוא בחי' מ\"ה היותר עליון שהוא שם הוי' העצמו' הנ\"ל שיתגלה בעוה\"ב שהוא אהי' הב' כנ\"ל ומה שם בנו הוא מ\"ה דחכ' עילאה דמשיח<sup data-n=\"7493\">340</sup> שנק' בן כנ\"ל שנק' אדם בתראה ומשה הוא א\"ק, וזהו שהי' משה עניו מכל האדם<sup data-n=\"7494\">342</sup> כו' להיותו בבחי' מ\"ה ואין האמיתי העצמי ומחמת זה דוקא יהי' העוה\"ב שנא' להנחיל אוהבי יש האמיתי שלמעלה ממשיח אע\"פ שנא' בו וגבה מאד (וזהו שרמזו דכל המשפיל עצמו<sup data-n=\"7495\">343</sup> כמשה שהי' עניו מכל האדם (וא' שלח נא ביד תשלח ע\"י משיח<sup data-n=\"7496\">344</sup> דכל רז<sup data-n=\"7497\">345</sup> לא אניס לי' ונק' מרבה המשרה<sup data-n=\"7498\">346</sup> כו') הקב\"ה מגביהו בעוה\"ב בבחי' יש האמיתי והמגביה עצמו כמשיח שנא' בו וגבה מאד יהי' שפל בערך לגבי משה בעוה\"ב, כי יש בכלל מאתים מנה<sup data-n=\"7499\">347</sup> דאפי' <span data-k=\"pg\">440</span> ּ אור צח ומצוחצח שהוא מקור כל רזי' וסודות דח\"ס כו' אוכם לגבי עה\"ע עצמו שיתגלה בעוה\"ב שהוא [בחי'] עצם הרצון והתענוג הפשוט כו' כנ\"ל וד\"ל). ולפי ערך זה יש גם בכל דור מבחי' משה בכאו\"א מישראל<sup data-n=\"7500\">348</sup> בעשות<sup data-n=\"7501\">349</sup> המצות בשפלות רק לעשות רצה\"ע שבה בלי כוונה יסוד וטעם כמ\"ש שמואל לשאול החפץ לה' בעולות וזבחים כ\"א שמוע<sup data-n=\"7502\">350</sup> כו' והוא ענין שמחה",[["7483","331","<b>לכל תכלה ראיתי קץ</b>: תהלים קיט, צו."],["7484","332","<b>כלתה נפשי</b>: תהלים פד, ג."],["7485","333","<b>רחבה מצותך מאד</b>: ראה גם לעיל פ' וארא סג, ג. וש\"נ."],["7486","334","<b>באשרי תמימי דרך</b>: תהלים קיט. ראה גם מאמרי אדה\"א דברים ח\"ג ס\"ע תתקג ואילך. (תתקט). לקמן קנט, א."],["7487","335","<b>(ונמצא</b>: אד: ונמצא."],["7488","336","<b>שמשה בבחי' פנימי' אבא ומשיח בפנימי' ע\"י</b>: ראה גם שע\"ת נו, ד ובהערה 96."],["7489","337","<b>אור</b>: א: ליתא."],["7490","338","<b>גם למעלה</b>: א: למעלה. ד: שלמעלה."],["7491","339","<b>כנ\"ל</b>: אוצ\"ל: כנ\"ל)."],["7492","341","<b>מה שמו מה שם בנו</b>: נסמן לעיל א, ג."],["7493","340","<b>דמשה. . מה שמו. . ומה שם בנו. . דמשיח</b>: ראה גם לעיל פ' שמות מט, ב. וש\"נ."],["7494","342","<b>משה עניו מכל האדם</b>: בהעלותך יב, ג."],["7495","343","<b>דכל המשפיל עצמו</b>: עירובין יג, ב."],["7496","344","<b>שלח. . ע\"י משיח</b>: שמות ד, יג. נסמן לעיל מד, ב."],["7497","345","<b>משיח דכל רז</b>: ע\"פ דניאל ד, ו. ראה גם מאמרי אדה\"א בראשית ע' יז וע' תד. ויקרא ח\"א ע' מח. במדבר ח\"ג ע' א'מח. דברים ח\"ג ע' תשפט. ח\"ד ע' א'תב. לקמן קצז, ד. רכג, ד."],["7498","346","<b>מרבה המשרה</b>: ישעי' ט, ו [ושם: למרבה). ראה מאמרי אדה\"א קונטרסים ע' שנא ובהנסמן שם."],["7499","347","<b>יש בכלל מאתים מנה</b>: ב\"ק עד, א."],["7500","348","<b>משה בכאו\"א מישראל</b>: ראה גם <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380063\" data-slug=\"likkutei-torah\" data-id=\"4001380063\">לקו\"ת פקודי ה, סע\"ד</a>. מאמרי אדה\"ז על פרשיות התורה ח\"א ע' תיז. <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300061187\" data-slug=\"likkutei-sichot\" data-id=\"1300061187\">לקו\"ש תצוה [כרך ו] ע' 176</a> הערה 41. וע' 177 הערה 44. לעיל פ' וארא פ, ג. לקמן קסב, ד. פ' יתרו רסג, ב. תצוה שמו, ד."],["7501","349","<b>בעשות</b>: א: בעשותו."],["7502","350","<b>החפץ לה'. . כ\"א שמוע</b>: שמואל-א טו, כב [ושם: כשמוע. . הנה שמוע — ראה לקמן פ' ויקהל תטז, א. מאמרי אדה\"א בראשית ע' תקמז. שמות ח\"א ע' ו. וש\"נ]."]]],[2300540689,"ש\"מ<sup data-n=\"7503\">351</sup> מצד המצוה עצמה שממילא יש בכלל מאתים מנה ויזכה לידע הכוונה וסוד שבמצות כידוע במ\"ש האריז\"ל<sup data-n=\"7504\">352</sup> לתלמידו הרח\"ו שלא זכה לג\"א<sup data-n=\"7505\">353</sup> ורוה\"ק ולהשיג טעמי' וסודות דתו\"מ רק מחמת שמחה ש\"מ כפשוטה דוקא (וכמשי\"ת), וזהו שא' דיראה לגבי משה מילתא זוטרתי<sup data-n=\"7506\">354</sup> היא ואע\"פ שא' לישראל ועתה מה ה'<sup data-n=\"7507\">355</sup> שואל מעמך כ\"א ליראה כו', אבל לגבי משה עצמו היראה מילתא כו' לפי שיר\"ת גם בשרשה ביר\"ע<sup data-n=\"7508\">356</sup> אינו אלא בחי' מ\"ה דח\"ע ששרשה בח\"ס והוא מדרג' דמל' דמשיח שהוא במל' דא\"ס לבד כנ\"ל וכמ\"ש בו והריחו ביראת ה'<sup data-n=\"7509\">357</sup> כו', אבל בחי' משה הוא מעצמות הרצון והתענוג שבמהו\"ע ית' במצות כנ\"ל, וז\"ש כי טוב הוא בטי\"ת רבתי דעה\"ח דעדן עצמו כו' ע\"כ גם יר\"ע מלתא זוטרתי לגביו דיראה אותיות ראי' דחכ' ושרשו למעלה מן החכמה, וז\"ש מה שמו בחי' מ\"ה דאין האמיתי שלא שייך שם ראיה דחכמה ולא ביטול במציאות דיר\"ע שאינו רק בבחי' כתר מל' שנק' נורא כנ\"ל, וז\"ש פא\"פ אדבר בו<sup data-n=\"7510\">359</sup> כו' כאשר ידבר איש אל רעהו<sup data-n=\"7511\">360</sup> כו' וד\"ל.\n<b>ובכ\"ז</b> יובן מ\"ש ויאמינו בה' ובמשה עבדו, פי' אחר שהי' להם בחי' היראה דראי' דחכ' בהשגה וטעם כמו השגת טעם וסוד שבמצות כמ\"ש וייראו העם את הוי' שבהעלם הרצון דכ\"ע כנ\"ל, אח\"כ א[מר] ויאמינו בה' שהוא בחי' הוי' העצמות דא\"ס שבמצות מצד עצמן שאין טעם כמוס דסוד דח\"ע מגיע לשם כלל והוא בחי' שעשועי' העצמיי' שיתגלה בעוה\"ב וכמ\"ד מצות א\"צ כוונה כנ\"ל שזהו בחי' משה עבד הוי' הזה כנ\"ל שהוא למעלה משם הוי' דכתר כו'. ואע\"פ שמשה נק' ר\"מ להמשיך לאמונה זו שבמהו\"ע הרצון הפשוט דמצות בכנ\"י בבחי' חיות גמור כנ\"ל, עכ\"ז עכשיו עצמו' התענוג ורצה\"ע הזה הוא מלובש בהעלם בלבוש גשמי' דמעשה המצות בגשמי' עכ\"פ רק שלע\"ל בעוה\"ב יתגלה מן הלבוש והעלם זה כמ\"ש ולא יכנף עוד כו'. ועוד טעם העיקר בזה שבאמת שרש ענין עצמו' הרצה\"ע הזה שבמצות הוא בעצמות אוא\"ס ממש שנק' סדכ\"ס דלמחת\"ב כו' שלא יגיע שם בחי' גילוי דראי' והשגה דח\"ע כלל להיותו בבחי' שעשועי' העצמיי' שהוא נסתר ונעלם בעצמו ממש דלמת\"ב אפי' לח\"ע הקדומה רק בבחי' אמונה לבד יותפס, וע\"כ א[מר] ויאמינו בהוי' העצמו' שא\"א שיבא בהשגה וראי' שאין ראיה והשגה רק בדבר הנגלה ונראה בקירוב אחר קירוב במדרגה גבוה יותר כמשיח שא' בו וגבה מאד כו' שהי' לו קירוב יותר בעילוי דראי'",[["7503","351","<b>ש\"מ</b>: אגד: של מצוה."],["7504","352","<b>במ\"ש האריז\"ל</b>: נסמן לעיל פ' וארא נה, א."],["7505","353","<b>לג\"א</b>: א: לגילוי אליהו. ג: לגילוי אלקות. וראה גם לעיל פ' בא צח, א הערה 80."],["7506","354","<b>דיראה לגבי משה מילתא זוטרתי</b>: ברכות לג, ב. ראה גם ש\"א מא, ב ובהנסמן במ\"מ לשם. לקמן רכה, א."],["7507","355","<b>ועתה מה ה' </b>[א: ניתוסף כו']<b>: עקב י, יב [ושם</b>: ועתה ישראל]."],["7508","356","<b>שיר\"ת. . בשרשה ביר\"ע</b>: נסמן לעיל קכה, ג."],["7509","357","<b>והריחו ביראת ה' </b>[א: ב' תיבות אחרונות ליתא]: ישעי' יא, ג."],["7510","359","<b>פא\"פ אדבר בו</b>: בהעלותך יב, ח."],["7511","360","<b>כאשר ידבר איש אל רעהו</b>: תשא לג, יא."]]],[2300540701,"דח\"ע הי' ביראה פנימי' יותר, אבל לגבי משה שהי' נאמן באמונה דמהו\"ע ממש שלמעלה מן ההתגלות כנ\"ל אין היראה <span data-k=\"pg\">רכ</span> ּ חשובה כלום וזהו דיראה מלתא כו', ולכך א' ויאמינו גם במשה עבדו בחי' עבד נאמן להוי' העצמי' הנ\"ל (דפסיק טעמא בין ב' הויות<sup data-n=\"7512\">361</sup> כו'), שגם שהמשיך משה לכנ\"י אמונה זו בגילוי וחיות וגם העלם וקשרם למעלה בחבלי עבותות באמונה זו באמתת מהו\"ע שבמצות כנ\"ל כרועה צאן הנאמן כו' שזנם ומפרנסם כו' כמ\"ש ורעה אמונה כנ\"ל, מ\"מ הכל הוא בבחי' אמונה דוקא כמו שהאמינו בהוי'<sup data-n=\"7513\">362</sup> העצמו' כן האמינו במשה עבד הוי' זה בקיום המצות בפו\"מ, אבל זה יהי' עיקר העוה\"ב שאז תבוא אמונה זו דוקא לגילוי גמור כנ\"ל שזהו העדן דשעשועי' העצמי' שע\"ז א' אשר אהי' כו' כנ\"ל וד\"ל. וזה הי' בקי\"ס<sup data-n=\"7514\">363</sup> כשא' זה אלי זה לנוכח ממש כו' בראי' מקרוב למה שהאמינו בהוי' רק שהי' זה למעלה בשרש נשמתם ולא למטה ממש כעוה\"ב, וז\"ש אז ישיר<sup data-n=\"7515\">364</sup> אז דוקא ישיר להבא כו' וכמ\"ש שם נשמחה בו שהן א' בקי\"ס שירת הים כמו שיהי' לע\"ל ממש, וז\"ש אשירה לה'<sup data-n=\"7516\">365</sup> כי גאה גאה בחי' רוממות והתנשאות שמצד עצמו שנכלל בשעשועי' העצמיי' ובזה נכללו ונתעלו ישראל עם משה יחד ועלו עמו מחמת האמונה זו שהאמינו בה' ובמשה עבדו כנ\"ל כמ\"ש אז ישיר משה ובנ\"י יחד וד\"ל. וז\"ש בקי\"ס ואתם תחרישון וא' בזהר לא תתערו מידי<sup data-n=\"7517\">366</sup> בהעלאת מ\"ן בתפלה אפי' בקבלת תו\"מ ביראה כו' לפי שבמהו\"ע לא יגיע גם היראה בביטול המציאות כש\"ע כו' רק בחי' השתיקה כדומם ממש, דמה\"ש<sup data-n=\"7518\">*367</sup> קול דממה דקה<sup data-n=\"7519\">367</sup> זה[ו] קול בלחש בש\"ע, אבל בסדכ\"ס עצמו ממש דאפי' אור צח כו' אין מגיע שם רק בחי' הביטול דשתיקה ממש וד\"ל.\n<b>וזהו</b> הפך ים ליבשה בנהר יעברו ברגל שם נשמחה בו, והנה יש להבין בזה מאחר שמבואר למעלה בשרש בחי' קי\"ס ויצ\"מ שהוא כמו לע\"ל ממש בעוה\"ב (שהוא שם אהי' הב' כנ\"ל) א\"כ למה א' שם נשמחה בו לשון להבא שאנו עתידים לשמוח בו שם דוקא ולא עכשיו והלא בקי\"ס ודאי הי' שמחה זאת ממש בשירת הים כמ\"ש אז ישיר משה כו' כנ\"ל, והול\"ל שם שמחנו בו (ועוד דמ\"ש בנהר יעברו ברגל להבא קאי בימות המשיח דכתי' והניף ידו על הנהר<sup data-n=\"7520\">368</sup> כו' והיתה מסילה<sup data-n=\"7521\">369</sup> כו' וע\"ז א' שם דוקא נשמחה בו ממש בעוה\"ב הוא אחר ימות המשיח כנ\"ל וכמ\"ש עד יעבור עמך ה' עד יעבור עם זו קנית כנ\"ל). אך הנה תחלה יש להבין ענין השמחה שהוא המביא כל העלם לגילוי<sup data-n=\"7522\">370</sup> כידוע",[["7512","361","<b>דפסיק טעמא בין ב' הויות</b>: תשא לד, ו. זהר (אד\"ר) נשא קלח, רע\"א. ראה הנסמן במאמרי אדה\"א נ\"ך ע' תקעז. קונטרסים ע' שדמ. הנחות תקע\"ז כאן ע' נב. ש\"א מג, א ובהנסמן במ\"מ בריש המאמר שם."],["7513","362","<b>בהוי'</b>: א: בנ\"י בהוי'."],["7514","363","<b>בקי\"ס</b>: א: בקי\"ס ג\"כ."],["7515","364","<b>אז ישיר</b>: בשלח טו, א. ראה סנהדרין צא, ב."],["7516","365","<b>אשירה לה'</b>: המשך הכתוב אז ישיר."],["7517","366","<b>ואתם תחרישון. . לא תתערו מידי</b>: בשלח יד, יד. ראה זהר בשלח מז, ב [ובסה\"מ תרל\"ד ע' קיח: שת\"י]. לקמן קפב, ב. קצג, ד."],["7518","*367","<b>ממש דמה\"ש</b>: ד: דמה שנק'."],["7519","367","<b>קול דממה דקה</b>: מלכים-א יט, יב."],["7520","368","<b>והניף ידו על הנהר</b>: ישעי' יא, טו."],["7521","369","<b>והיתה מסילה</b>: נסמן בסמוך בהערה 385."],["7522","370","<b>השמחה שהוא המביא כל העלם לגילוי</b>: ראה גם מאמרי אדה\"ז תקס\"ו כאן (ע' קמח). תו\"ח ויצא קעג, ב ובהערה 12. להלן קסב, ג."]]],[2300540713,"בחוש שכאשר ישמח האדם בנפשו אזי יגלה כל מצפוני לבבו שהי' בסוד נעלם בנפשו ולא יוכל לעצור רוחו כלל, לפי שהשמחה הזאת ה[י]א שמחת הנפש עצמה ומהותה שגורם בחי' ההתגלות כל עצמו' ומהותה כמו שהיא בלא לבוש והעלם כלל ע\"כ תצא מכל העלם לגילוי דוקא, ונמצא שהשמחה פועלת גילוי אור העצמו' וממילא נגלה כל בחי' ההעלם. ואמנם זה גופא מה שיש בטבע השמחה לגרום גילוי אור העצמות הנה ידוע שבאה ע\"י התפעלות הנפש בעונג נפלא וחדש שנוגע בעצם הנפש שמזה יגיל בחדוה גדולה בעצם הנפש ואז מתגלה העונג וחדוה זו לבא בבחי' התפשטות בגילוי, והוא ענין השמחה שהוא גילוי העונג והחדוה הנעלמה בלבו ונפשו כמו מאיזה בשורה טובה ונפלאה שיעשה <span data-k=\"pg\">442</span> ּ משתה ושמחה בגילוי, ואמנם עיקר גילוי ההעלם שבנפשו בא' בשמחת לבו דוקא ולא כשהוא בעונג וחדוה צפונה בלבו עדיין כידוע. והטעם הוא לפי שיש ב' מיני עונג וחדוה והן ב' מיני שמחה א' העונג המורכב בדבר מה שאינו בעצם נקודת הנפש עצמה כמו העונג המורכב ברצון ושכל ומדות כו' וכמו בשורה טובה מן הון ועושר וגדולה או מכיבוש וניצוח לשונאו שהוא השלמת עונג רצונו וכן מתענוג גדול שבחכ' נפלאה וכן במדות כאהבה בתענוגים וכה\"ג. והב' עונג הפשוט ועצמי שנוגע בעצם דיחידה שבנפש כמו מבשורת הצלת בנו יחידו שאוהבו כנפשו כבשורת יעקב מיוסף שנא' ותחי רוח יעקב<sup data-n=\"7523\">371</sup> כו' וכן היוצא משבי' מס\"נ<sup data-n=\"7524\">372</sup> לחיים ולגדולה יתירה, ששמחה זו אע\"פ שבאה מן ההיפוך שהוא תכלית העוצב והמרירות שנגע עד הנפש אמנם זהו עצמו הגורם שישמח בעצם נקודת נפשו והוא בחי' העונג ושעשועי' שבעצמיות ממש, וזהו שנק' שמחת הנפש מצד עצמותה ממש שבלתי יכול לבוא בהרכבה בשום דבר מה גם לא ברצון וחכ' ומדות שאין להם ערך כלל אליה. ויובן מזה הטעם שהשמחה גורמת גילוי ההעלם בהתפשטות' דוקא לפי שגם השמחה מבשורה טובה שבעונג המורכב ברצון וחכ' ומדות יגיע לשמחה ועונג הנפש עצמה הפשוט שיגלה כל העלם כו'.\n<b>ועד\"ז</b> יובן ג\"כ בבחי' שמחה האלקי' בכנ\"י מלמטה למעלה שיש ב' מיני שמחה וכך הוא מלמעלה למטה, א' שמחה בהוי' כמו בגילוי העונג להתענג על הוי' באה\"ר שיגיל וישמח בה' שגורם בחי' גילוי ההעלם דעצמו' למעלה ג\"כ בשמחה עליונה שהוא שמחה של שם הוי' שבכתר שיתגלה מהעלמו שהי' בסוד וטעם כמוס דרצה\"ע, וכמו בימות המשיח שיתגלו טעמי וסודות התורה וכג\"א<sup data-n=\"7525\">373</sup> ורוה\"ק וגם מה שנעלם בקוצו ש\"י כו', וכמו השמחה בשם הוי' דאצי' בגילוי ההעלם דמוחי' דאו\"א בז\"א שכ\"ז בא מבחי' עונג העליון שמורכב ברצון וחכ' ומדות כו'",[["7523","371","<b>ותחי רוח יעקב</b>: ויגש מה, כז."],["7524","372","<b>משבי' מס\"נ</b>: א: מבית האסורים ומסכנת נפשות. וראה בסמוך ד\"ה ועד\"ז שו\"ה לגאולה."],["7525","373","<b>וכג\"א</b>: א: וכגילוי אליהו. וראה לעיל הערה 353."]]],[2300540725,"(שנק' ע\"ק והתגלות ע\"י במועדי' בשמחה דבינה<sup data-n=\"7526\">375</sup> דוקא מטעם הנ\"ל) והשמחה הוא המגלה כל העלם העונג שברצון וחכ'<sup data-n=\"7527\">374</sup> ומדות כמו העונג מבשורה טובה כנ\"ל. אך המדרגה הב' הוא שמחה ועונג העצמו' ממש ובכנ\"י הי' שמחה זו בעצמות נפשם ממש, והוא מה שיצאו מאפילה לאור גדול משעבוד קשה לגאולה<sup data-n=\"7528\">376</sup> שזה כיוצא משבי' וסכ\"נ לגדולה יתירה שלמעלה הוא מענג המורכב באיזה רצון כו', כי הרי הוא בנקוד' העצמיות ממש ולמעלה גורם שמחה עליונה שבעצמו' א\"ס ממש שהוא העונג הפשוט שבשעשועי' העצמיי' כמו בהצלת בנו יחידו כו'. וכך הוא ענין התענוג העצמי בהצלת בנ\"י שהוציאם מעבדות לחירות ומאפילה לאור גדול כו' שזהו למעלה הרבה מעונג המורכב ברצה\"ע וח\"ע כו'. וזהו שא' הפך ים כו' שם נשמחה בו לע\"ל דוקא דבקי\"ס הי' שמחת הנפש עצמה בכנ\"י בשירת הים כמו שיהי' לע\"ל שנשמחה בו ממש שלמעלה הרבה משמחה שבהוי' דכתר וחכ' כו', וזהו גילוי ההעלם דעונג ושעשועי' העצמיי' שמצד עצמותו ממש שמלובש עכשיו במצות בפו\"מ מצד עצם התענוג כו' והוא שמחה ש\"מ בכנ\"י שלא מצד הכוונה וטעם בסוד הוי' כו' כנ\"ל. ואמנם ביצ\"מ הי' התענוג העצמי הזה מלובש ומוסתר עדיין בחומר הגופני בשעבוד עניני עוה\"ז ולא הי' יכול לבא שמחה זו בהתגלות רק בקי\"ס שראו <span data-k=\"pg\">רכא</span> ּ מקרוב כל בחי' ההעלם דמהו\"ע התענוג העליון כמ\"ש זה אלי כו', ועכ\"ז הרי לא ראו במהו\"ע שעשועי' העליונים דעצמו' א\"ס רק גילוי כחו במה שעשה לשם הוי' העליון דרצה\"ע שבא לגילוי כנ\"ל, ואמנם לע\"ל בעוה\"ב א' שם נשמחה בו ממש בלי לבוש והסתר כלל וכלל דמה שהאמינו בהוי' זה העצמות בקי\"ס שיכול לבוא לגילוי בשמחה זו העצמיות (וכן עתה באמונה דמעשה המצות בשמחה של מצוה מצד עצם הרצון והתענוג כו') הוא שבא לגילוי ממש לע\"ל, וז\"ש נשמחה לעתיד וד\"ל (ועכ\"ז גם במועדים לשמחה בהוי' דאצי' אנו או' וישמחו בך ממש מקדשי שמך<sup data-n=\"7529\">377</sup> כו' לפי שמגיע לשמחה שבעצמו' ממש מטעם הנ\"ל, אבל שמחה ש\"מ הוא שמחה העצמו' ממש שיהי' לע\"ל כנ\"ל).\n<b>ומעתה</b> הנה יש להבין מ\"ש הפך ים<sup data-n=\"7530\">378</sup> לשון עבר בנהר יעברו ברגל ל' להבא<sup data-n=\"7531\">379</sup>, עבר ועתיד בענין א', ושם נשמחה משמע שם בהעברת הנהר ובאמת שמחה זו דנשמחה בו בעוה\"ב הוא כנ\"ל, אך הנה א[מר] דכל ימי חייך להביא לימות המשיח<sup data-n=\"7532\">380</sup> כו', דהנה באמת הנה ידוע דהעברה זו בנהר פרת בימות המשיח כשיהי' קיבוץ גליות (כמ\"ש בישעי' י\"א) אחר שדיבר במשיח ויצא חוטר<sup data-n=\"7533\">381</sup> כו' והי' ביום ההוא יוסיף ה' לקנות את שאר עמו אשר ישאר מאשור<sup data-n=\"7534\">382</sup> כו' ואסף נדחי ישראל<sup data-n=\"7535\">383</sup> כו' והחרים ה' את לשון ים מצרים והניף ידו על הנהר בעים רוחו והכהו לז' נחלים<sup data-n=\"7536\">384</sup>",[["7526","375","<b>במועדי' בשמחה דבינה</b>: נסמן לעיל קמט, ג."],["7527","374","<b>ומדות כו'. . וחכ'</b>: א: ליתא. וכנראה נשמט מפני תיבות הדומות: וחכ'. . וחכ'."],["7528","376","<b>מאפילה לאור גדול משעבוד. . לגאולה</b>: ע\"ד פסחים קטז, ב (במשנה). הגש\"פ פיסקא לפיכך."],["7529","377","<b>וישמחו בך. . מקדשי שמך</b>: נוסח תפלת העמידה ליו\"ט [בדילוג]."],["7530","378","<b>ים</b>: א: ניתוסף: ליבשה."],["7531","379","<b>הפך. . לשון עבר. . ל' להבא</b>: ראה גם לעיל קלט, א. וש\"נ."],["7532","380","<b>דכל ימי חייך. . המשיח</b>: פ' ראה טז, ג. ברכות יב, ב (במשנה ועה\"ג שם). הגש\"פ פיסקא ארב\"ע."],["7533","381","<b>ויצא חוטר</b>: ישעי' שם פסוק א."],["7534","382","<b>והי'. . ישאר מאשור</b>: שם, יא [בדילוג]."],["7535","383","<b>ואסף נדחי ישראל</b>: שם, יב."],["7536","384","<b>והחרים. . לז' נחלים</b>: שם, טו."]]],[2300540737,"כו' והיתה מסילה לשאר עמו כו' כאשר היתה ביום עלותו מאמ\"צ<sup data-n=\"7537\">385</sup> ) הרי יהי' אז במעלה ומדריגה יתירה מקי\"ס אחר שיהי' ביעור הרע לגמרי כמ\"ש ולא ירעו כו' כי מלאה הארץ דעה<sup data-n=\"7538\">386</sup> כו' וז\"ש עד יעבור עמך ה' כו'. והענין הוא כידוע דקי\"ס הי' בבחי' המל'<sup data-n=\"7539\">388</sup> ה\"א אחרונה<sup data-n=\"7540\">389</sup> שנק' ים סוף סופא דכ\"ד<sup data-n=\"7541\">390</sup> והוא שנהפך ים ליבשה בבחי' עדאת\"ג והי' בזה הכנה רק לגילוי קבלת התו\"מ<sup data-n=\"7542\">387</sup> בנגלה בפו\"מ במ\"ת, אבל העברה שניה בנהר יעברו ברגל זה יהי' בבחי' בינה שנק' נהר<sup data-n=\"7543\">391</sup> שיוצא מעדן<sup data-n=\"7544\">392</sup> כו' ה\"א ראשונה<sup data-n=\"7545\">393</sup> שנק' עדאת\"כ בכלל, וזה יהי' בשביל גילוי פנימי' התורה מעונג ושעשועי' העליונים שבח\"ע דתוה\"ק כו' שנגלה כל בחי' העלם וסוד דח\"ס שהוא בחי' רצון הנעלם בחי' פנימי' הכתר שז\"ש אהי' אנא זמין לאתגלאה כנ\"ל וא\"א שיבא לגילוי כל בחי'<sup data-n=\"7546\">394</sup> העלם הח\"ע דפנימי' התורה כ\"א ע\"י בקיעה בנהר זה העליון שיוצא מעדן עילאה שהוא שעשועי' העצמיי' שנמשך בתורה כמ\"ש ואהי' אצלו כו' שעשועים יום יום כו' כמו שהי' בקי\"ס שנגלה ההעלם עצמו כו' כמ\"ש וישם הים לחרבה כנ\"ל, וזהו מצד שבא מכח העצמו' דשעשועי' שבמהו\"ע א\"ס שלמעלה מעונג דח\"ע דתורה שבוקע הנהר ועושה כל בחי' ההעלם לגילוי (כנ\"ל בענין רוח קדים עזה כו' שהים ראה וינוס כו') עד שלא נשאר שום רושם לחלוחית מים דחו\"ב שבהעלם כו' והי' מסילה ביבשה לשאר עמו כו', והוא מה שיהי' דרך ה' בפנימי' וסודות התורה כמו הנגלות לנו עכשיו ממש (כדוגמא שהנס נעשה כמו טבע גשמי' כו') וזה מורה על שלימות הבירורי' דעה\"ד טו\"ר בתכלית כנ\"ל כי יהופך גם חשך לאור ואז יהי' ההעלם דחשך סתרו לגילוי אור, וז\"ש והניף ידו על הנהר בעיים רוחו שזהו רוח אלקי' שנק' רוח קדים כו' שהי' בקי\"ס, רק שבקי\"ס הי' רק בקיעה א' כמ\"ש <span data-k=\"pg\">444</span> ּ ויבקעו המים<sup data-n=\"7547\">395</sup> (רק שנחלק לי\"ב גזרים ליב\"ש<sup data-n=\"7548\">396</sup> כמ\"ש לגוזר י\"ס לגזרים<sup data-n=\"7549\">397</sup> נגד י\"ב ג\"א<sup data-n=\"7550\">398</sup> שכלול בשם הוי'<sup data-n=\"7551\">399</sup> דשם מ\"ה ששרשו בהוי' העצמי' ממש כמשי\"ת) ובנהר דלע\"ל א[מר] והכהו לז' נחלים לז' בקיעות<sup data-n=\"7552\">400</sup> והדריך בנעלים.",[["7537","385","<b>והיתה מסילה. . מאמ\"צ</b>: שם, טז [ושם: היתה לישראל]."],["7538","386","<b>כמ\"ש </b>[א: ליתא]<b> ולא [אגד</b>: לא] ירעו. . דעה: שם, ט."],["7539","388","<b>דקי\"ס הי' בבחי' המל'</b>: ראה גם <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380143\" data-slug=\"likkutei-torah\" data-id=\"4001380143\">לקו\"ת צו טז, ד</a>. שה\"א פט, ב. צ, א. ב. לקמן קפה, ג."],["7540","389","<b>המל' ה\"א אחרונה</b>: ראה זהר ויקרא יז, א. תו\"ח ויצא קסז, ג הערה 38."],["7541","390","<b>ים סוף סופא דכ\"ד</b>: נסמן לעיל קלז, ד."],["7542","387","<b>דקי\"ס. . הכנה קבלת התו\"מ</b>: נסמן לעיל קמח, ג."],["7543","391","<b>בינה שנק' נהר</b>: ראה זהר (אדרא דמשכנא) משפטים קכג, ב."],["7544","392","<b>נהר שיוצא מעדן</b>: בראשית ב, י."],["7545","393","<b>בינה. . ה\"א ראשונה</b>: נסמן בהערה 389."],["7546","394","<b>לגילוי כל בחי'</b>: א: ליתא."],["7547","395","<b>ויבקעו המים</b>: בשלח יד, כא."],["7548","396","<b>לי\"ב גזרים ליב\"ש</b>: ראה פדר\"א פמ\"ב. מאמרי אדה\"א ויקרא ח\"א ע' רכא. וש\"נ. שה\"א סח, ב ובהערה 22. לקמן קפה, ג."],["7549","397","<b>לגוזר י\"ס לגזרים</b>: תהלים קלו, יג."],["7550","398","<b>י\"ב ג\"א </b>[אגד: גבולי אלכסון]: נסמן לעיל פ' בא קכז, ד."],["7551","399","<b>י\"ב ג\"א. . הוי'</b>: ראה גם מאמרי אדה\"א ויקרא ח\"א ע' ח."],["7552","400","<b>לז' נחלים לז' בקיעות</b>: ראה גם מאמרי אדה\"ז תקס\"ו כאן (ע' קמח). מאמרי אדה\"א הנחות תקע\"ז כאן (ע' נו). שה\"א צו, ב. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380145\" data-slug=\"likkutei-torah\" data-id=\"4001380145\">לקו\"ת צו יז, ב</a> ואילך. לקמן קפה, ג."]]],[2300540749,"<b>והענין</b> הוא דבקי\"ס הי' בבחי' המל' שהי' בשביל קבלת התו\"מ בפו\"מ כנ\"ל הי' הבקיעה להיות בחי' גילוי מל' שמים כמ\"ש זה אלי כו' שא' ונעשה רצונו<sup data-n=\"7553\">401</sup> בפו\"מ כענין שא' במ\"ת נעשה<sup data-n=\"7554\">402</sup> (כמו שאנו או' מלכותך ראו בניך<sup data-n=\"7555\">403</sup> כו'), אבל בהעברת הנהר לעתיד שיהי' בבחי' גילוי ההעלם דח\"ס סודות התו' א[מר] והכהו לז' נחלים שהן בחי' ז' המדות העליונות שברצה\"ע הנעלם שבאים בבחי' התחלקות מן טעם<sup data-n=\"7556\">404</sup> כמוס לרצה\"ע שבנהר שיוצא מעדן שהוא בחי' בינה שבכתר, וע\"כ הכהו לז' נחלים דוקא שהן בחי' ז' ימי קדם שבפנימי' ע\"י וא\"א שבאי' לגילוי מן ההעלם ע\"י שלימות הבירורי' דז\"מ דתהו שיעלו לשרשם בבחי' ס\"ג דבינה שבכתר שהוא שם אהי' הא' כנ\"ל, והוא בימות המשיח בקיבוץ גליות דכתי' בי' ישכיל עבדי כו' וגבה מאד למעלה גם מן האבות ששרשם בחג\"ת דא\"א<sup data-n=\"7557\">405</sup> כו' וכמ\"ש והטבך והרבך מאבותיך<sup data-n=\"7558\">406</sup> כו'. וזהו והדריך בנעלים דוקא לפי שיהי' בחי' שלימות הבירורי' דרפ\"ח בבחי' ב\"ן דנוגה שהוא בחי' המל'<sup data-n=\"7559\">407</sup> דעור דנוגה התחתון שנק' כתנות עור<sup data-n=\"7560\">408</sup> בעי\"ן שיבורר ויעלה לשרשו בחי' חשמ\"ל העליון שנק' חשך סתרו<sup data-n=\"7561\">409</sup> שיאיר מהעלמו כנ\"ל שהוא בחי' ס\"ג דתהו<sup data-n=\"7562\">*410</sup> שנק' כתנות או\"ר באל\"ף אחר הבירור השלם כמו שא' שבתורתו של ר\"מ<sup data-n=\"7563\">410</sup> הי' כתוב כתנות או\"ר בא[ל\"ף], וזהו שהדריך אותו בנהר דלע\"ל כו'<sup data-n=\"7564\">411</sup> בנעלים דוקא שהוא נעל דעור דחשמ\"ל דק\"נ שיהי' בתכלית הבירור שמעין זה הי' בעולי רגל דכתי' יראה כל זכורך<sup data-n=\"7565\">412</sup> את פני ה' א', מה יפו פעמייך בנעלים<sup data-n=\"7566\">413</sup> כו' (והוא מה שעכשיו נעל זה של עור שאסור ביו\"כ<sup data-n=\"7567\">414</sup> כענין חנוך הי' תופר מנעלים<sup data-n=\"7568\">415</sup> לשכינה כו') (וביהושע שהוא בחי' המל' פני לבנה<sup data-n=\"7569\">416</sup> בהתלבשות בבריאה א' של נעלך<sup data-n=\"7570\">417</sup> כו') לפי שבחי' שם הוי' הנעלם שבפנימי' הכתר יהי' אז בגילוי גמור כמו שם הוי' דאצי' ויהי' חיבור גמור בין ב' הויות להיות בבחי' א' ממש וד\"ל.\n<b>וזהו</b> ענין עין בעין יראו<sup data-n=\"7571\">418</sup>, פי' בחי' סוכ\"ע הכללי שמקיף וסובב לאבי\"ע בהשוואה א' שזהו בחי' שם הוי' שבכתר",[["7553","401","<b>שא' ונעשה רצונו</b>: ע\"פ ספרי פינחס כח, ח."],["7554","402","<b>שא' במ\"ת נעשה</b>: יתרו יט, ח. משפטים כד, ג. ז."],["7555","403","<b>מלכותך ראו בניך</b>: תפלת ערבית."],["7556","404","<b>מן טעם</b>: א: טעם. ד: בטעם."],["7557","405","<b>האבות ששרשם בחג\"ת דא\"א</b>: ראה גם לקמן קצט, ד (ע\"י וא\"א). רא, ד. רד, ד (ע\"י). ריא, ג. פ' תצוה שעג, ב (ע\"י וא\"ק). פקודי תנז, ג (ע\"י). <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380278\" data-slug=\"likkutei-torah\" data-id=\"4001380278\">לקו\"ת בחוקותי מז, א</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380146\" data-slug=\"likkutei-torah\" data-id=\"4001380146\">צו יז, ג</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380771\" data-slug=\"likkutei-torah\" data-id=\"4001380771\">עקב יד, ב</a> (ושולל שם בחי' עתיק). נצבים נג, א (ומציין שם לד\"ה אם בחוקותי). ברכה צו, ג. מאמרי אדה\"א דברים ח\"ב ע' שצא. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300670340\" data-slug=\"torat-chaim\" data-id=\"2300670340\">תו\"ח לך פה, ב</a> ובהערה 11. שה\"א כה, א ובהערה 4."],["7558","406","<b>והטבך והרבך מאבותיך</b>: נצבים ל, ה."],["7559","407","<b>המל'</b>: אגד: חשמ\"ל. ראה הנסמן לעיל פ' שמות א, ג הערה 43."],["7560","408","<b>חשמ\"ל. . כתנות עור</b>: בראשית ג, כא. ראה הנסמן במאמרי אדה\"א נ\"ך ע' שיח. לקמן פ' ויקהל תה, ד. תיט, ד."],["7561","409","<b>חשמ\"ל העליון שנק' חשך סתרו</b>: נסמן לעיל פ' שמות א, ג הערה 43."],["7562","*410","<b>חשך סתרו. . דתהו</b>: ראה גם לקמן פ' משפטים רפז, ב. שער האמונה מג, א ובהערה 1."],["7563","410","<b>כתנות או\"ר. . שבתורתו של ר\"מ</b>: נסמן לעיל פ' שמות ח, ב."],["7564","411","<b>שהדריך אותו </b>[גד: אותם]<b>. . כו'</b>: א: שידריך אותם לע\"ל בנהר."],["7565","412","<b>יראה כל זכורך</b>: פ' ראה טז, טז."],["7566","413","<b>מה יפו פעמייך בנעלים</b>: נסמן לקמן קצח, ג."],["7567","414","<b>נעל. . שאסור ביו\"כ</b>: ראה שו\"ע אדה\"ז הל' יוהכ\"פ סתרי\"ד, ס\"ב."],["7568","415","<b>חנוך הי' תופר מנעלים</b>: ראה של\"ה רפה, ב בשם המדרש. ס' מאירת עינים פ' לך [לר\"י דמן עכו ירושלים תשל\"ה ע' סז]. הנסמן במאמרי אדה\"ז על פרשיות התורה ח\"א לע' נא. מאמרי אדה\"א נ\"ך ע' רצט. הנחות תקע\"ז ע' קצב. לקמן קצח, ג. פ' משפטים רצד, ג."],["7569","416","<b>וביהושע. . פני לבנה</b>: ב\"ב עה, סע\"א. ראה מאמרי אדה\"א נ\"ך ע' תסא ואילך. שה\"א מד, ב."],["7570","417","<b>של נעלך</b>: יהושע ה, טו."],["7571","418","<b>עין בעין יראו</b>: ישעי' נב, ח."]]],[2300540761,"הכללי שנק' רצון הנעלם ומח' הקדומה שכוללת כל ההשתל' יבא אז מהעלם לגילוי ממש דהיינו שיראו אותו בעין השכל בבחי' ראיה והשגה ממש וכמ\"ש ונגלה כבוד הוי' כו', וזהו עין דכנ\"י יראו בעין העליון דבחי' מקיף הכללי דשם הוי' העליון שזהו בחי' התחברות דעין המקבל עם עין המשפיע שיתחברו ב' הויות העליון עם התחתון להיות לאחדים ממש כמ\"ש ביום ההוא יהי' הוי' אחד יהי\"ה ב\"פ י\"ה<sup data-n=\"7572\">419</sup> היינו עלדא\"ת עם עלד\"א, כי בחי' ההעלם עצמו דסוד הוי' שבכתר יהי' בגילוי בהוי' דלתתא ממש (כמו ראיי' דעולי רגלים בשם הוי' דז\"א כשם שבא לראות<sup data-n=\"7573\">420</sup> כו' דכתיב עיניך יונים<sup data-n=\"7574\">421</sup> כו' כך יהי' ראיי' דהוי' דז\"א בהוי' העליון דא\"א ושם נק' עין [אחד] כמ\"ש הנה עין ה' אל יריאיו<sup data-n=\"7575\">422</sup> כו' בחי' עינא פקיחא<sup data-n=\"7576\">423</sup> כו' שלמעלה מהתחלקות השכל במדות דתרין עיינין כלולים כא'<sup data-n=\"7577\">424</sup> בבחי' רצה\"ע הנעלם טרם שמתחלק בטעם כמוס לחו\"ג כו', משא\"כ בחכ'<sup data-n=\"7578\">425</sup> שבמדות שהן ב' עיני' ועיני הוי' משוטטי'<sup data-n=\"7579\">426</sup> וכנ\"י נק' עיני העדה כו') <span data-k=\"pg\">רכב</span> ּ וזהו בחי' כתר שבכתר בחי' ג\"ר דע\"י שבוקע המסך המפסיק בח\"ס בין קדה\"ק כו', שז\"ש והכהו לז' נחלים שיבקעו בחי' המדות דרצון הנעלם כמו שהן בעצם הרצון כמ\"ש ההרים תרקדו<sup data-n=\"7580\">427</sup> כו' כמו שהים הפך ליבשה כנ\"ל וע\"כ יהי' גילוי כל סוד הנעלם כמ\"ש עושה פלא (ומ\"ש לז' נחלים שהן ז' מדות דבינה היינו שיעברו לנהר דבינה דמה שלמעלה מן ההשגה שנק' פלא יראו בהשגה בעין וזהו יעברו ברגל ביבשה שיהי' ז' מסילות כו' וכמ\"ש ולא ילמדו עוד כו' וד\"ל) (ושרש הראשון היינו בחי' מל' דא\"ס שלפני הצמצום דחשך סתרו שיבקע ההעלם ויעשנו גילוי ויאיר כאור והוא ענין הנ\"ל בוי\"ו דוהנורא שיתגלה מל' דא\"ס להיות בבחי' מלך על עם בלי לבוש וצמצום כלל. וזהו בחי' מל' דמשיח שהוא ביר\"ע דמל' דא\"ס עצמו וז\"ש והריחו ביראת הוי' העליון דמדות שבכתר שלמעלה מח\"ס דמורח ודאין<sup data-n=\"7581\">428</sup> בחי' חוטמא דע\"י<sup data-n=\"7582\">429</sup> כו' ולא למראה עיניו<sup data-n=\"7583\">430</sup> בח\"ס שבא ע\"י צמצום כו').\n<b>וז\"ש</b> עד יעבור כו' שיעברו בנהר דעדן לבחי' העדן עצמו שלמעלה גם משם הוי' דלעילא שבפנימי' הכתר למעלה גם מבחי'<sup data-n=\"7584\">431</sup> מל' דא\"ס שא' תפול עליהם אימתה כו' שנק' נורא והיינו מ\"ש ויהי בישורון מלך<sup data-n=\"7585\">432</sup> מל' דמשיח בחי' מלך הקדוש כנ\"ל) וזהו שאחר שיעברו בנהר דעדן ברגל א' נשמחה בו ממש,",[["7572","419","<b>ביום ההוא. . ב\"פ י\"ה</b>: זכרי' יד, ט. ראה לקו\"ת להאריז\"ל שם. הנסמן במאמרי אדה\"א נ\"ך ע' קנב."],["7573","420","<b>כשם שבא לראות</b>: חגיגה ב, א."],["7574","421","<b>עיניך יונים</b>: שה\"ש א, טו. ד, א."],["7575","422","<b>הנה עין ה' אל יריאיו</b>: תהלים לג, יח."],["7576","423","<b>עינא פקיחא</b>: נסמן לעיל פ' שמות לט, ב."],["7577","424","<b>דתרין עיינין כלולים כא'</b>: ראה זהר (אד\"ר) נשא קל, א."],["7578","425","<b>בחכ'</b>: א: ח\"ס. ד: כתר."],["7579","426","ועיני ה' משוטטי' [אד: משוטטות]. ראה זכרי' ד, י. דהי\"ב טז, ט. מאמרי אדה\"א הנחות תקע\"ז ע' שלה. וש\"נ."],["7580","427","<b>ההרים תרקדו</b>: תהלים קיד, ו."],["7581","428","<b>דמורח ודאין</b>: סנהדרין צג, ב. ראה הנסמן במאמרי אדה\"א דברים ח\"א ע' יז. דרושי חתונה ח\"א ע' קלא (ובהנסמן שם ע' קכה). לקמן רכה, ג. פ' תצוה שכד, א."],["7582","429","<b>חוטמא דע\"י</b>: ראה שע\"ת קד, א ובהנסמן במ\"מ לשם."],["7583","430","<b>ולא למראה עיניו</b>: המשך הכתוב והריחו."],["7584","431","<b>למעלה גם מבחי'</b>: א: הרצון הפשוט שהוא בחי'. וראה גם להלן הערה 436. ד: בחי'."],["7585","432","<b>ויהי בישורן מלך</b>: ברכה לג, ה. ראה גם לקמן פ' תצוה שלב, א."]]],[2300540773,"דהנה ענין בקיעת הז' נחלים בנהר דעדן גם שמבחי' העלם דרצה\"ע עצמו נעשה גילוי כנ\"ל כ\"ז אינו רק בבחי' שלימות הבירורים דרפ\"ח כו' <sup data-n=\"7586\">433</sup>כנ\"ל בענין הקים על עול תו\"מ שיעלה לבחי' מל'<sup data-n=\"7587\">434</sup> דא\"ס והן ז' מדות דח\"ע דתו\"מ<sup data-n=\"7588\">435</sup> שבאו מן ההעלם לגילוי לשלימותן, אבל בעדן עצמו שהוא בחי' שעשועי' העצמיי' דא\"ס עצמו דעוה\"ב בשכר המצות בפו\"מ מצד עצם הרצון הפשוט שהוא שם הוי'<sup data-n=\"7589\">436</sup> העצמי ה\"ז למעלה מבחי' הבירורים לגמרי ונק' ברכת ה' כו' זהו שבא העלם דבחי' מהו\"ע ית' ממש כנ\"ל, וזהו שבא ע\"י שמחה העצמי' שבעצמו' א\"ס שע\"ז א' שם נשמחה בו ממש שאין שמחה ועונג דח\"ע דפנימיות התורה מגיע לשם כלל, ושמחה זו בו ממש מביאה לבחי' התגלות עצמותו ממש שלפני המקיף הכללי, והוא בחי' טה\"ע שלמעלה מקדושה<sup data-n=\"7590\">438</sup> כמו ביו\"כ שא' לפני הוי' תטהרו<sup data-n=\"7591\">439</sup> שהוא מעין העוה\"ב רק אפס קצהו מאיר בשעשועי'<sup data-n=\"7592\">437</sup> שבתורה, וע\"כ כאשר עברו בנהר ברגל שם שמחו בו ממש והוא העדן עצמו שע\"ז א' יקימנו ונחי' לפניו<sup data-n=\"7593\">440</sup> ממש בחיי עולם שיבולע המות לנצח<sup data-n=\"7594\">441</sup> כו' (משא\"כ בימוהמ\"ש נא' הנער בן ק' שנה ימות<sup data-n=\"7595\">442</sup> ויצטרכו לעבוד הארץ כמ\"ש ועמדו זרים<sup data-n=\"7596\">443</sup> כו').\n<b>וזה</b> הי' בחי' משה עבד הוי' העצמי' שהביא והמשיך לאור אמיתי' מהו\"ע ית' במעשה המצות מצד עצמן כנ\"ל, וע\"כ א[מר] תורה צוה לנו משה כו' ואח\"כ א' ויהי בישורון מלך שהוא משיח שנק' מלך הח' הד\"ר<sup data-n=\"7597\">444</sup> כו' מקור התיקון. וז\"ש בקי\"ס אשירה להוי' היינו להוי' העצמי' כי גאה גאה שהמשיך לבחי' מל' דא\"ס להיות בגילוי בהתנשאות מלך על עם כו' בלי צמצום כלל (משום דיר\"ע<sup data-n=\"7598\">445</sup> דנורא דמל' דא\"ס ג\"כ מילתא זוטרתי לגבי משה עבד הוי' כנ\"ל), וזהו יתרון מעלה שהי' בקי\"ס אע\"פ שהי' בבחי' מל' ה\"א אחרונה שהי' בזה בהעלם מבחי' הוי' העצמי' שהוא העוה\"ב שהוא שם אהי' הב' כנ\"ל דנתחב\"ס בסוף מעשה המצות מצד עצמ' דוקא<sup data-n=\"7599\">446</sup>, וזהו<sup data-n=\"7600\">447</sup> ויאמינו בהוי' ובמשה עבדו <span data-k=\"pg\">446</span> ּ דהכל א' כנ\"ל והוא העוה\"ב שבא בשכר המצות בפו\"מ דשכר מצוה מצוה<sup data-n=\"7601\">448</sup> עצמה מטעם הנ\"ל וע\"כ ע\"ז א' עד יעבור סתם ולא הזכיר שם הוי' כי זהו בחי' התגלות העצמ[י]ת דא\"ס ממש שאינו בא ע\"י ד' אותיות דיו\"ד וה\"א כו', רק עכשיו מלובש בכל מצוה משם הוי' דעצמו' ונק' מצות הוי' ולע\"ל א' ולא יכנף עוד כו' דמה שמוסתר עכשיו ואינו אלא בבחי'",[["7586","433","<b>כנ\"ל</b>: בתו\"ח כאן נכפלו עוד הפעם התיבות: כ\"ז. . כנ\"ל."],["7587","434","<b>שיעלה לבחי' מל'</b>: א: דמל'. ד: למעלה גם מבחי' מל' דא\"ק שיעלה לבחי' מל'."],["7588","435","<b>דתו\"מ</b>: א: דתיקון. ד: דתו'."],["7589","436","<b>הרצון הפשוט שהוא שם הוי'</b>: א: שבהוי'. וראה גם לעיל הערה 431."],["7590","438","<b>טה\"ע שלמעלה מקדושה</b>: ראה גם לעיל פ' בא קכג, ג ובהנסמן לשם."],["7591","439","<b>טה\"ע. . לפני הוי' תטהרו</b>: נסמן לעיל שם."],["7592","437","<b>שלפני. . בשעשועי'</b>: א: ליתא."],["7593","440","<b>יקימנו ונחי' לפניו</b>: הושע ו, ב."],["7594","441","<b>שיבולע המות לנצח</b>: ישעי' כה, ח."],["7595","442","<b>הנער בן ק' שנה ימות</b>: ישעי' סה, כ. ראה גם מאמרי אדה\"א ויקרא ח\"ב ע' תרפו."],["7596","443","<b>ועמדו זרים</b>: ישעי' סא, ה."],["7597","444","<b>משיח. . הד\"ר</b>: ראה גם לעיל פ' שמות מג, ד. לקמן קסא, א. מאמרי אדה\"א דברים ח\"ד ע' א'שפו. וש\"נ. קונטרסים ע' דש."],["7598","445","<b>דיר\"ע</b>: אד: דיראה."],["7599","446","<b>עצמ' דוקא</b>: א: עצמו. ג: עצמן דוקא. ד: עצמן."],["7600","447","<b>וזהו</b>: אד: וז\"ש."],["7601","448","<b>דשכר מצוה מצוה</b>: נסמן לעיל פ' שמות ז, ב."]]],[2300540784,"האמונה בהוי' זה למס\"נ על התורה<sup data-n=\"7602\">449</sup> בפו\"מ יתגלה בעוה\"ב כמ\"ש אשר אהי' כו' וד\"ל (אך מיד שבנהר יעברו ברגל למעלה מסוד הוי' שבפנימי' התורה דמשיח יגיעו לשמחה העצמי' במהו\"ע ית' ממש שהוא שמחה ש\"מ מצד עצמה כנ\"ל לפי שזהו עליי' דשעשועי' שבח\"ע העצמי' דתוה\"ק שנכלל ועולה בשעשועי' העצמיי' ממש (וכמובן באשרי תמימי כו' שכולל תו\"מ כא' ממש בכל א\"ב כמו בפקודיך<sup data-n=\"7603\">450</sup> כו' בדרך עדותיך ששתי<sup data-n=\"7604\">451</sup> כו' גל עיני<sup data-n=\"7605\">452</sup> כו' גרסה נפשי<sup data-n=\"7606\">453</sup> כו' טוב טעם<sup data-n=\"7607\">454</sup> כו' עד סוף הק'<sup data-n=\"7608\">455</sup> (מה אהבתי<sup data-n=\"7609\">456</sup> כו' נר לרגלי<sup data-n=\"7610\">457</sup> כו') שזהו עליי' המל' דדוד הוא משיח לע\"ל) תען לשוני<sup data-n=\"7611\">458</sup> כו' ותורתך שעשועי<sup data-n=\"7612\">459</sup> שעשועי' העצמי' ממש וד\"ל (וכמ\"ש בס' הבהיר דדוד הי' מחבר<sup data-n=\"7613\">460</sup> תורה שלמעלה בהקב\"ה כו').\n<b>וזהו</b> הפך ים ליבשה בנהר יעברו כו' שכולל עבר דקי\"ס עם עתיד דיעברו בנהר פרת בימי משיח כא' ואז א[מר] שם נשמחה בו דייקא דמשמע דאם לא קי\"ס שעבר אע\"פ שבנהר יעברו כו' לא הי' גילוי השמחה העצמי' בו ממש לעוה\"ב, והענין הוא מובן ע\"פ כל הנ\"ל שיש יתרון מעלה בקי\"ס שהי' הכנה רק לקבלת התו\"מ בפו\"מ בגשמיות כנ\"ל הרבה יותר מעליות העולמות בימות המשיח בתשלום כל הבירורים דרפ\"ח מעה\"ד כו' שיהי' גילוי ההעלם דח\"ע הפנימי', לפי שסוף מעשה המצות בפו\"מ עבמח\"ת למעלה גם מבחי' פנימי' דח\"ע שלא יגיע שם בחי' ראי' והשגה בעין השכל כלל כי הוא בחי' התגלות העצמו' ממש דלמתב\"כ ואפי' אור צח דח\"ע אוכם הוא לגבי עה\"ע עצמו כנ\"ל שלזה א[מר] ויאמינו בהוי' זה העצמו' בבחי' האמונה לבד שלמעלה מן השכל והשגה דראי' דחכמה (והוא להיותו בעצמו' דא\"ס קודם שנמשך בבחי' מל' דא\"ס להיות מקיף כללי שנק' מחשבה אחת<sup data-n=\"7614\">461</sup> כו'), אך מה שהי' בכנ\"י בבחי' אמונה לבד שכולל כל המצות כמ\"ש העמידן על אחת<sup data-n=\"7615\">462</sup> כו' זה יהי' שכר המצות בעוה\"ב דהיום לעשותם [בפו\"מ] ולמחר לקבל שכרם<sup data-n=\"7616\">463</sup> שהוא העוה\"ב גילוי אור העצמות דא\"ס ממש, והוא ע\"י מעשה כל מצוה שיש בה שם הוי' למטה בד' אותיות צמצום והתפשטות לצמצם ולבטל הרצון מפני רצון ה' בסו\"מ והתפשטות בקיום גילוי רצה\"ע בוע\"ט כנ\"ל, הרי באתעדל\"ת עושי' אתעדל\"ע<sup data-n=\"7617\">464</sup>",[["7602","449","<b>התורה</b>: א: ניתוסף: ומצות."],["7603","450","<b>בפקודיך</b>: תהלים קיט, טו."],["7604","451","<b>בדרך עדותיך ששתי</b>: שם שם, יד."],["7605","452","<b>גל עיני</b>: תהלים שם, יח."],["7606","453","<b>גרסה נפשי</b>: א: ליתא. שם קיט, כ."],["7607","454","<b>טוב טעם</b>: שם שם, סו."],["7608","455","<b>הק'</b>: א: ליתא. ד: הקיפיטיל."],["7609","456","<b>מה אהבתי</b>: שם שם, צז."],["7610","457","<b>נר לרגלי</b>: תהלים קיט, קה."],["7611","458","<b>תען לשוני</b>: תהלים שם, קעב."],["7612","459","<b>ותורתך שעשועי</b>: שם שם, קעד."],["7613","460","<b>דדוד הי' מחבר</b>: נסמן לעיל פ' וארא פ, א."],["7614","461","<b>מל' דא\"ס. . מחשבה אחת</b>: ראה גם מאמרי אדה\"א דברים ח\"ג ע' תתקלט ואילך."],["7615","462","<b>העמידן על אחת</b>: מכות כד, א. ראה שה\"א ד, א. יא, א."],["7616","463","<b>דהיום לעשותם. . שכרם</b>: נסמן לעיל פ' שמות ו, ד."],["7617","464","<b>באתעדל\"ת עושי' אתעדל\"ע</b>: נסמן לעיל מא, א."]]],[2300540795,"מעצמות א\"ס ב\"ה לעשות לשם הוי' בהעלם דרצה\"ע להיות נמשך ביו\"ד וה\"א כנ\"ל לצמצם א\"ע כנקודה די' כו' ואח\"כ התפשטו' רצה\"ע בבחי' ה\"א כו', אך שם הוי' זה נק' ארחות הוי'<sup data-n=\"7618\">465</sup> למעלה עדיין בהעלם ברצה\"ע וז\"ש לעשותם לעשות לשם הוי' העליון, אבל למחר בעוה\"ב לקבל שכרם שיהי' גילוי שם הוי' העצמו' דא\"ס ברצה\"ע הזה עצמו למטה ממש כמו שהוא למעלה ממש במהו\"ע בלי לבוש וצמצום כלל וכלל (ואע\"פ שגם בבחי' מקיף הכללי שוה מעלה ומטה ה\"ז רק מקיף לאבי\"ע אבל בחי' עצמו' דא\"ס ממש נק' יש האמיתי דיש הגשמי<sup data-n=\"7619\">466</sup> כמו שהוא אינו נפרד כלל וכלל להיותו למעלה מבחי' אין של היש כמ\"ש במ\"א והוא העוה\"ב שיחי' גופי' גשמיי' מחיי החיים<sup data-n=\"7620\">467</sup> דא\"ס עצמו כמ\"ש ונחי' לפניו ממש וזהו עיקר יתרון המעלה על ימות המשיח <span data-k=\"pg\">רכג</span> ּ שהוא בבחי' אין דח\"ע (בחי' אדם פנימי<sup data-n=\"7621\">468</sup> כמו החכ' שבראש שהוא מקור הרוחניות דחיות האברים וכוללם יחד וזהו כמו ת\"ת שכנגד כולם<sup data-n=\"7622\">469</sup> וכמ\"ש בו ישכיל עבדי במקור החכ' שבראש דא\"ק וכמ\"ש ורוח אלקים כו' רוחו של משיח שקדם לעולם), וכנשמת אדה\"ר דכתי' ויפח באפיו נ\"ח<sup data-n=\"7623\">470</sup> נשמה כללי' נשמת כ\"ח<sup data-n=\"7624\">471</sup> כו' וע\"ז א' קורא הדורות מראש<sup data-n=\"7625\">472</sup> דא\"ק, אבל בחי' חיצוני' דאדם<sup data-n=\"7626\">473</sup> ברמ\"ח אברי'<sup data-n=\"7627\">474</sup> חיצוני' שהן רמ\"ח פקודי' בפו\"מ יש בהן יתרון מעלה מאדם פנימי דחכ' אדם, ששרשו במקיף דיחידה מ\"ם דצלם<sup data-n=\"7628\">475</sup> בבחי' גלגלתא דחפיא על מו\"ס<sup data-n=\"7629\">476</sup> כו' שיש בהן בחי' ההתכללו' ממש מראש לסוף שלמעלה מהתכללות דחכ' ומדות דפנימי' אדם, וע\"ז א' אף דעשיתיו<sup data-n=\"7630\">477</sup> בגוף בצלם דמות תבניתו שנק' אדם אדמה לעליון<sup data-n=\"7631\">478</sup> ממש והוא בחי' עצמו' א\"ס שלפני החכ' ומדות דתוה\"ק<sup data-n=\"7632\">479</sup> וזהו בחי' משה שנק' עבד הוי' דעצמו' שהוא שם העצם כנ\"ל שד[ו]מה ליש האמיתי עצמו וע\"כ הי' עניו מכל אדם כו' לפי שכל בחי' אדם דתו\"מ<sup data-n=\"7633\">480</sup> כלולים בו, וזהו ענין המצות בפו\"מ בציור אברים חיצונים ונק' אדם חיצוני שמאיר בזה ממהו\"ע א\"ס שנק' יש האמיתי כו' וז\"ש מ\"ה שמ\"ו<sup data-n=\"7634\">481</sup> וד\"ל, וז\"ש במשה מה שמו הוי' העצמי' כו'<sup data-n=\"7635\">482</sup> שלמעלה מבחי' בן דמשיח שאינו אלא כתולדה דבן ממוח האב שיוליד בדומה לו כנשמת אדה\"ר דפרחא מחי העולמים<sup data-n=\"7636\">483</sup> כו', וע\"כ א' ולא קם נביא כמשה<sup data-n=\"7637\">484</sup> אשר ידעו ה' פא\"פ כו' וכאשר ידבר איש אל רעהו<sup data-n=\"7638\">485</sup> בלי ביטול כלל וד\"ל).",[["7618","465","<b>ארחות הוי'</b>: תהלים כה, י."],["7619","466","<b>יש האמיתי דיש הגשמי</b>: ראה גם לעיל פ' שמות כג, ב. לקמן קפז, א. קצה, א. ג. רלח, א. רלט, רע\"ב. פ' תצוה שכה, א. ויקהל תכא, ב. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300670586\" data-slug=\"torat-chaim\" data-id=\"2300670586\">תו\"ח נח עו, סע\"א</a>. מאמרי אדה\"א שמות ח\"ב ס\"ע תקמ ואילך. הנסמן לעיל קלח, ד הערה 335."],["7620","467","<b>מחיי החיים</b>: ראה יומא עא, א."],["7621","468","<b>אדם פנימי</b>: ראה גם שע\"ת ח, ד. מב, סע\"א."],["7622","469","<b>ת\"ת שכנגד כולם</b>: פאה רפ\"א. ראה גם לקמן פ' תצוה שלו, א."],["7623","470","<b>ויפח באפיו נ\"ח</b>: בראשית ב, ז. ראה לעיל יז, א הערה 705."],["7624","471","<b>נשמת כ\"ח </b>[אגד: כל חי]: נוסח התפלה דשויו\"ט. ראה גם מאמרי אדה\"ז על ענינים ע' יב. שעה\"י קכב, ב ובהערה 22."],["7625","472","<b>קורא הדורות מראש</b>: ישעי' מא, ד. ראה הנסמן במאמרי אדה\"א דברים ח\"ג ע' תתיא. ע' תתפח. קונטרסים ע' תלב."],["7626","473","<b>חיצוני' דאדם</b>: נסמן לעיל בהערה 468."],["7627","474","<b>דאדם ברמ\"ח אברי'</b>: אהלות פ\"א, מ\"ח."],["7628","475","<b>מ\"ם דצלם</b>: ראה מאמרי אדה\"א דברים ח\"ב ע' תצט ואילך."],["7629","476","<b>גלגלתא דחפיא על מו\"ס</b>: ראה זהר (אד\"ר) נשא קכח, ב."],["7630","477","<b>אף דעשיתיו </b>[אד: עשיתיו]: ישעי' מג, ז."],["7631","478","<b>אדם אדמה לעליון</b>: נסמן לעיל מו, ב."],["7632","479","<b>דתוה\"ק</b>: אד: דתורה הקדומה."],["7633","480","<b>דתו\"מ</b>: אד: דחכמה ומדות."],["7634","481","<b>מ\"ה שמ\"ו</b>: שמות ג, יג."],["7635","482","<b>וד\"ל. . כו'</b>: א: מה. ד: מ\"ה הוי\"ה העצמי שאמר משה וד\"ל."],["7636","483","<b>כנשמת. . מחי העולמים</b>: ראה זהר תרומה קלח, א. לעיל פ' שמות מ, ב. תו\"ח לך לה, ג."],["7637","484","<b>ולא קם נביא כמשה</b>: ברכה לד, י [ושם: עוד בישראל כמשה]."],["7638","485","<b>וכאשר </b>[א: כאשר — וכ\"ה לעיל קנז, א]<b> ידבר איש אל רעהו</b>: תשא לג, יא. ראה גם לקמן קצד, רע\"ד. מאמרי אדה\"א נ\"ך ס\"ע תעח. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300670349\" data-slug=\"torat-chaim\" data-id=\"2300670349\">תו\"ח נח נא, ד</a> ובהערה 43."]]],[2300540805,"<b>וזהו</b> שקדם תחלה להפך ים ליבשה כו' שבקי\"ס הי' מעין העוה\"ב ששם נשמחה בו ממש כמו בשמחה ש\"מ שנא' כי נר מצוה בבחי' חיצוני' שלמעלה מתורה אור דפנימי' ח\"ע, וכן א' באורך ממש נראה אור<sup data-n=\"7639\">486</sup> בעוה\"ב למעלה ממקור חיים דקו\"ח דמל' דא\"ס דמשיח שע\"ז א' יחיינו מיומים<sup data-n=\"7640\">487</sup> דאור תוה\"ק שהיתה שעשועי' יום יום כו', אבל בעוה\"ב נחיה לפניו ממש בשעשועי' העצמיי' (וכמו שא' ע\"פ נכון כסאך מאז<sup data-n=\"7641\">488</sup> משל לאגוסטוס יושב<sup data-n=\"7642\">489</sup> ומלך עומד והוא מל' דא\"ס שבמשיח שיהי' עומד לגבי מלך מלכי המלכים<sup data-n=\"7643\">490</sup> בעוה\"ב והוא שנגלה עליהם במצרים בכבודו ובעצמו<sup data-n=\"7644\">491</sup> וגם על מלכי המלכים שהן בנ\"י שנק' בני מלכים<sup data-n=\"7645\">492</sup> ומלכי המלכים הוא בחי' האור פנימי' דח\"ע דתורה שא' בי מלכים ימלוכו<sup data-n=\"7646\">493</sup> דמאן מלכי רבנן<sup data-n=\"7647\">494</sup> כו' (וכמ\"ש בזהר אורייתא קדישא<sup data-n=\"7648\">495</sup> וישראל קדישי' אבל אין קדוש כה'<sup data-n=\"7649\">496</sup> כו' אע\"ג דאורייתא מתקשראה<sup data-n=\"7650\">497</sup> כו', והוא טהרה (גימ' ריח כמ\"ש והריחו) דימות המשיח בבחי' הבירורי' בשלימות שמביאה לקדושה<sup data-n=\"7651\">498</sup> העצמות ממש דעוה\"ב שלמעלה מבחי' הבירורי' לגמרי שלא ע\"י עבודה ותיקון דחכ' כלל (וכמשה שלא אכל לחם דתורה<sup data-n=\"7652\">499</sup> וגם לא לחם פנג<sup data-n=\"7653\">500</sup> כו') כמ\"ש בחריש ובקציר תשבות<sup data-n=\"7654\">501</sup> והוא ביום שכולו שבת שנק' מנוחה לחה\"ע<sup data-n=\"7655\">502</sup> בעוה\"ב (וז\"ש בשירת הים אשירה להוי' העצמו' דעוה\"ב כי גאה גאה על מל' דמשיח דמ\"ש וע\"י יתיב<sup data-n=\"7656\">503</sup> כו' זהו בחי' אדם פנימי דמשיח שנק' זקן שקנה חכמה<sup data-n=\"7657\">504</sup> ממקורה הראשון בתורה [הקדומה] שקדמה לעולם<sup data-n=\"7658\">505</sup> כמ\"ש ונחה עליו רוח חו\"ב<sup data-n=\"7659\">506</sup> כו' שז\"ס ורוח אלקי' כו' דתורה ותשובה ושמו של משיח<sup data-n=\"7660\">507</sup> קדמו לעולם כו', אבל בקי\"ס שהפך ים הקדמוני דתורה<sup data-n=\"7661\">508</sup> ליבשה זהו בחי' העוה\"ב ממש וד\"ל, ובמ\"ת הי' מעין העוה\"ב כמ\"ש ביום חתונתו<sup data-n=\"7662\">509</sup> וביום שמחת לבו <span data-k=\"pg\">448</span> ּ לעוה\"ב דהכל א' מטעם הנ\"ל שקיבלו המצות בא[מרם] נעשה בפו\"מ בציור אדם חיצוני והיו בציור קומת אדם בחיצוני' בי\"ב שבטים שכלולים כא' שהוא דומה לעליון ממש בבחי' שם הוי' העצמו' שלא נודע לאבות שגם שהן המרכבה<sup data-n=\"7663\">510</sup> ברוחניות דח\"ע דתורה כמ\"ש במ\"א עמ\"ש שוב למען עבדיך שבטי<sup data-n=\"7664\">511</sup> כו', וזהו שבקע הים לי\"ב גזרים שכלולים בבקיעה א' (שלמעלה מהבקיעה דנהר לז' נחלים כנ\"ל) והוא הטעם שבעוה\"ב יתגלה שם הוי' שבמצות למטה כמו",[["7639","486","<b>באורך. . נראה אור</b>: תהלים לו, י."],["7640","487","<b>יחיינו מיומים</b>: הושע ו, ב."],["7641","488","<b>נכון כסאך מאז</b>: תהלים צג, ב."],["7642","489","<b>משל לאגוסטוס יושב</b>: נסמן לעיל פ' בא ק, ג."],["7643","490","<b>מל' דא\"ס. . מלך מלכי המלכים</b>: נסמן שם."],["7644","491","<b>שנגלה עליהם. . בכבודו ובעצמו</b>: נסמן לעיל פ' בא קכב, א."],["7645","492","<b>בנ\"י שנק' בני מלכים</b>: שבת סז, א."],["7646","493","<b>בי מלכים ימלוכו</b>: משלי ח, טו."],["7647","494","<b>דמאן מלכי רבנן</b>: ראה גיטין סב, א. הנסמן במאמרי אדה\"א שמות ח\"ב ע' תקלח. שע\"ת קו, ג. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300680278\" data-slug=\"torat-chaim\" data-id=\"2300680278\">תו\"ח וישב רב, ב</a>. לקמן פ' משפטים רצא, ג."],["7648","495","<b>אורייתא קדישא</b>: ראה זהר תזריע מד, א. מאמרי אדה\"א ויקרא ח\"א ע' שסד. וש\"נ. שה\"א עז, א. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300670216\" data-slug=\"torat-chaim\" data-id=\"2300670216\">תו\"ח בראשית לג, א</a> ובהערה 2. לקמן פ' תצוה שעג, ב."],["7649","496","<b>אין קדוש כה'</b>: שמואל-א ב, ב."],["7650","497","<b>דאורייתא מתקשראה</b>: ראה זהר אחרי עג, א."],["7651","498","<b>טהרה. . שמביאה לקדושה </b>[א: לידי קדושה]: נסמן לעיל ז, א."],["7652","499","<b>וכמשה שלא אכל לחם דתורה</b>: ראה מאמרי אדה\"ז תקס\"ח ח\"א ע' סט וס\"ע פא ואילך. מאמרי אדה\"א במדבר ח\"ב ע' תשסד."],["7653","500","<b>לחם פנג</b>: נסמן לעיל כג, ב."],["7654","501","<b>בחריש ובקציר תשבות</b>: תשא לד, כא. ראה מאמרי אדה\"א ויקרא ח\"ב ע' תשטז. וש\"נ. לקמן רלה, א. פ' משפטים רצב, ד. ויקהל תכח, ב. תלט, ב."],["7655","502","<b>יום שכולו שבת. . לחה\"ע</b>: תמיד בסופה."],["7656","503","<b>וע\"י יתיב</b>: דניאל ז, ט."],["7657","504","<b>שנק' </b>[אד: ליתא]<b> זקן שקנה חכמה</b>: נסמן לעיל לא, ד."],["7658","505","<b>בתורה. . שקדמה לעולם</b>: פסחים נד, א."],["7659","506","<b>ונחה עליו רוח חו\"ב</b>: ישעי' יא, ב [בדילוג]."],["7660","507","<b>דתורה ותשובה ושמו של משיח</b>: פסחים שם."],["7661","508","<b>ים הקדמוני דתורה</b>: נסמן לעיל פ' שמות לו, א."],["7662","509","<b>ביום חתונתו</b>: שה\"ש ג, יא."],["7663","510","<b>לאבות. . שהן המרכבה</b>: נסמן לעיל ה, ג."],["7664","511","<b>שוב למען עבדיך שבטי</b>: ישעי' סג, יז. ראה גם מאמרי אדה\"א במדבר ח\"א ע' ע. דברים ח\"א ע' של."]]],[2300540814,"למעלה ממש במהו\"ע כנ\"ל כמ\"ש להנחיל אוהבי יש האמיתי כו', משא\"כ בימות המשיח שיראו בראי' והשגה כמו שהוא ברוחניות למעלה בהעלם דמקיף הכללי כו' ובעוה\"ב יתגלה למטה בגשמיות ביש גמור בלי הסתר מצד הגוף כלל, וז\"ש שם נשמחה בו ממש משום דהפך ים כו' ויש בכלל מאתים מנה וממילא בנהר יעברו כו' וע\"כ מזכירים יצ\"מ לימות המשיח דוקא כמ\"ש כל ימי כו' וד\"ל) ואתפשטותי' דמשה בכל דרא<sup data-n=\"7665\">512</sup> בבחי' עבד הוי' דעצמות ובחי' משיח בחי' בן שנק' בני מלכים וזהו שרמז ריב\"ז אני כשר<sup data-n=\"7666\">513</sup> לפני המלך ורחב\"ד כעבד כו' ובכלל נק' כנ\"י בן ועבד שלמעלה מבן<sup data-n=\"7667\">514</sup> כו').\n<b>והנה</b> אחר כל הנ\"ל בענין ימות המשיח ועוה\"ב, יש להבין מארז\"ל דיפה שעה אחת<sup data-n=\"7668\">515</sup> בתשו' ומע\"ט בעוה\"ז מכל חיי העוה\"ב שזהו פלא גדול מאחר שכל עיקר שכר המצות הוא העוה\"ב שזהו שם אהיה הב' כנ\"ל, א\"כ איך מעשה המצות בעוה\"ז גבוה יותר מחיי העוה\"ב עד שיפה שעה אחת כו', וכן בענין התשובה שבעוה\"ז בבירור הרע דק\"נ שמזה יהי' גאולה דמשיח כמא' אם עושי' תשו' נגאלי'<sup data-n=\"7669\">516</sup> (שהוא שלימות הבירור שהוא ע\"י שם מ\"ה דח\"ע כנ\"ל) איך תשובה מן הרע בפו\"מ שעה א' גבוה יותר כו'. אך הנה יש להקדים תחלה מה שא' דביו\"ד נברא העוה\"ב<sup data-n=\"7670\">517</sup> והעוה\"ב עצמו הוא בחי' הה\"א שהוא ההתפשטות לאורך ורוחב והיו\"ד הוא בחי' הצמצום שמצמצם א\"ע להיות בחי' התפשטות ההשגה לנשמו' הצדיקים כו' כמו כל שפע מן המשפיע אל המקבל שצ\"ל ע\"י ד' אותיות אלו יו\"ד ה\"א כו' כנ\"ל, ואין זה מובן דהלא מבואר למעלה בשרש העוה\"ב שהוא בחי' התגלות אור העצמות דא\"ס ממש כמו שהוא כמ\"ש להנחיל אוהבי יש י\"ש האמיתי מקורא דכולא כו' שזהו למעלה משם הוי' בד' אותיות צמצום והתפשטות כו' אלא שם אהיה אנא [זמין] כו' כנ\"ל ואיך א' דביו\"ד נברא העוה\"ב כו'. אך הנה הענין הוא דבאמת עיקר ענין העוה\"ב הוא מה שהנשמות נהנין מעונג האלקי העליון במורגש ממש דהיינו בהשגה ותפיסא לאורך ורוחב גדול כמו שנשמות [נהנין] עתה בג\"ע דבריאה שנא' ויברא ה' גן בעדן מקדם<sup data-n=\"7671\">518</sup> מקדמונו ש\"ע<sup data-n=\"7672\">519</sup> שנמשך מעונג ושעשועי' העצמיי' דא\"ס שקדם לעולם הנאצל",[["7665","512","<b>ואתפשטותי' </b>[ד: (ואמר אתפשטותי']<b> דמשה בכל דרא</b>: נסמן לעיל פ' וארא פ, ג."],["7666","513","<b>ריב\"ז אני כשר</b>: ברכות לד, ב."],["7667","514","<b>ועבד שלמעלה מבן</b>: ראה <a class=\"ft-cite\" href=\"#/read/tanya/3401310046\" data-slug=\"tanya\" data-id=\"3401310046\">תניא פמ\"א</a>. מאמרי אדה\"א בראשית ע' שס."],["7668","515","<b>דיפה שעה אחת</b>: נסמן לעיל פ' שמות ט, א."],["7669","516","<b>אם עושי' תשו' נגאלי'</b>: נסמן לעיל פ' שמות לז, א."],["7670","517","<b>דביו\"ד נברא העוה\"ב</b>: מנחות כט, ב. לקמן פ' פקודי תמג, ב."],["7671","518","<b>ויברא ה' </b>[א: ליתא]<b> גן בעדן מקדם</b>: בראשית ב, ח [ושם: ויטע ה\"א — ראה לקמן פ' ויקהל תט, א. מאמרי אדה\"א קונטרסים ע' שיב. וש\"נ. הנחות תקע\"ז ע' שמא]."],["7672","519","<b>מקדם מקדמונו ש\"ע</b>: נסמן לעיל פ' שמות לה, א."]]],[2300540823,"כו', והוא העדן שישיגו בו הנשמות בעוה\"ב בעולם הבריאה שז\"ש ביו\"ד נברא העוה\"ב [שגם העוה\"ב הוא בא בדרך בריאה כמ\"ש כי בי\"ה ה' צור עולמים ביו\"ד נברא העוה\"ב] ובה\"א נברא העוה\"ז וכל התהוות בריאה הוא מאין ליש בד' אותיות דיו\"ד וה\"א כו', וכך הוא גם בעונג העליון שנמשך מעצמות המאציל לאצי' נמשך ע\"י יו\"ד שהוא הצמצום בעצמו ואח\"כ ההתפשטות דה\"א כו' וכללות ד' אותיות דהוי' באבי\"ע<sup data-n=\"7673\">520</sup> יו\"ד בחכ' דאצי' ה\"א בבריאה וי\"ו ביצי' ה\"א בעשי' כו', וזהו שם הוי' <span data-k=\"pg\">רכד</span> ּ שבעצמו' א\"ס ממש שנק' שמי הוי' העצמ[י]' כנ\"ל שלא נודע גם לאבות ולא בג\"ע דאצי' ובריאה כו' הרי הוא למעלה גם משם הוי' שבתענוג ורצה\"ע הנעלם שבא בגילוי מאין ליש באבי\"ע כנ\"ל, ועכ\"ז הרי גם בו יש ד' אותיות דשם הוי' רק שנק' שמי הוי' העצמי והוא יו\"ד ואח\"כ ה\"א כו' שבעצמו' השעשועי' שנמשך בתו\"מ בפו\"מ דוקא והוא בחי' מקור כל חיי העוה\"ב שנמשך באבי\"ע כמ\"ש כי עמך מקור חיים מקור כל חיי העוה\"ב כו', אבל מ\"מ יפה שעה אחת בתשובה ומע\"ט בעוה\"ז דוקא יותר מכל חיי העוה\"ב שנמשך ממקור כל החיים דעצמות השעשועים דא\"ס כנ\"ל. והטעם הוא לפי שבעוה\"ז נעשה המצוה בפו\"מ בביטול הרצון שהוא היו\"ד וגילוי רצה\"ע בכלי הגשמי בה\"א כו' שמזה דוקא נעשה אותיות דשם הוי' שבעצמו' שלמעלה גם משם הוי' שבהעלם וגילוי הנ\"ל, א\"כ הרי יש כח ושרש לתשובה ומע\"ט בעוה\"ז שעושים לשם הוי' העצמי בעצמות א\"ס ממש שלמעלה גם משם הוי' זה דעצמו', כי השם הזה אינו אלא שמורה על העצם כו' כנ\"ל. וז\"ש כי עמך מקור חיים דעוה\"ב באורך ממש נראה אור ע\"י המצות בפו\"מ למעלה מכל חיי העוה\"ב שנברא ונאצל מיו\"ד דשם הוי' העצמ[י]' כו' כי התשובה בסו\"מ והמצות בוע\"ט זהו שנתאוה להיות לו ממש דירה בתחתונים<sup data-n=\"7674\">522</sup> עד שעי\"ז נמשך בד' אותיות דהוי' בעצמות התענוג כו' (ובמ\"א מבואר<sup data-n=\"7675\">523</sup> הטעם לפי שהעוה\"ב הוא בבחי' ממכ\"ע בבחי' אורות בכלים והוא בבחי' שם הוי' בצמצום והתפשטו' כו', אבל שרש העוה\"ז הוא בבחי' מקיף בחי' סוכ\"ע הכללי כו' וד\"ל), וע\"כ יש ביכולת מעשה המצוה בעוה\"ז דוקא לעשות לשם הוי' בעצמו' להיות ב' הויות בהעלם וגילוי כנ\"ל וע\"כ התשובה אינו אלא בעוה\"ז ולא יועיל בעוה\"ב וגם המצות בפו\"מ אינו רק בעוה\"ז כמו שא' היום לעשותם וכמא' חפשי בלא מצות<sup data-n=\"7676\">524</sup> כו'. וז\"ש בתשובה ומע\"ט בעוה\"ז דוקא תשובה סומ\"ר שהוא בלאו די\"ה שקודם להן דו\"ה כו' וע\"ט במע\"ט הנגלות לנו דוקא יותר מכל חיי העוה\"ב מפני שהוא למעלה מבחי' השעשועי' הנמשך לנשמות בעוה\"ב וד\"ל,",[["7673","520","<b>ד' אותיות דהוי' באבי\"ע</b>: נסמן לעיל פ' שמות כד, ד הערה 62."],["7674","522","<b>שנתאוה. . דירה בתחתונים</b>: נסמן לעיל פ' וארא ע, ג."],["7675","523","<b>ובמ\"א מבואר</b>: ראה גם לעיל פ' וארא נב, א. נח, ב. סידור שחרית לב, ד."],["7676","524","<b>חפשי בלא מצות</b>: ראה שבת קנא, ב. הנסמן לעיל ז, א הערה 305."]]],[2300540832,"ומבואר למעלה שיש ב' מדרגות ימות המשיח והעוה\"ב, ולנגד זה א' ב' דברים תשו' ומע\"ט<sup data-n=\"7677\">525</sup> בעוה\"ז שהתשו' הוא ענין הבירור דרע בביטול רצון שבזה יש יתרון האור מן החשך דתהו בחי' ס\"ג שלמעלה משם מ\"ה דתיקון וע\"כ נעשה מזה י\"ה דל\"ת שקודם לו\"ה דמ\"ע (ולכך אמר ר[בי] יש קונה עולמו<sup data-n=\"7678\">526</sup> בשעה א[חת] בתשו' דראב\"ד שנכלל בזה ו\"ה דמ\"ע כו'), ואמנם כ\"ז בשם הוי' דכתר שהוא העלם הרצון כנ\"ל והוא שם אהי' הא' כנ\"ל ולמעלה מזו הוא שם הוי' העצמ[י]' הנ\"ל שיתגלה בעוה\"ב ממעשה המצות עצמן וז\"ש ומע\"ט שגם מע\"ט בעוה\"ז יפה יותר משכר המצות בעוה\"ב וד\"ל. ומה שהקדים תשובה למע\"ט<sup data-n=\"7679\">527</sup> משמע שא\"א להיות גילוי אור העצמי' ממע\"ט גם בעוה\"ב בלי הקדמת התשובה מקודם וכתשובה שנגאלים תחלה בימות המשיח ואח\"כ יגיעו למדרגת העוה\"ב וכן בענין יפה שעה אחת בעוה\"ז היינו בתשו' ומע\"ט דוקא, והענין הוא דגם במצות מעשיות צריך שיהי' ע\"י תשובה מקודם דוקא (כמו התשובה בעי\"ת שאז יוכ\"פ מכפר שיו\"כ הוא מעין העוה\"ב שאינו אלא אחר התשובה<sup data-n=\"7680\">528</sup> כו'). והטעם הוא כי ע\"י התשובה נעשה בחי' הצמצום דיו\"ד <span data-k=\"pg\">450</span> ּ למעלה להיות שבא מן המיצר ושפלות בחי' עמ\"ת<sup data-n=\"7681\">529</sup> כמ\"ש מן המיצר<sup data-n=\"7682\">530</sup> קראתי י\"ה אז ענני במרחב י\"ה במצות והוא מה שמבטל רצונו מפני רצון ה' כנ\"ל, וע\"כ במקום שבע\"ת עומדים<sup data-n=\"7683\">531</sup> צ\"ג א\"י לעמוד לפי שצ\"ג עיקר ענין עבודתם הוא במצות שהוא בחי' התפשטו' דה\"א בגילוי רצון הנעלם כו' וא\"א להיות כ\"א ע\"י צמצ[ו]ם דיו\"ד תחלה שהוא התשובה מקודם, ואע\"פ שצ\"ל שמחה ש\"מ מצד עצם הרצון והתענוג העצמ[י]' כו' כנ\"ל, אבל גם זה א\"א אם לא ע\"י צמצום די[ו\"ד] דשפלות ומיצר דתשובה שמטעם זה א[מר] דמלכא משיחא אתא לאתבא צדיקייא בתיובתא<sup data-n=\"7684\">532</sup> לצדיקיי' במצות דוקא צ\"ל תשובה, וז\"ש תשובה ומע\"ט יחד שמזה דוקא יוכל להיות העוה\"ב דטהרה מביאה לידי קדושה העצמי' בגילוי והתפשטו' בעוה\"ב כו' (וגם משה עבד הוי' העצמ[י]' כנ\"ל לא זכה לתשובה<sup data-n=\"7685\">533</sup> רק קודם מותו כו' כדי שיוכל להיות גילוי שם הוי' שבעצמו' עי\"ז וע\"כ א[מר] שלח נא כו', שבזה<sup data-n=\"7686\">534</sup> יתרון מעלה למשיח שמחמת התשובה יבוא העוה\"ב וד\"ל. וזהו יחיינו מיומים בימות המשיח בגילוי סוד הוי' שבפנימי' התורה מהעלם הרצה\"ע כנ\"ל ע\"י התשובה מן המיצר דוקא כמ\"ש העם ההולכים בחשך ראו אור גדול<sup data-n=\"7687\">535</sup> כשנהפך החשך העליון לאור גדול כו' ע\"י תשובה האמיתי' ואח\"כ יקימנו בתח\"ה ונחי' לפניו בעוה\"ב דתח\"ה הוא בסוף ימות המשיח<sup data-n=\"7688\">536</sup> קודם העוה\"ב שיחיו חיי עולם כו', וכמ\"ש והשביע בצחצחות נפשך<sup data-n=\"7689\">537</sup> באור צח ומצוחצח דמשיח ואח\"כ",[["7677","525","<b>ב' דברים תשו' ומע\"ט</b>: ראה גם <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300680296\" data-slug=\"torat-chaim\" data-id=\"2300680296\">תו\"ח תולדות קנג, ד</a> ובהערה 72. מאמרי אדה\"א הנחות תקע\"ז ע' צז. לקמן קצב, ג."],["7678","526","<b>יש קונה עולמו</b>: ע\"ז יז, א."],["7679","527","<b>שהקדים תשובה למע\"ט</b>: ראה גם לעיל פ' וארא סו, א ובהערה 299."],["7680","528","<b>יוכ\"פ מכפר. . אחר התשובה</b>: ראה גם מאמרי אדה\"א דברים ח\"ב ע' תקכג. וש\"נ."],["7681","529","<b>עמ\"ת</b>: א: עומק תחת."],["7682","530","<b>מן המיצר</b>: תהלים קיח, ה."],["7683","531","<b>במקום שבע\"ת עומדים</b>: נסמן לעיל פ' שמות מא, א הערה 175."],["7684","532","<b>דמלכא משיחא. . בתיובתא</b>: נסמן לעיל פ' שמות מא, ב."],["7685","533","<b>משה. . זכה לתשובה</b>: ראה לעיל פ' שמות לז, א. וש\"נ."],["7686","534","<b>שבזה</b>: א: ניתוסף: יש."],["7687","535","<b>העם. . ראו אור גדול</b>: ישעי' ט, א. ראה גם מאמרי אדה\"א שמות ח\"א ע' צג."],["7688","536","<b><a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300021242\" data-slug=\"likkutei-sichot\" data-id=\"1300021242\">דתח\"ה</a> הוא בסוף ימות המשיח</b>: ראה גם <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300061304\" data-slug=\"likkutei-sichot\" data-id=\"1300061304\">לקו\"ש</a> י\"ג שבט [כרך ב] ע' 518 ובהערה 11. יו\"ד שבט [כרך ו] ע' 294 ובהערה לשם."],["7689","537","<b>והשביע בצחצחות נפשך</b>: ישעי' נא, יח."]]],[2300540841,"עצמותיך יחליץ בתח\"ה כו' שיקימנו ונחי' לפניו ממש. ונמצא ג' מדרגות הן ימות המשיח ותח\"ה ועוה\"ב דאין בין העוה\"ז לימוהמ\"ש<sup data-n=\"7690\">538</sup> רק שעבוד מלכיות לבד, אבל תחה\"מ הוא העוה\"ב כמ\"ש יקימנו ונחי' מיד לפניו ממש חיי עולם וד\"ל).\n<b>ובזה</b> יובן מארז\"ל דמאן דלא כרע במודים<sup data-n=\"7691\">539</sup> אינו קם בתחה\"מ כו' וזה פלא לכאורה דמה שייכות יש לענין הכריעה במודים דוקא לענין הקמה בתח\"ה כו', אך הנה ידוע שיש ב' מדרגות הודאה וברכה, בחי' הברכה הוא בחי' ההמשכה<sup data-n=\"7692\">540</sup> וגילוי אור ושפע הבאה מלמעלה למטה מבחי' ההעלם לגילוי כמו ברוך אתה הוי'<sup data-n=\"7693\">541</sup> כו' ברכה זו היא שיהי' שם הוי' מתגלה ונמשך למטה דוקא כמו יהי שם הוי' מבורך<sup data-n=\"7694\">542</sup>, וכמו והמלך שלמה ברוך<sup data-n=\"7695\">543</sup> לשון נפעל כו' כמ\"ש במ\"א, והוא ענין הכריעות בח\"י ברכות דש\"ע<sup data-n=\"7696\">544</sup> כידוע. אך זה א\"א להיות כ\"א בבחי' העלאה באהבה ודביקות הנפש בקירוב אחר קירוב לדבקה בשם הוי' ע\"י בחי' השגה ותפיסא במוח בינה בהתפעלות העונג המורגש בהשגה האלקי' כו', ואז רוח אייתי רוח<sup data-n=\"7697\">545</sup> ואמשיך רוח דבאתעדל\"ת אתעדל\"ע שיהי' נמשך ומתברך שם הוי' מבחי' ההעלם לגילוי אור מלמעלה למטה דכל העלאה גורם ההמשכה, והעלאה זו אינו כ\"א ע\"י הדביקות והתקשרות הנשמה בשם הוי' כמו אליך הוי' נפשי אשא<sup data-n=\"7698\">546</sup> שהוא ע\"י ההשגה וראי' דחו\"ב בלב כידוע (ויש בזה ב' מדרגות ברכה ושפע בחיי שעה כמו בש\"ע וברכת הוי' העצמי' שבמצות לעוה\"ב כמשי\"ת). אבל בחי' ההודאה הוא בחי' ביטול במציאות לגמרי שלמעלה מן השכל וההשגה לפי שהוא בעצמו' אור א\"ס שא' בו למחת\"ב כלל שאין השגה מגיע לשם כלל (אפי' מח' הקדומה דחכ' הקדומה שיתגלה במשיח דכתי' בי' ישכיל עבדי כנ\"ל), רק שמודה בהודאה לבד שזהו רק בחי' הצמצום והביטול מכל עצמותו בחי' יו\"ד שלמעלה מה\"א דהשגה כנ\"ל שאז <span data-k=\"pg\">רכה</span> ּ דוקא יוכל להמשיך בחי' ההמשכה וברכה דבחי' ההתפשטות בהשגה ותפיסא בה\"א כמ\"ש מן המיצר קראתי י\"ה מן המיצר דוקא אז ענני במרחב והתפשטות די[ו\"ד] בה\"א שהיא בחי' ברכה כנ\"ל וד\"ל (וכך הוא ענין הברכה דמצות עכשיו שצ\"ל תחלה תשובה דוקא כנ\"ל בענין תשובה ומע\"ט כו', רק שענין הברכה דמצות הוא למעלה מגילוי דשם הוי' בעולמות לצורך שפע העולמות הרוחניי'",[["7690","538","<b>דאין בין העוה\"ז לימוהמ\"ש</b>: ראה ברכות לד, ב. וראה גם ד\"ה אוסרי לגפן תקס\"ד נדפס ב<a class=\"ft-cite\" href=\"#/read/torat-chaim/2300680037\" data-slug=\"torat-chaim\" data-id=\"2300680037\">תו\"ח ויחי רלו, א</a>. מאמרי אדה\"א ויקרא ח\"ב ע' תרפו. דברים ח\"א ע' קב. וש\"נ."],["7691","539","<b>דמאן דלא כרע במודים</b>: נסמן לעיל פ' וארא עד, א."],["7692","540","<b>הברכה הוא בחי' ההמשכה</b>: ראה גם סידור שער התפלה כג, א. שער החנוכה רפ, ג. ש\"א לב, א. שע\"ת כו, א. מאמרי אדה\"א הנחות תקע\"ז ע' רסב. וש\"נ. לקמן קסב, א. פ' תרומה שיז, ב."],["7693","541","<b>ברוך אתה הוי'</b>: נוסח ברכת המצות [תהלים קיט, יב. דהי\"א כט, י]."],["7694","542","<b>יהי שם הוי' מבורך</b>: תהלים קיג, ב."],["7695","543","<b>והמלך שלמה ברוך</b>: מלכים-א ב, מה. ראה ביאוה\"ז עקב קכ, א. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381244\" data-slug=\"likkutei-torah\" data-id=\"4001381244\">לקו\"ת שה\"ש כח, ד</a>. מאמרי אדה\"א ויקרא ח\"ב ע' תנח. הנחות תקע\"ז ע' רסב. ש\"א כ, א. צג, ב. לקמן ריח, א. פ' תרומה שיז, ג."],["7696","544","<b>הכריעות בח\"י ברכות דש\"ע</b>: ראה מאמרי אדה\"ז אתהלך לאזניא ס\"ע קלז. תקס\"ד ע' קעו. תקס\"ה ח\"א ע' קיח."],["7697","545","<b>רוח אייתי רוח</b>: נסמן לעיל סג, ג."],["7698","546","<b>אליך הוי' נפשי אשא</b>: תהלים כה, א."]]],[2300540850,"וגשמיי' כידוע בענין יב\"ק יחוד ברכה קדושה שבמצות, היחוד הוא יחוד זו\"נ קודב\"ה ושכינתי' מ\"ה וב\"ן<sup data-n=\"7699\">547</sup> להוסיף אורות ומוחי' חדשי' בכל האצי' בכלל שהוא ד' אותיות דשם הוי' בכללו', והברכה הוא בא[מרו] ברוך כו' אשר קדשנו במצותיו ה\"ז בחי' תוס' אור חדש מבחי' ההעלם דשם הוי' שבכתר דוקא כידוע בענין ק' ברכות שהן בי\"ס שבכתר<sup data-n=\"7700\">548</sup> וז\"ש איהו ברוך בעצם ואיהי ברכה<sup data-n=\"7701\">549</sup> ונק' ישראל ברוכי הוי'<sup data-n=\"7702\">550</sup> כו', וקדושה למעלה מן הברכה והוא מקדוש' העצמ[י]' שקדשנו במצותיו ממש (שזהו שם הוי' העצמי' שיתגלה בעוה\"ב ממעשה המצות בעוה\"ז כנ\"ל וד\"ל).\n<b>וזהו</b> שא' דמאן דלא כרע במודים אינו קם בתח\"ה כו', דהנה תח\"ה יהי' אחר ימות המשיח כמ\"ש ביום הג' יקימנו כו' ביום הג' שאחר שיחיינו מיומים בימות המשיח כנ\"ל, והענין הוא כידוע ההפרש בין ימות המשיח לתח\"ה דאע\"פ שגם בימוהמ\"ש יהי' שלימות הבירורי' דרפ\"ח כו' מעה\"ד וכמ\"ש ואת רוה\"ט אעביר מן הארץ<sup data-n=\"7703\">551</sup> וכתיב וגר זאב כו' לא ירעו כו' ומלאה הארץ דיעה את הוי'<sup data-n=\"7704\">552</sup> לבדו<sup data-n=\"7705\">553</sup> כו' כולם ידעו אותי כו', עכ\"ז יהיו הגופי' גשמיי' שנולדו מאו\"א ויצטרכו למזון גשמי רק שרוח האלקי ישכון בכל בשר וכמ\"ש וראו כ\"ב<sup data-n=\"7706\">554</sup> כו' (כמו שהי' קודם חטא עה\"ד בקין והבל וכה\"ג שנק' בני האלקי'<sup data-n=\"7707\">*555</sup> ממש כמ\"ש על קין קניתי איש את ה'<sup data-n=\"7708\">555</sup> (שעלו למטה ב' וירדו ד'<sup data-n=\"7709\">556</sup> כו') עד שא' לא ידון רוחי באדם<sup data-n=\"7710\">557</sup> כו' וע\"כ היו מאריכי' ימים רבים וכך יהי' בימוהמ\"ש כנ\"ל), וזהו רק גילוי שם הוי' שבהעלם אור פנימי' הכתר עד שיגלה כל סוד ה' לכל נפש ורוח כ\"ב כמ\"ש ואשפוך רוחי על כ\"ב גם בבהמות וחיות יהי' בחי' הביטול לאלקו' וכמ\"ש וארי' כבקר יאכל תבן (וכמו חמורו של רפב\"י<sup data-n=\"7711\">558</sup> ופרות שנשאו הארון<sup data-n=\"7712\">559</sup> כו') (והוא בחי' הזדככות וטהרת החומר בתכלית כמו גופו של אדה\"ר ויותר מזה והנשמה היא נשמת אדה\"ר במשיח<sup data-n=\"7713\">560</sup> שהוא רוח אלקי' דזהו אדם אדם דוד משיח<sup data-n=\"7714\">561</sup>, וז\"ש מה שמו א\"ק מה שם בנו משיח שזהו א' רבתי דאדם דד\"ה<sup data-n=\"7715\">562</sup> ). אך בחי' תחה\"מ למעלה הרבה מזה והוא מ\"ש ביום הג' יקימנו כו' כנ\"ל, והענין הוא כידוע בשרש תחה\"מ שיומשך מבחי' טהירו עילאה דהיינו למעלה גם מבחי' שם הוי' שבכתר מל' דא\"ס שיאיר במשיח כנ\"ל בוי\"ו דוהנורא כו', והוא מבחי' אור הא\"ס",[["7699","547","<b>זו\"נ. . מ\"ה וב\"ן</b>: ראה גם לעיל פ' בא צג, א."],["7700","548","<b>ק' ברכות שהן בי\"ס שבכתר</b>: ראה גם לעיל פ' שמות מח, ד. וש\"נ."],["7701","549","<b>איהו ברוך. . ואיהי ברכה</b>: נסמן לעיל קלד, ג."],["7702","550","<b>ונק' ישראל ברוכי הוי'</b>: ישעי' סה, כג. וראה גם לעיל שם."],["7703","551","<b>ואת רוה\"ט אעביר מן הארץ</b>: זכרי' יג, ב."],["7704","552","<b>ומלאה הארץ דיעה את הוי'</b>: ישעי' יא, ט [ושם: כי מלאה — ראה לקמן פ' יתרו רסב, ב. משפטים רעז, ג. רפב, ג. תצוה שכט, ג [ושם הוגה מגוכי\"ק]. שעח, ג. מאמרי אדה\"א ויקרא ח\"א ע' רסט. וש\"נ. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300670061\" data-slug=\"torat-chaim\" data-id=\"2300670061\">תו\"ח נח נט, ב</a> הערה 32. שה\"א ב, א הערה 8]."],["7705","553","<b>לבדו</b>: א: ליתא."],["7706","554","<b>וראו כ\"ב</b>: ישעי' מ, ה."],["7707","*555","<b>בקין והבל. . בני האלקי'</b>: ראה גם לקמן פ' ויקהל תא, ב."],["7708","555","<b>קניתי איש את ה'</b>: בראשית ד, א."],["7709","556","<b>שעלו למטה ב' וירדו ד'</b>: סנהדרין לח, ב."],["7710","557","<b>לא ידון רוחי באדם</b>: בראשית ו, ג. ראה גם לעיל קנד, א."],["7711","558","<b>חמורו של רפב\"י</b>: נסמן לקמן קצה, ד."],["7712","559","<b>ופרות שנשאו הארון</b>: נסמן לעיל פ' וארא עד, א הערה 106."],["7713","560","<b>נשמת אדה\"ר במשיח</b>: ראה גם לעיל יז, א. וש\"נ."],["7714","561","<b>אדם אדם דוד משיח</b>: נסמן לעיל מז, ב."],["7715","562","<b>א' רבתי דאדם דד\"ה </b>[ד ניתוסף: כמ\"ש במ\"א]: בתחלתו. מסורה גדולה פ' בראשית. ראה מאמרי אדה\"ז תקס\"ח ח\"ב ע' תרעב. מאמרי אדה\"א הנחות תקע\"ז ס\"ע ו ואילך."]]],[2300540859,"עצמו שע\"ז א' כי טל אורות טליך<sup data-n=\"7716\">563</sup> שהוא טל השמים העליוני' שנק' שה\"ש<sup data-n=\"7717\">564</sup> למעלה ממקיף הכללי לפרטי ההשתל' דקו\"ח כו' וכמ\"ש ויתן לך האלקי'<sup data-n=\"7718\">565</sup> מטל השמים לע\"ל דוקא (והוא שנק' טלא דנטיף<sup data-n=\"7719\">566</sup> מעתיקא סתימאה שנק' עתיקא דעתיקי[ן] והוא בחי' עצמו' התענוג הפשוט שבבחי' שעשועי' העצמיי' דא\"ס עצמו שנק' טה\"ע כמ\"ש במ\"א בענין ותחת <span data-k=\"pg\">452</span> ּ רגליו כמעשה לבנת הספיר שהוא שם ב\"ן דמל' דא\"ס בקו\"ח שנק' חי העולמים<sup data-n=\"7720\">569</sup> שיהי' בשלימות הבירורים דרפ\"ח דתהו ע\"י משיח כנ\"ל וכעצם השמים לטוהר<sup data-n=\"7721\">568</sup> זהו בחי' טה\"ע שלמעלה מבחי' הבירורים לגמרי), והוא בחי' הטלא עילאה שיחי' בו המתים<sup data-n=\"7722\">570</sup> שע\"ז א' מד' רוחות בואי הרוח כו' להחיות הגופים שהן יחודשו<sup data-n=\"7723\">571</sup> מעו\"ב<sup data-n=\"7724\">572</sup> ורוח אלקי' דעונג העצמו' יחי' אותם בחיות גמור במזון<sup data-n=\"7725\">573</sup> גשמי שהוא העוה\"ב שאין בו או\"ש<sup data-n=\"7726\">574</sup> כלל רק צדיקים נהנין כו' וכמ\"ש ונחי' לפניו ממש חיי נצחיי' בבחי' נצחיות דא\"ס ממש (וכמו עצמות יבישות<sup data-n=\"7727\">575</sup> שהחי' יחזקאל שקרם עליהם עו\"ב כו' שהראהו דוגמא דתח\"ה דלע\"ל (וזהו למעלה גם מאדה\"ר קודם החטא שהי' בבחי' בריאה בחומר וצורה האלקי' מחי העולמי' הכללי בלבד והי' מאכלו מפרי הג\"ע<sup data-n=\"7728\">*576</sup> (כמו לחם פנג דימות המשיח וכמזון המן שנק' מזונא דח\"ע<sup data-n=\"7729\">576</sup> שאין בו פסולת<sup data-n=\"7730\">577</sup> כלל, וכך הוא מעין זה בג\"ס השבת שנק' סעוד' דע\"ק<sup data-n=\"7731\">578</sup> ואין לזה ערך לאור וחיות דע\"ס<sup data-n=\"7732\">*579</sup> מבחי' העדן דעוה\"ב בתח\"ה כנ\"ל. ומ\"ש רז\"ל שיעשה סעודה לצדיקים מלויתן כו' זה יהי' בתח\"ה שיקומו גם האבות אברהם כו' ולא ירצה לברך רק דוד א' לי נאה לברך<sup data-n=\"7733\">579</sup> זהו ענין העונג דעצמו' שיבא בהגשמה להחיות הנשמות וכמו לחיותינו ברעב<sup data-n=\"7734\">580</sup> כו' וכמשה בהר לחם לא אכל<sup data-n=\"7735\">581</sup> כו', וזה יהי' רמז על שלימות הבירורי' דמ\"ע ול\"ת שנק' לויתן ושור הבר<sup data-n=\"7736\">582</sup> שדוד הוא משיח יברך על כוס של יין המשומר מוימ\"ב<sup data-n=\"7737\">583</sup> להיותו תכלית השלימות הבירורי' יותר מאבות כמ\"ש וגבה מאד כי חכמתו עמדה לו לתקן לבחי' התהו דחשך סתרו שנק' הדר כו', ולא כאברהם<sup data-n=\"7738\">584</sup> שיצא ממנו ישמעאל כו' גם יעקב עולם התיקון<sup data-n=\"7739\">585</sup> נשא<sup data-n=\"7740\">586</sup> ב' אחיות לאה ורחל בחי' ב\"ן<sup data-n=\"7741\">587</sup> דבינה ומל'<sup data-n=\"7742\">588</sup> שעתידה תורה לאסור כו' כמ\"ש במ\"א, וז\"ש כוסי רויה גימ' אר\"ך כוס ישועות אשא<sup data-n=\"7743\">589</sup>, לפי שע\"י תשובה דמשיח יבא כל המשכת העונג העצמות דתח\"ה והעוה\"ב",[["7716","563","<b>כי טל אורות טליך</b>: ראה לעיל פ' שמות ז, רע\"ב. וש\"נ."],["7717","564","<b>שה\"ש</b>: ד: שמי השמים."],["7718","565","<b>ויתן לך האלקי'</b>: תולדות כז, כח."],["7719","566","<b>טלא דנטיף</b>: ראה הערה 563."],["7720","569","<b>בקו\"ח שנק' חי העולמים</b>: ראה גם לקמן קפ, ד. ש\"א מג, א. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300670328\" data-slug=\"torat-chaim\" data-id=\"2300670328\">תו\"ח נח סח, סע\"ג</a>."],["7721","568","<b>ותחת רגליו. . וכעצם השמים לטוהר</b>: משפטים כד, י."],["7722","570","<b>הטלא. . המתים</b>: ראה שבת פח, ב."],["7723","571","<b>יחודשו</b>: א: מתכסות."],["7724","572","<b>מעו\"ב</b>: מעור ובשר."],["7725","573","<b>במזון</b>: א: בלא מזון. ד: כמזון."],["7726","574","<b>העוה\"ב שאין בו או\"ש </b>[ג: אכילה ושתי']: ראה ברכות יז, ב."],["7727","575","<b>עצמות יבישות</b>: יחזקאל פל\"ז."],["7728","*576","<b>מאדה\"ר. . מאכלו מפרי הג\"ע</b>: ראה גם לקמן תכב, ג."],["7729","576","<b>וכמזון המן שנק' מזונא דח\"ע</b>: ראה זהר בשלח סב, א."],["7730","577","<b>המן. . שאין בו פסולת</b>: ראה חוקת כא, ה וברש\"י שם. יומא עה, ב. מאמרי אדה\"א דברים ח\"ד ע' א'תק."],["7731","578","<b>בג\"ס </b>[אג: בג' סעודות]<b>. . סעוד' דע\"ק</b>: ראה גם מאמרי אדה\"א נ\"ך ס\"ע קמח ואילך. וש\"נ."],["7732","*579","<b>דע\"ס</b>: דעתיקא סתימאה."],["7733","579","<b>שיעשה סעודה. . לי נאה לברך</b>: ראה פסחים קיט, ב. הנסמן ב<a class=\"ft-cite\" href=\"#/read/torat-chaim/2300680444\" data-slug=\"torat-chaim\" data-id=\"2300680444\">תו\"ח תולדות קס, א</a> הערה 7. ש\"א לג, ב."],["7734","580","<b>לחיותינו </b>[אד: להחיותם]<b> ברעב</b>: תהלים לג, יט [ושם: ולחיותם — ראה בהנסמן בסמוך]. ראה לקמן רטז, ב. מאמרי אדה\"א שמות ח\"ב ע' תסג. וש\"נ. נ\"ך ס\"ע תעא."],["7735","581","<b>לחם לא אכל</b>: תשא לד, כח."],["7736","582","<b>דמ\"ע ול\"ת שנק' לויתן ושור הבר</b>: ראה מאמרי אדה\"ז על מארז\"ל ע' קמג."],["7737","583","<b>יין המשומר מוימ\"ב</b>: ראה ברכות לד, ב. מאמרי אדה\"א דברים ח\"א ע' סז. וש\"נ. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300670064\" data-slug=\"torat-chaim\" data-id=\"2300670064\">תו\"ח לך צא, ג</a> הערה 32."],["7738","584","<b>ולא כאברהם</b>: ראה פסחים שם."],["7739","585","<b>יעקב עולם התיקון</b>: ראה ע\"ח (שער העקודים) ש\"ו, פ\"א."],["7740","586","<b>יעקב נשא</b>: ראה פסחים שם."],["7741","587","<b>לאה ורחל בחי' ב\"ן</b>: ראה תו\"ח ח\"ש קלז, א הערה 10."],["7742","588","<b>לאה ורחל. . דבינה ומל'</b>: ראה פרדס (שער ערה\"כ) שכ\"ג, בערכם."],["7743","589","<b>כוס ישועות אשא</b>: תהלים קטז, יג."]]],[2300540868,"דוקא כנ\"ל בענין תשובה ומע\"ט כו' שהתשובה דוקא גורם המשכת רצה\"ע בהתפשטו' ורוחב דעצמו' העונג כמו רחבה מצותך מאד כו' וד\"ל).\n<b>וז\"ש</b> דמאן דלא כרע במודים כו', דהנה כריעה זאת היינו בגוף הגשמי דוקא שכורע וכופף קומתו שאע\"פ שזהו ביטול חיצוני מאד אבל העצמו' שבשדרה שכופף בכריעה זו הוא דוקא הגורם שיקום בתח\"ה דוקא. והענין הוא דבכריעה זו יש בחי' הביטול מעצמותו רק בבחי' ההודאה שלמעלה מן השכל והטעם, ואמנם זהו אשר מגיע למעלה ג\"כ להיות בבחי' היו\"ד דשם הוי' הנעלם שלמעלה מסובב הכללי דשם אמר כחשיכה כאורה<sup data-n=\"7744\">590</sup> כו' העלם וגילוי שוין ממש ע\"כ יכול להיות נמשך הטל להחיות העצמו' היבישות שיקבלו אור וחיות העצמו' דתענוג הפשוט כנ\"ל. אך דוקא מי שהי' בגופו ודוקא בעצם שבשדרה בחי' הביטול בכריעה גשמי' אז יהי' עצם זה כלי לשכון בו גילוי אור הטל העליון שמבחי' עתיקא סתימאה להחיותו בחיי עולם כנ\"ל, אבל מי שלא הי' בגופו בעצמו' השדרה ביטול בכריעה גשמי' לא יקום בתח\"ה והוא מטעם הנ\"ל בענין תשובה ומע\"ט, שהתשובה מן המיצר דוקא גורם בחי' ההמשכה וההתפשטות דגילוי ההעלם דרצה\"ע שיומשך בשכר המצות בעוה\"ב כמ\"ש היום לעשותם כו' דהיינו בתשו' ומע\"ט ולמחר לקבל שכרם (ובחי' הביטול בכריעה בשדרה בגופו, הודאה <span data-k=\"pg\">רכו</span> ּ זו למעלה מהודאה שבשכל והשגה כמו השתחווא' אפי' ארץ בגופו דוקא בעזרה בעולי רגל<sup data-n=\"7745\">591</sup> כו' ולענין תח\"ה שהוא להחיות העצמו' צ\"ל בביטול שבעצם השדרה (והוא למעלה מכריעה בברוך בש\"ע שזוקף בשם<sup data-n=\"7746\">592</sup> הוי' בהודאה שבהשגה להמשיך ברכה מאת שם הוי' דאצי' לבד, אבל כריעה במודים הוא ביטול העצמות שיקום בתחה\"מ לקבל ברכת הוי' העצמי' מחיי החיים דעצמו' א\"ס שע\"ז נא' ברכת ה' תעשיר כו' לחיות חיי עולם (וז\"ש מחזיקנא טיבותא לרישאי דמנפשי' כרע<sup data-n=\"7747\">593</sup> להיותו בבחי' ביטול עצמי שלמעלה מן הדעת כו'). ובזה יובן מארז\"ל דמי שלא כרע במודים לאחר ז' שנים נעשה שדרתו נחש<sup data-n=\"7748\">594</sup> שמרמז בזה דנחש הקדמוני שנמשך ממנו סט' דמות נאחז בעצמו' השדרה שלו שלא יוכל לקום בתח\"ה וז' שנים הן ז\"מ דק\"נ כידוע וד\"ל).",[["7744","590","<b>כחשיכה כאורה</b>: נסמן לעיל פ' וארא סד, א."],["7745","591","<b>השתחווא'. . בעולי רגל</b>: נסמן לעיל קמג, א."],["7746","592","<b>מכריעה. . שזוקף בשם</b>: ברכות יב, סע\"א. ראה גם <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300680397\" data-slug=\"torat-chaim\" data-id=\"2300680397\">תו\"ח וישב ריא, ד</a>."],["7747","593","<b>מחזיקנא. . דמנפשי' כרע</b>: ראה ירושלמי ברכות פ\"ב, סה\"ד כגי' תוד\"ה עיון שבת קיח, ב."],["7748","594","<b>לאחר. . שדרתו נחש</b>: ב\"ק טז, סע\"א. ראה ש\"א כא, א."]]],[2300540877,"<b>ונמצא</b> מובן ג\"כ מזה שסיבת המשכת העונג [העצמי'] דעוה\"ב ותח\"ה אינו בא רק מבחי' הבירור השלם בתשו' ומע\"ט דימות המשיח כנ\"ל, וז\"ש בזהר דמאן דלא מהפך חשוכא<sup data-n=\"7749\">595</sup> כו' בהאי עלמא לית לי' כו' וד\"ל.\n<b>וזהו</b> אז ישיר משה ובנ\"י את השירה הזאת כו' אשירה לה' כי גאה גאה כו', דהנה פי' אז ישיר לעבר ולהבא<sup data-n=\"7750\">596</sup> משמע, אז לעבר [י]שיר להבא משה ובנ\"י יחד ובאמת השירה הזאת בקי\"ס הי', אך לפי שקי\"ס הי' האור מעין דלעתיד ממש כמ\"ש הפך ים כו' שם נשמחה בו כנ\"ל ע\"כ א' אז ישיר משה כו' וקאי אדסמיך לי' שא' ויאמינו בהוי'<sup data-n=\"7751\">597</sup> ובמשה עבדו עבד הוי' להמשיך לשם הוי' דעצמו' הא\"ס ב\"ה למטה במצות כמו שהוא למעלה ממש כמו בעוה\"ב כנ\"ל, ע\"כ יכול משה לשורר לשירה זאת עם בנ\"י יחד (שנתחברו בחי' או\"י דמשה מה שמו העצמי עם [ב]נ\"י בחי' או\"ח<sup data-n=\"7752\">598</sup> דמצות בפו\"מ יחדיו כו'). אשירה להוי' כי גאה גאה כו' הנה א' ישיר לשון יחיד והול\"ל ישירו משה ובנ\"י וגם אשירה לשון יחיד, לפי שנכללו בנ\"י במשה במה שהאמינו במשה עבדו עבד הוי' העצמי כנ\"ל. והנה מ\"ש כי גאה גאה ת\"א גיאה על גיוותניא כו' שז\"ש סוס ורוכבו רמה בים סוס גימ' ב\"פ ס\"ג<sup data-n=\"7753\">599</sup> אותיות גס<sup data-n=\"7754\">600</sup> והוא בחי' גסות דכתר דק\"נ ששרשו בגיאות העליון בס\"ג דתהו השפיל גיאי[ם] לפי שהוא גאה גאה כו'. והענין הוא כנ\"ל שיש ב' מדרגות בשם הוי', א' בחי' הוי' הנעלם שבבחי' כתר ובכלל הוא בחי' כתר דמל' דא\"ס שזהו בחי' התנשאות דמצד עצם הרוממות כנ\"ל בוי\"ו דוהנורא כו', והב' שם הוי' דמל' דא\"ס שבא בבחי' ההתגלות להיות מלכותך מל' כ\"ע<sup data-n=\"7755\">601</sup> כו' ע\"י צמצום ולבוש כמ\"ש ה' מלך גאות לבש (שזהו נק' מקיף הכללי שמתנשא על ימות עולם וזהו גאה הב', אבל גאה גאה הוא מל' דא\"ס עצמו<sup data-n=\"7756\">602</sup> שנק' מלך יחיד לבדו כנ\"ל), ואין ערוך כלל בין הוי' דמל' דא\"ס המצומצם בקו\"ח באבי\"ע לעצמות הרוממות דשם הוי' הנעלם כשעלה ברצונו הפשוט כו'. ואמנם בקי\"ס הי' בחי' גילוי ההעלם דמל' דא\"ס עצמו כשהפך ים ליבשה כנ\"ל (וכמו שא' מלכותך ממש ראו בניך לפי שבוקע הים לפני משה ע\"כ זה אלי כו') וזה הי' ע\"י משה דוקא כשהרים ידו על הים כמ\"ש ויט משה כו' ויולך ה' ברוח קדים כו', לפי ששרש משה מה שמו<sup data-n=\"7757\">603</sup> הוא שם הוי' שבעצמו' השעשועי' דא\"ס עצמו שלמעלה גם <span data-k=\"pg\">454</span> ּ מעונג דמל' דא\"ס כמ\"ש לך ה' הממלכה כנ\"ל, ע\"כ הי' ביכולתו לעשות מהעלם דמל' דא\"ס שהוא המלך",[["7749","595","<b>דמאן דלא מהפך חשוכא</b>: ראה לעיל פ' שמות ט, א. וש\"נ."],["7750","596","<b>אז ישיר. . לעבר ולהבא</b>: בשלח טו, א. ראה גם שה\"א נ, א (ובהנסמן במ\"מ לשם). ע, ב."],["7751","597","<b>ויאמינו בהוי'</b>: בשלח יד, לא."],["7752","598","<b>או\"י דמשה. . [ב]נ\"י בחי' או\"ח</b>: ראה שער האמונה ע, ב ובהנסמן במ\"מ שם נ, א הערה 2."],["7753","599","<b>סוס גימ' ב\"פ ס\"ג</b>: ראה גם לקמן קסט, א. קעט, ב. <a class=\"ft-cite\" href=\"#/read/torah-or/3901370411\" data-slug=\"torah-or\" data-id=\"3901370411\">תו\"א צא, ב</a>. <a class=\"ft-cite\" href=\"#/read/torah-or/3901370414\" data-slug=\"torah-or\" data-id=\"3901370414\">ד. צב, א</a>. <a class=\"ft-cite\" href=\"#/read/torah-or/3901370432\" data-slug=\"torah-or\" data-id=\"3901370432\">צו, ג</a>. <a class=\"ft-cite\" href=\"#/read/torah-or/3901370435\" data-slug=\"torah-or\" data-id=\"3901370435\">צז, ב</a>. <a class=\"ft-cite\" href=\"#/read/torah-or/3901370536\" data-slug=\"torah-or\" data-id=\"3901370536\">קכ, ב</a>. מאמרי אדה\"ז תקס\"ו ע' קכג. ע' קנה. ע' קנט. הנחות הר\"פ ע' קנב. מאמרי אדה\"א קונטרסים ע' שצ."],["7754","600","<b>ס\"ג אותיות גס</b>: ראה גם מאמרי אדה\"א שמות ח\"ב ע' תקסו. וש\"נ. דרך מצותיך סז, ב. שעה\"י קמא, ב ובהערה 23. ש\"א עג, א ובהערה 15. לקמן פ' משפטים שג, א. תשא שפד, ד."],["7755","601","<b>דמל' דא\"ס. . מלכותך מל' כ\"ע</b>: ראה גם לעיל קמב, ב. וש\"נ."],["7756","602","<b>גאה גאה הוא מל' דא\"ס עצמו</b>: ראה גם לעיל קמ, א. וש\"נ."],["7757","603","<b>משה מה שמו</b>: נסמן לעיל פ' שמות מג, ד."]]],[2300540886,"המרומם לבדו<sup data-n=\"7758\">604</sup> להיות הוא עצמו בבחי' גילוי כו' כמ\"ש הים ראה וינוס כו' והוא מפני שמשה נק' עבד הוי' להמשיך ולחבר לעצמו' דא\"ס למטה כמו שהוא במהו\"ע ממש כנ\"ל בענין בכל ביתי נאמן הוא כו', ולזה הי' ביכולתו ג\"כ להעלות ל[ב]נ\"י עמו שישירו שירה הזאת להוי' שבעצמו' א\"ס לומר עמו יחד כי גאה גאה שבחי' ההעלם דגיאות האמיתי יבא בגילוי <sup data-n=\"7759\">605</sup>על גיאות דמלך על עם (כענין אגוסטוס יושב אז מלך עומד כו'), ואז ממילא סוס ורוכבו שהן הגיאות דגסות דפרעה רמה בים שהרי אין לישות<sup data-n=\"7760\">606</sup> דכתר דק\"נ אחיזה ושרש רק בכתר מל' דקדושה שבא בגילוי להיות מלך לעולם באחוריי' וחיצוני' כנ\"ל, אבל במל' דא\"ס עצמו כשבא בגילוי אין להם שרש כלל וכנ\"ל במ\"ש פרעה לא ידעתי את הוי' הנעלם כו' והוא מצד שבחי' החושך נעשה אור כמ\"ש ויהי הענן והחשך ויאר כו' (וכמו שיהי' לע\"ל במל' דמשיח שיתגלה פחד ה'<sup data-n=\"7761\">607</sup> ונק' נורא כו'), וזהו הטעם שבשעת קי\"ס דוקא שבחי' ההעלם עצמו נעשה<sup data-n=\"7762\">*608</sup> גילוי א' אז ישיר משה ובנ\"י אז דוקא וישיר להבא כמו שיהי' לע\"ל שא' שם נשמחה בו ממש שלפניו ההעלם עצמו נעשה גילוי כו' וד\"ל. וזהו שאחר שהאמינו בה' ובמשה עבדו שהוא בחי' הממוצע לחבר ולקשר לשם הוי' העצמי שיתגלה בעוה\"ב אז ישיר משה ובנ\"י יחד כו' כי גאה גאה לעשות מההעלם גילוי כנ\"ל וד\"ל.\n<b>ויש</b> ענין זה בכל שנה גם עכשיו בכל יו\"כ ויו\"כ שהוא מעין העוה\"ב ממש שנק' שבת שבתון<sup data-n=\"7763\">608</sup> כו' קדוש ה' מכובד<sup data-n=\"7764\">609</sup> שאין בו או\"ש כו' כידוע, והיינו בהמשכת י\"ג מדה\"ר שהי' ע\"י משה שירד ביו\"כ<sup data-n=\"7765\">*610</sup> וכמ\"ש ויעבור ה' על פניו ויקרא<sup data-n=\"7766\">611</sup> ה' ה' אל רחום כו', ולכאורה משמעות ויקרא זה דקאי על שם הוי'<sup data-n=\"7767\">612</sup> שזכר קודם ויעבור ה' על פניו ואח\"כ שם הוי' קרא ה' ה' כו', אבל באד\"ר מבואר להדיא דויקרא זה קאי על משה<sup data-n=\"7768\">613</sup> שאחר שעבר ה' על פניו ויקרא משה ה' ה' כו', לפי שבחי' מקור סיבת המשכות די\"ג מדה\"ר במשה דוקא תליא מילתא, והיינו מטעם הנ\"ל ששרש משה מ\"ה דשם הוי' העצמו' ממש שלפניו כל בחי' העלם נעשה גילוי וע\"כ הי' ביכולת משה דוקא להמשיך מבחי' העונג ושעשועי' הפשוטי' ועצמיי' דא\"ס עצמו לקרות הוי' הוי' שיומשך בחי' י\"ג מדה\"ר דרעוא דכ\"ר מן ההעלם להיות בבחי' גילוי לסליחת העוונות שזהו למעלה מבחי' הרצון המורכב בטעם וחכ' דתורה כידוע. ואמנם כח זה לעשות מהעלם דרעוא דכל רעוין גילוי גמור בא' הוי' הוי' אע\"פ דפסיק טעמא בגווייהו כו'",[["7758","604","<b>דמל' דא\"ס שהוא המלך המרומם לבדו</b>: ברכת יוצר. ראה גם לעיל פ' בא צ, א. וש\"נ."],["7759","605","<b>על</b>: א: ע\"י. ג: אל."],["7760","606","<b>לישות</b>: ד: לאוה\"ע."],["7761","607","<b>לע\"ל. . פחד ה'</b>: נסמן לקמן קפה, ב."],["7762","*608","<b>נעשה אור. . נעשה</b>: בתו\"ח כאן נכפלו שורות אלו."],["7763","608","<b>יו\"כ. . שנק' שבת שבתון</b>: ראה גם לעיל פ' בא צד, ב. וש\"נ."],["7764","609","<b>קדוש ה' מכובד</b>: ראה ישעי' נח, יג. שבת קיט, א. לקמן פ' ויקהל תטו, ג. מאמרי אדה\"ז תקס\"ה ח\"ב ע' תתלא. מאמרי אדה\"א דברים ח\"ד ע' א'קפג וע' א'שפד."],["7765","*610","<b>בהמשכת י\"ג מדה\"ר. . ביו\"כ</b>: ראה גם לקמן קעב, א. וש\"נ."],["7766","611","<b>ויעבור. . ויקרא</b>: תשא לד, ו."],["7767","612","<b>ויקרא זה דקאי על שם הוי'</b>: ראב\"ע ורשב\"ם עה\"פ. וראה אוה\"ת תשא ע' ב'סז. ר\"ה יז, ב. תנחומא תשא לב."],["7768","613","<b>באד\"ר. . דויקרא זה קאי על משה</b>: ראה (נשא שם) קלח, א. תרגום ירושלמי עה\"פ. פדר\"א ספמ\"ו. אוה\"ת שם. מאמרי אדה\"א במדבר ח\"ב ע' תלד."]]],[2300540895,"זהו תלוי במשה דוקא לפי שנק' ר\"מ באמונה דאמתת העצמו' דא\"ס ב\"ה ממש שיתגלה בעוה\"ב, וע\"כ א' אשירה לשון יחיד לפי שנכללו בנ\"י עמו פי'<sup data-n=\"7769\">614</sup> שהוא העיקר רק גם הם העלה באמונה רבה זו שהאמינו גם במשה עבדו (כמו שישראל עלו במח'<sup data-n=\"7770\">615</sup> העצמי' שלמעלה ממחשבה הכללי' כידוע וד\"ל).",[["7769","614","<b>פי'</b>: אד: לפי."],["7770","615","<b>שישראל עלו במח'</b>: ראה גם לעיל פ' שמות לב, ב. וש\"נ."]]],[2300540070,"<b>בעז\"ה</b>\n<span data-k=\"pg\">רכז</span> ּ<b>אז</b> ישיר<sup data-n=\"7771\">1</sup> משה ובנ\"י כו' אשירה לה' כי גאה גאה סוס ורוכבו רמה בים<sup data-n=\"7772\">2</sup>, להבין ענין חזרת כנס\"י<sup data-n=\"7773\">3</sup> מדרכי הישר לא\"י במסעות הידועים עפ\"י ה' להיות חונים נגד הים<sup data-n=\"7774\">4</sup> כו', למען ידעו מצרים<sup data-n=\"7775\">5</sup> כו' והלא לא נותר מהם עד א[חד]<sup data-n=\"7776\">6</sup> ומי יודע מהאותות שיספר כו'. וגם להבין כל עיקר ענין קי\"ס מהו, כתיב ברוך ה' אלקי ישראל מן העולם ועד העולם ב' עולמות<sup data-n=\"7777\">8</sup> אלו הם עלמא דאתכסייא ועלמא דאתגלייא<sup data-n=\"7778\">9</sup> כו' והוא ענין קי\"ס. וביאור הדבר כי הנה על שלשה דברים<sup data-n=\"7779\">10</sup> העולם עומד על התורה ועבודה כו', עבודה הן [ה]קרבנות<sup data-n=\"7780\">11</sup> שהי' אש שלמעלה יורד<sup data-n=\"7781\">12</sup> וא[ו]כל הבהמה ע\"ג המזבח, כמ\"כ בכל יום חייב אדם למסור נפשו הבהמית שת[ו]כלל באש שלמעלה שיורד וא[ו]כל אש שלמטה שבגופו כו', וענין האש שלמעלה היינו ענין התפלה שהיא עבודה שבלב<sup data-n=\"7782\">13</sup> במקום קרבן<sup data-n=\"7783\">14</sup> כו' באומרו ברוך אתה ה' מן<sup data-n=\"7784\">15</sup> העולם ועד העולם כו' שהוא בחי' סוכ\"ע וממכ\"ע כי הוי' הוא האלקי'<sup data-n=\"7785\">16</sup> כידוע וכשמוסר<sup data-n=\"7786\">18</sup> נפשו הבהמי' לה' אחד ג\"כ אזי בחי' אש שלמעלה מהארת סוכ\"ע שורה ומתגלה בנפשו כי ברוך לשון המשכה<sup data-n=\"7787\">19</sup> וגילוי מן ההעלם הוא כידוע וד\"ל.\n<b>וכדי</b> להבין שרש הדברים יש להקדים מארז\"ל כל מה שיש ביבשה<sup data-n=\"7788\">20</sup> יש בים כנגדן<sup data-n=\"7789\">21</sup> כו', כי הנה אנו רואים הפרש",[["7771","1","<b>אז ישיר</b>: מאמר זה הוא מכ\"ק אדה\"ז שנאמר בש\"פ בשלח תקס\"ג, וישנו בג' נוסחאות: א) מכ\"ק אדה\"א והיא הנדפסת כאן. ונדפסה גם במאמרי אדה\"ז תקס\"ג ח\"א ע' קנג [ובע' תקסז שם ישנו ביאור קצר שלא נדפס כאן]. ב) הר\"מ בן כ\"ק אדה\"ז נדפסה במאמרי אדה\"ז שם. ג) ב<a class=\"ft-cite\" href=\"#/read/torah-or/3901370279\" data-slug=\"torah-or\" data-id=\"3901370279\">תו\"א בשלח סב, ב</a>. והערות וכו' באוה\"ת בשלח כרך ז ע' ב'תרסז. ע' ב'תרסט. וראה עוד ע\"ד המאמר להלן ברשימת הכת\"י [ושם ג\"כ מפורט סימני האותיות הבאים להלן בהמראי מקומות]."],["7772","2","<b>אז ישיר. . בים</b>: בשלח טו, א."],["7773","3","<b>כנס\"י</b>: ג: בנ\"י."],["7774","4","<b>להיות חונים נגד הים</b>: בשלח יד, א."],["7775","5","<b>למען ידעו מצרים</b>: עד\"ז בהנחת הר\"מ כאן: בכדי שידעו מצרים כי אני הוי'. ובתו\"א כאן: וידעו מצרים כי אני ה' — בשלח יד, ד. יח. וראה להלן הערה 131."],["7776","6","<b>לא נותר מהם עד א</b> [חד]: בהנחת הר\"מ כאן: כתי' לא נשאר בהם עד אחד — בשלח יד, כח. ובתו\"א כאן: כתיב ויכסו מים צריהם אחד מהם לא נותר — תהלים קו, א."],["7777","8","<b>עולמות</b>: ג: עולמים."],["7778","9","<b>עלמא דאתכסייא ועלמא דאתגלייא</b>: נסמן לעיל לג, א."],["7779","10","<b>על שלשה דברים</b>: ראה אבות פ\"א, מ\"ב."],["7780","11","<b>עבודה הן [ה]קרבנות</b>: ראה מפרשי המשנה אבות שם."],["7781","12","<b>אש שלמעלה יורד</b>: ראה תו\"כ ויקרא א, ז. עירובין סג, א."],["7782","13","<b>התפלה שהיא עבודה שבלב</b>: ראה ספרי (ופרש\"י) עקב יא, יג. תענית ב, סע\"א. רמב\"ם ריש הל' תפלה. <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8316450608\" data-slug=\"or-hatorah-hb\" data-id=\"8316450608\">אוה\"ת עקב ע' תרח</a>."],["7783","14","<b>התפלה שהיא. . במקום קרבן</b>: נסמן לעיל פד, ג."],["7784","15","<b>באומרו ברוך אתה ה' מן</b>: ראה גם לעיל פ' וארא נב, ד. וש\"נ. בהנחת הר\"מ כאן (ע' קנד): שאומרים בתפלה ב\"א [ ברוך אתה] הוי' כו' מן. ובתו\"א כאן: ”בש\"ע. . ברוך אתה כו'. והוא ע\"ד מ\"ש ברוך ה' אלקי ישראל מן\"."],["7785","16","<b>סוכ\"ע וממכ\"ע כי הוי' הוא האלקי'</b>: נסמן לעיל עג, ב."],["7786","18","<b>וכשמוסר</b>: ג: וכשנקשר. ועד\"ז באדה."],["7787","19","<b>ברוך לשון המשכה</b>: נסמן לעיל קס, ג."],["7788","20","<b>כל מה שיש ביבשה</b>: נסמן לעיל יח, ג."],["7789","21","<b>יש בים כנגדן</b>: ג: כנגדן יש בים."]]],[2300540108,"בין ברואים שביבשה לברואים שבים שברואים שבים א\"א להחיות<sup data-n=\"7790\">22</sup> אפי' רגע<sup data-n=\"7791\">23</sup> בלתי הים וכדבר א' ממש נחשבו וההוראה ע\"ז הוא אשר הבריאה מובלעת בתוך הים והים מכסה עליהם מלמעלה לומר שאינו נחשבת לדבר ממש<sup data-n=\"7792\">24</sup> בפ\"ע כלל ותמיד צריכים לשאוב שפע חיותה מן הים וכאלו אין במציאות רק הים לבדו, אבל הברואים נסתרים ונעלמים בים כאלו אינם במציאות כלל כו', משא\"כ ברואי' שביבשה אעפ\"י שמקבלים חיותם מן אויר הארץ ומעפר הארץ יסודם אינם צריכים ג\"כ<sup data-n=\"7793\">25</sup> לתמידות קבלת השפע כי הרי יוכלו להתקיים זמן רב באויר השמימה הגבה למעלה מאויר [חומר] עפר הארץ כו', וכמ\"ש כ\"ז בארוכה במ\"א וד\"ל. וזה הוראה [א]ל היפוך שהם נבדלים ונפרדים ליש ודבר מה בפ\"ע כו', וה\"ז כמו ה[ו]לד בבטן אמו שעובר כירך אמו הוא<sup data-n=\"7794\">26</sup> והוא מכוסה ונעלם בבטנה וכאלו אינו במציאות כי אוכל מה שאמו אוכלת<sup data-n=\"7795\">27</sup> כו' ואמנם לאחר [הלידה] שיצא לאויר העולם א\"צ לאמו בבחי' ביטול [ב]מציאות כ\"כ כי הרי הוא יש ודבר בפ\"ע רק שיונק משדי אמו כו'. וע\"כ<sup data-n=\"7796\">28</sup> משלים<sup data-n=\"7797\">29</sup> אלו יובן ג\"כ למעלה צ\"ל<sup data-n=\"7798\">30</sup> ההפרש בין עלמא דאתכסיא לעלמא דאתגליא, כי הנה מדת מל[כותו] ית' בכל [משלה] להחיות רוח שפלים<sup data-n=\"7799\">31</sup> דבע\"ג מאין ליש בבחי' התגלות ממש ליש ודבר נפרד לעצמו והשפע [ה]אלקי המחי' אותו בבחי' הסתר והעלם עליהם כו' הוא בחי' [יבשה] הארץ הדום רגלי<sup data-n=\"7800\">32</sup> הנק' ארץ העליונה והוא עלמא דאתגליא כו', אמנם כנגדן ממש יש בכל פרטי התחלקות הנבראים בעודנם בבחי' בנין<sup data-n=\"7801\">33</sup> מל' דאצי' עובר ירך אמו הוא כו' והוא בחי' ימא עילאה עלמא דאתכסיא שהם בתכלית ביטול המציאות וכאילו אינם כו' כי ימא עילאה מכסה עליהם ואפילו רגע לא יתקיימו בלעדו כו', <span data-k=\"pg\">456</span> ּ והן ענין הנשמות הגבוהות כמו נשמת משרע\"ה שנאמר עליו כי מן המים משיתיהו<sup data-n=\"7802\">34</sup>, פי' מן המים עליונים דימא עילאה קודם ש[נ]קוו המים ונתגלה בחי' היבשה כו' והיינו בחי' הוי' סוכ\"ע, ולכך נאמר במשה שהי' כבד פה וכבד לשון<sup data-n=\"7803\">35</sup> כו', פי' פה העליון הוא הדבור העליון בדבר ה'",[["7790","22","<b>להחיות</b>: א: להם לחיות. ג: לה לחיות. ד: להם להיות."],["7791","23","<b>שברואים שבים. . אפי' רגע</b>: ראה גם שה\"א פד, א ובהערה 4."],["7792","24","<b>שאינו. . ממש</b>: אג: שאינה. ד: שאין. . א: יש. גד: ויש."],["7793","25","<b>ג\"כ</b>: ג: כ\"כ."],["7794","26","<b>שעובר כירך אמו הוא</b>: גיטין כג, ב."],["7795","27","<b>אוכל מה שאמו אוכלת</b>: נדה ל, ב."],["7796","28","<b>וע\"כ</b>: אגד: וע\"ד."],["7797","29","<b>משלים</b>: מכאן עד לקמן על יד הערה 68 נשמט בטעות במאמרי אדה\"ז תקס\"ג כאן (ע' קנה)."],["7798","30","<b>למעלה צ\"ל</b>: א: המשל למעלה. דה: למעלה."],["7799","31","<b>להחיות רוח שפלים</b>: ישעי' נז, טו."],["7800","32","<b>הארץ הדום רגלי</b>: ישעי' סו, א [ושם: והארץ — ראה לקמן קסה, ד. הנסמן בשה\"א עה, א הערה 9]."],["7801","33","<b>בנין</b>: אג: בטן. ד: כבפנים."],["7802","34","<b>כי מן המים משיתיהו</b>: נסמן לעיל פ' שמות מג, א."],["7803","35","<b>כבד פה וכבד לשון</b>: שמות ד, י."]]],[2300540146,"שמים נעשו<sup data-n=\"7804\">36</sup> כו' כידוע שהוא בחי' כח הפועל בנפעל<sup data-n=\"7805\">37</sup> בחי' יבשה וארץ העליונה עלמא דאתגליא הנ\"ל, ולפי שהיתה נשמתו הגבה למעלה מפה העליון אלא בבחי' ים העליון עלמא דאתכסיא שלמעלה מן הדבור לכך הי' כבד פה שלא [הי'] יכול לדבר בגילוי כי הוא ירידה גדולה אלא השתיקה יפה לו לענין מדריגתו מבחי' ההעלם והביטול מ\"ה שבחכמה כו', כי ידוע שמצד מ\"ה שבחכ' שהוא ביטול ההשגה לומר מה פשפשת<sup data-n=\"7806\">38</sup> כו' יבא סיבת השתיקה שישתוק ולא יוכל להביא השכל בדבור כלל כ\"א באותיות מחשבתו לבד כו', משא\"כ גילוי השגת החכ' יוכל לגלותה גם בדבור כו', [וז\"ש] ונחנו מ\"ה<sup data-n=\"7807\">39</sup> כו' וז\"ש<sup data-n=\"7808\">40</sup> הי' מפנימי' חכ' כח מ\"ה<sup data-n=\"7809\">41</sup> תכלית ביטול המציאות כו', וכן ענין נשמת רב המנונא סבא<sup data-n=\"7810\">42</sup> שנק' בשם נוני דימא עילאה מזה הטעם כמ\"ש במ\"א וד\"ל.\n<b>והנה</b> יש בזה ב' מדריגות, הא' בבחי' ההתחלקות, והגם<sup data-n=\"7811\">43</sup> שהוא מקור ענין ההתחלקות כמו הברואים שבים העליון עלמא דאתכסיא כו' יקרא בשם סובב שבממלא והכל בבחי' מל' לבד כמ\"ש במ\"א, ועד\"מ התחלקות נרנח\"י<sup data-n=\"7812\">44</sup> שהנשמה יחידה היא ונחלקת לג' חלקים שכל ומדות ומחדו\"מ והשכל נחלק לג' חלקים והמדות לז' כו' וכ\"א מקבל שפע לעצמו לבד, החכמה מקבל בפ\"ע והמדה בפ\"ע כו', [והמקיפי'] של נר\"נ המה מקור התחלקות זו הם כמשל ברואים שבים הנ\"ל, וגם למעלה יובן שזהו בחי' סובב שבממלא לבד. אמנם סוכ\"ע עצמו הוא הגבה למעלה גם מענין מקור להתחלקות נבראים, והוא מ\"ש ברוך ה' מן העולם ועד העולם פי' ברוך שיומשך אור הוי' סוכ\"ע העצמי לעלמא דאתכסיא להקרות בשם הוי' באלקים ממכ\"ע ואח\"כ מן העולם הזה לעלמא דאתגליא בנבראים הנפרדי' ליש ודבר בפ\"ע כנ\"ל וד\"ל.\n<b>וזהו</b> פי' ענין קי\"ס דכתיב הפך ים ליבשה<sup data-n=\"7813\">45</sup> כו' דמאחר שהלכו ביבשה בתוך הים הי' כמו\"כ למעלה בחי' גילוי הארה דיבשה עליונה הנ\"ל בתוך העלם הים העליון וסיבת הפיכת העלם הים לגילוי הוא מפני ששם נשמחה בו פי' השמחה היא הביאה ההעלם לגילוי<sup data-n=\"7814\">46</sup> וזהו אז ישיר משה כו'. וביאור הדבר הוא להיות כי ענין השמחה הוא התפעלות עצמות הנפש שתצא מן ההעלם לגילוי לבד כו', שהרי אנו רואים השמחה מן השירה הוא התפעלות שכליים ולא התפעלות המדות כי בניגון שיכוין",[["7804","36","<b>בדבר ה' שמים נעשו</b>: תהלים לג, ו."],["7805","37","<b>כח הפועל בנפעל</b>: נסמן לעיל פ' וארא עה, א."],["7806","38","<b>מה פשפשת</b>: זהר בהקדמה א, ב."],["7807","39","<b>ונחנו מ\"ה</b>: ראה גם לעיל פ' שמות מג, א. וש\"נ."],["7808","40","<b>כו' וז\"ש</b>: אדה: כי."],["7809","41","<b>חכ' כח מ\"ה</b>: זהר (רע\"מ) צו כח, א. לד, א. ראה גם לעיל פ' שמות לג, א. וש\"נ."],["7810","42","<b>רב המנונא סבא</b>: ראה גם ביאוה\"ז בשלח מא, סע\"ג ואילך. בלק קמט, א. הנסמן לעיל פ' בא צט, ג."],["7811","43","<b>והגם</b>: תוקן ע\"פ אגדה (ועד\"ז ב)."],["7812","44","<b>נרנח\"י</b>: נסמן לעיל פ' בא פט, ג."],["7813","45","<b>הפך ים ליבשה</b>: תהלים סו, ו."],["7814","46","<b>השמחה היא הביאה ההעלם לגילוי</b>: ראה לעיל קנז, ב. וש\"נ."]]],[2300540183,"בו ההשגה הגם שלא יהי' דבר חדש בהשגתו מאז ומקדמת דנא כו' עכ\"ז יתפעל מאד, וא\"כ אין זה מצד ההשגה עצמה כדרך שנולדים התפעלות המדות ממנה כו' שהרי אין בה התחדשות כלל, אך הענין הוא שמחמת הזמר והשיר בהשגתו תצא ההשגה לגילוי בנפשו מן ההעלם היחידה שבנפשו ומסיבת זה יהי' התפעלות הנפעלות<sup data-n=\"7815\">47</sup> הנפש גדולה בשיר בשמחה רבה כו', וא\"כ היינו התפעלו' השכל שנתפעל השכל וההשגה עצמה ויצא מן ההעלם הנפש <span data-k=\"pg\">רכח</span> ּ לגילוי ולא התפעלות שחוץ ממנה כו', ולזה הטעם לא [תתיישן] ההשגה עולמית ולעולם תתפעל ע\"י הזמר כו' כי ההעלם לא ישתנה כו' ואין לו הפסק כו' וד\"ל. וזהו [ש]שמחת השיר היא בחי' גבורות יין המשמח כו' נכנס יין יצא סוד<sup data-n=\"7816\">48</sup> שפעולתו להביא לידי גילוי כנ\"ל כו'. ובזה יובן ענין פסוד\"ז שהם הכנה לבא ההעלם [דהוי'] סוכ\"ע<sup data-n=\"7817\">49</sup> העצמי לידי גילוי בש\"ע באמרו ברוך כו' [פי'<sup data-n=\"7818\">50</sup> ] שהזמרה הוא שמחת השיר מעורר למעלה סיבת הגילוי מן ההעלם והיינו בחי' התפעלו' ההתבוננו' עצמה שתבא לידי גילוי ולא התפעלו' שחוץ ממנו כנ\"ל. וזהו אז ישיר [משה הוא] הדעת<sup data-n=\"7819\">51</sup> וההתבוננות באלקים חיים שיש בכאו\"א מישראל<sup data-n=\"7820\">52</sup> כל חד לפום מה דמשער בלבי'<sup data-n=\"7821\">53</sup> כו' [ישיר משה] שבא לידי גילוי מן ההעלם ע\"י השיר כנ\"ל והיינו גילוי הוי' סוכ\"ע בכאו\"א מישראל כו', וענין אז ישיר <sup data-n=\"7822\">54</sup>משה ולא מקדמת דנא היינו לפי שבשעת קי\"ס הי' ענין גילוי ההעלם של ים העליון כנ\"ל, וזהו שם נשמחה בו שם דייקא וד\"ל.\n<b>וזהו</b> ועבד הלוי הוא<sup data-n=\"7823\">55</sup> פי' הלוי היינו השיר שעל הקרבן<sup data-n=\"7824\">56</sup> שהיו הלוים משוררים בשעת הקרבת הקרבן ע\"ג המזבח ע\"י הכהן המקריבה כידוע, והנה ג' דברים שהעולם עומד וא' מהם העבודה שבלב שבמקום כהן המקריב ע\"ג המזבח כנ\"ל היינו ענין גילוי והמשכת ההעלם דהוי' העצמי בממכ\"ע בברכות ש\"ע בחשאי<sup data-n=\"7825\">57</sup> דוקא כי המשמיע קולו בתפלתו<sup data-n=\"7826\">58</sup> כו', מפני שבחי' כהן הוא בלחש<sup data-n=\"7827\">59</sup> דוקא לפי שהיא מבחי' ביטול מ\"ה שבחכמה<sup data-n=\"7828\">60</sup> כו', אבל עבודת הלוי הוא להיפוך שישיר בשיר ברעש גדול בשעת הקרבן, וענין השירה הוא העלאת מ\"ן מלמטה לעורר השמחה עליונה ומפני זה יהי' הגילוי מן ההעלם ע\"י הכהן ואינו אלא לשר[ת] את הכהן<sup data-n=\"7829\">61</sup> כו', וזהו ועבד הלוי עבודת הלוי אינו אלא הוא פי' שיתגלה ההעלם הנק' הוא כמ\"ש כי הוי' הוא האלקים, דהיינו שיש הפרש בין הוי' העצמי לאלקי' הים העליון הנק' עלמא דאתכסיא ולכך הוא בלשון נסתר שאינו ידוע מי משא\"כ",[["7815","47","<b>הנפעלות</b>: בג: ליתא."],["7816","48","<b>נכנס יין יצא סוד</b>: עירובין סה, סע\"א. ראה גם <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300680053\" data-slug=\"torat-chaim\" data-id=\"2300680053\">תו\"ח ויחי רלו, ב</a>."],["7817","49","<b>סוכ\"ע</b>: גה: סובב."],["7818","50","<b>פי'</b>: ה: לפי."],["7819","51","[משה הוא]<b> הדעת</b>: נסמן לעיל פ' וארא פה, ד."],["7820","52","<b>משה. . שיש בכאו\"א מישראל</b>: נסמן לעיל קנו, ד."],["7821","53","<b>לפום מה דמשער בלבי'</b>: זהר וירא קג, ריש ע\"ב. ראה לקו\"ת מסעי פה, ב."],["7822","54","<b>משה</b>: גה: ליתא."],["7823","55","<b>ועבד הלוי הוא</b>: קרח יח, כג."],["7824","56","<b>השיר שעל הקרבן</b>: ראה גם לעיל פ' בא קו, ד. וש\"נ."],["7825","57","<b>ש\"ע בחשאי</b>: ראה שו\"ע אדה\"ז הל' תפלה סק\"א, ס\"ב-ד. הנסמן במאמרי אדה\"א בראשית ע' צט. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300670360\" data-slug=\"torat-chaim\" data-id=\"2300670360\">תו\"ח נח נב, א</a> הערה 4."],["7826","58","<b>המשמיע קולו בתפלתו</b>: נסמן לעיל פ' בא קח, ב."],["7827","59","<b>כהן הוא בלחש</b>: ראה זהר שמיני לט, א. אמור פח, ב. קרח קעז, ב. סה\"מ באתי לגני ח\"א ע' לז. וש\"נ."],["7828","60","<b>כהן. . מ\"ה שבחכמה</b>: ראה לקו\"ת יו\"כ ע, ב. וש\"נ. ע\"ח (שער לאה ורחל) של\"ח, פ\"ז (לקו\"ת תזריע כג, ב). אוצרות חיים שם (הובא בדר\"מ ק, א. ושם: דף פ\"ז פ\"ח, והוא במהדורת קארעץ תקמ\"ג). ביאוה\"ז שופטים קכב, א. ויצא יח, ב. סידור שער הסוכות רסח, ב. מאמרי אדה\"ז על פרשיות התורה ח\"א ע' רנב."],["7829","61","<b>הלוי. . לשר[ת] את הכהן</b>: במדבר ג, ז. קרח יח, ב."]]],[2300540220,"אתה [לנוכח], ועבודת הלוי אינו אלא לעשות הכנה שיהי' הוא הנסתר לנוכח להקרות אתה עלמא דאתגליא כנ\"ל, משא\"כ עבודת הכהן היינו להמשיך מהוי' העצמי שהוא מלמעלה למטה כמ\"ש כי הוי' הוא [ה]אלקי' וכמ\"ש בזהר<sup data-n=\"7830\">62</sup> וד\"ל.\n<b>וזהו</b> אשירה לה' כי גאה גאה כו', ויש להבין ענין הכפל, אך הענין הוא כנ\"ל [ש]סובב העצמי הוא למעלה מבחי' סובב שבממלא כו' כי הוא בבחי' עצמות האצי' ולכך נק' [גאה גאה פי'] גאה ומתנשא על הנק' גאה והוא בחי' סובב שבממלא כו' כמ\"ש כי אתה הוי' לבדך<sup data-n=\"7831\">63</sup> כו' להיות כי סובב שבממלא הרי הוא בבחי' סדר ההשתל' ראש וסוף בבחי' מקור דמקור כנ\"ל, והגם שנק' גם הוא גאה כמ\"ש ה' מלך גיאות לבש<sup data-n=\"7832\">64</sup> כו' שהוא סובב כל ממלא ראש וסוף כא' וכמ\"ש ומתחת זרועות [עולם<sup data-n=\"7833\">65</sup> כו'], עכ\"ז התנשאות זו היא לפי ערך המקבלים לבד [מ]כח הפועל אלקי הנק' ממלא אם בי\"ס דבריאה או דיצי' כו', אבל סובב העצמי הוא רם ומתנשא הגבה למעלה מהתנשאות זו וזהו גאה על גאה כו'. [ומובן] שיותר אין ערך המקיף לגבי בלתי מקיף שהוא העצמות שאין ערוך הפנימי' לגבי המקיף כו' עד\"מ הידוע מכל[י] השגת תלמיד זה לגבי שלמעלה הימנו גם המקיף יקרא פנימי כו' ואמנם לגבי הרב עצמו מקיפים דכולם לא יקרא אפי' בשם פנימי כי מופלא ומובדל <span data-k=\"pg\">458</span> ּ השגתו מהשגתם באין ערוך ביניהם כלל עד שכאשר<sup data-n=\"7834\">66</sup> שעומק המושג מאתם יחשב לו להשגה אלא כלא חשיב ממש כו' לגבי עצמותו כו' וד\"ל. וזהו לא [נ]ערוך אליו קדושתו<sup data-n=\"7835\">67</sup> פי' קדושתו והבדלתו העצמי אינו בערך א' עם קדושת המקיפים כנ\"ל וד\"ל, ולפי שהי' גילוי העלם הים ליבשה לכך השיגו אז בחי' כי גאה גאה ולא מקדמת דנא כו' וד\"ל.\n<b>סוס</b> ורוכבו רמה בים פי' סוס היינו <sup data-n=\"7836\">68</sup>בחי' אותיות [ש]נק' סוסים וכמ\"ש כי תרכב על סוסיך<sup data-n=\"7837\">69</sup> כו', וביאור הדבר הנה כתיב בחכ' יסד ארץ<sup data-n=\"7838\">70</sup>, ארץ הוא אותיות הדבור שהוא לגבי החכ' שבדבור כמו ערך הדומם העפר לגבי השכל המדבר שהרי [ה]אותיות עצמן אין בהם שום עצמות השכלה רק שבהם ישרה אור השכל כאדם הדר בבית והיכל, כמו שאנו רואים שיוכלו האותיות להפרד להיות בבחי' דומם כגון אותיות הכתב או גם אותיות ה' מוצאות הפה שהן הבל גשמי לבד רק שאור השכל יאיר<sup data-n=\"7839\">71</sup> בהן יובן מתוכם ההשפלה<sup data-n=\"7840\">*72</sup> לזולתו כו', וה\"ז כמשל איש",[["7830","62","<b>וכמ\"ש בזהר</b>: ראה לעיל פ' בא קט, ג הערה 520."],["7831","63","<b>כי אתה הוי' לבדך</b>: ישעי' לז, כ. ב<a class=\"ft-cite\" href=\"#/read/torah-or/3901370280\" data-slug=\"torah-or\" data-id=\"3901370280\">תו\"א כאן (סב, ג</a>): אתה הוא ה' לבדך — נחמי' ט, ו."],["7832","64","<b>ה' מלך גיאות לבש</b>: תהלים צג, א."],["7833","65","<b>ומתחת זרועות [עולם</b>: ראה גם לעיל פ' וארא נה, ד. וש\"נ."],["7834","66","<b>שכאשר</b>: ג: שנאמר."],["7835","67","<b>לא </b>[נ]<b>ערוך אליו קדושתו</b>: פיוט יגדל. ראה מאמרי אדה\"א שמות ח\"ב ע' תקצד. ויקרא ח\"ב ע' תקלג. וש\"נ. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300680345\" data-slug=\"torat-chaim\" data-id=\"2300680345\">תו\"ח מקץ רכא, א</a>."],["7836","68","<b>בחי'</b>: ע\"כ נשמט במאמרי אדה\"ז כאן. ראה לעיל הערה 29."],["7837","69","<b>כי תרכב על סוסיך</b>: חבקוק ג, ח. ראה מאמרי אדה\"א שמות ח\"א ע' קכג. וש\"נ. ש\"א ס, ב ובהערה 38. לקמן קסט, א. קעט, ב. קפב, ד (קצד, א)."],["7838","70","<b>בחכ' יסד ארץ</b>: נסמן להלן הערה 75."],["7839","71","<b>יאיר</b>: במאמרי אדה\"ז כאן (ע' קנו) נדפס: אחר. וצ\"ל כבפנים."],["7840","*72","<b>ההשפלה</b>: אוצ\"ל: ההשפעה."]]],[2300540252,"הרוכב על הסוס שאין ערוך לסוס לגבי האדם הרוכב עליו שמנהיגו ברצונו כו', כמו\"כ השכל עצמו נק' רוכב על האותיות שנקראים סוסים ולכל אשר יפנה השכל יפנו הצירופי אותיות כו', וגם כמו שיש יתרון מעלה בסוס על הרוכב שיוכל להביאו למקום הרחוק שאין ביכולתו לילך ברגליו כידוע, כמ\"כ עד\"מ יש יתרון מעלה באותיות שיוכל[ו] להגביה ולהביא השכל למדריגה הנעלה מה שאין ביכולתו להשיג בעצמו וכנראה בחוש שע\"י הדבור ימצא סיבת תוספת שפע שכל כו' וד\"ל, וכמ\"כ עד\"מ יובן למעלה כי הכל הי' מעפ\"ר<sup data-n=\"7841\">72</sup> העליון אשר בקרקע המשכן אר\"ץ העליונה<sup data-n=\"7842\">73</sup> [ו]אב\"א יסד ברתא<sup data-n=\"7843\">74</sup> כידוע הוא הרוכב על הדבור כמ\"ש ה' בחכמה יסד ארץ<sup data-n=\"7844\">75</sup> הוא בחי' חכ[מ\"ה] שבדבור העליון כו' וזהו כי תרכב על סוסיך כו'. והנה כתי' לא בגבורת הסוס יחפץ ולא<sup data-n=\"7845\">76</sup> בשוקי האיש ירצה כו' כי רוצה ה' את יריאיו<sup data-n=\"7846\">77</sup> כו', פי' כי הנה חכ' שבדבור העליון דיו\"ד מאמרות ויאמר אלקים<sup data-n=\"7847\">78</sup> כו' נק' מים תחתונים אשר מתחת [לרקיע] כו' וחכ' שבתשבע\"פ [ד]מל' קרינן לה<sup data-n=\"7848\">80</sup> הגם שה[י]א ג\"כ בחי' אותיות הדבור לבד אבל הוא ענין מים עליונים אשר מעל לרקיע וכמ\"ש במ\"א בענין יהי רקיע<sup data-n=\"7849\">79</sup> בתוך המים ויבדל כו' ואותיות התורה ג\"כ נק' סוסים לגבי ח\"ע שבהם הרוכב עליהם כי אורייתא מח\"ע נפקת<sup data-n=\"7850\">81</sup> כידוע, אבל כמו שאין ערוך בין חכ' די' מאמרות לחכ' שביו\"ד הדברות<sup data-n=\"7851\">82</sup> מאחר [שח\"ת] זו שבמאמרות נמשכה ממים עליונים ח\"ע דאורייתא כמ\"ש במ\"א, כמו\"כ אין ערוך לאותיות המאמרות לגבי אותיות התורה אעפ\"י ששניהם בחי' דומם לבד, וכמו שידוע שיש דצח\"מ בבחי' אצי'<sup data-n=\"7852\">83</sup> ג\"כ, וכערך השכל עם הדומם בעולם העשי' כן ערך הדומם דאצי' עם השכל דעולם הבריאה כו' שהרי ידוע שתחתית העליון גבוה מעליון שבתחתון<sup data-n=\"7853\">84</sup>, וא\"כ אותיות התורה שהם בחי' דומם דח\"ע הם גבוהים מחכ' שבמאמרות כו' וד\"ל.\n<b>וזהו</b> סו\"ס ורוכב\"ו פי' מה שנשתלשלו וירדו אותיות התורה וחכמתה בירידת המדרגות כ\"כ בים חכ' שבמאמרות מן העלם לגילוי כו' הנה ירידה צורך עלי'<sup data-n=\"7854\">85</sup> הוא שע\"י הקריאה באותיות התורה יגרום גילוי ההעלם כידוע שדבור של [דבר] הלכה הנה הוא מוריד וממשיך הוי' העצמי להיות <span data-k=\"pg\">רכט</span> ּ סובב וממלא כו', והטעם מובן להיות כי חכמה שבמאמר[ות] הנק' ים העליון כנ\"ל היינו סובב שבממלא שהוא כמשל מחשבה הכללית שמקפת",[["7841","72","<b>הכל הי' מעפ\"ר</b>: ע\"פ קהלת ג, כ."],["7842","73","<b>מעפ\"ר העליון אשר בקרקע המשכן אר\"ץ העליונה</b>: ראה גם שה\"א מד, א הערה 2."],["7843","74","<b>[ו]אב\"א יסד ברתא</b>: נסמן לעיל פ' שמות מז, ב."],["7844","75","<b>ה' בחכמה יסד ארץ</b>: משלי ג, יט."],["7845","76","<b>לא בגבורת הסוס יחפץ ולא</b>: תהלים קמז, י [ושם: לא — ראה גם ש\"א עג, א. וש\"נ]."],["7846","77","<b>כי רוצה ה' את יריאיו</b>: שם, שם יא [ותיבת כי ליתא שם. וכן ליתא בג]."],["7847","78","<b>ויאמר אלקים</b>: בראשית א, ג."],["7848","80","<b>שבתשבע\"פ [ד]מל' קרינן לה</b>: ת\"ז בהקדמה (יז, א)."],["7849","79","<b>מים תחתונים. . עליונים. . יהי רקיע</b>: בראשית א, ו. ראה גם מאמרי אדה\"ז תקס\"ב ח\"א ע' רמו ואילך. ע' רנח."],["7850","81","<b>אורייתא מח\"ע נפקת</b>: נסמן לעיל פ' שמות יא, א."],["7851","82","<b>די' מאמרות. . הדברות</b>: ראה גם הנסמן לעיל פ' וארא פא, ג."],["7852","83","<b>שיש דצח\"מ בבחי' אצי'</b>: ראה ע\"ח (שער קיצור אבי\"ע) ש\"נ, פ\"י קרוב לסופו. מאמרי אדה\"א ויקרא ח\"ב ריש ע' תסז. קונטרסים ע' תקלט ובהנסמן בהנ\"ל."],["7853","84","<b>שתחתית העליון גבוה מעליון שבתחתון</b>: ראה ע\"ח (שער כסא הכבוד) שמ\"ו, פ\"ב. פ\"ה. הנסמן במאמרי אדה\"א בראשית ע' לז. לקו\"ב לשעה\"י (קה\"ת תשנ\"ה) ע' קעו."],["7854","85","<b>ירידה צורך עלי'</b>: ראה גם הנסמן באוה\"ת עקב ע' תפא."]]],[2300540283,"המושג מראשו עד רגלו כא' בהשוואה<sup data-n=\"7855\">86</sup> מכל צד כמ\"ש במ\"א בארוכה, וזהו צופה ומביט<sup data-n=\"7856\">87</sup> עד סוף כל הדורות בסקירה א' יודע את כל הנבראים כו' ובידיעה זו הוא מחי' את כולם כא' קטן וגדול בבחי' מקיף כמו ענין תולה ארץ על בלימ\"ה<sup data-n=\"7857\">88</sup> כמבואר במ\"א בענין עגולים ויושר, והנה מחשבה זו הכללית נמשכה מסובב העצמי' שהוא חכ' ש[ב]תורה שקדמה להשתלשלו' דבי\"ע<sup data-n=\"7858\">89</sup> כידוע ע\"כ בקוראו בתורה ממשיך סובב בממלא כו' וא\"כ ירידה זו [ל]צורך עלי[ית] המקבלים הוא וד\"ל. וזהו יש קונה עולמו<sup data-n=\"7859\">90</sup> בשעה א' פי' יש הם ש\"י עולמות כמ\"ש להנחיל אוהבי יש<sup data-n=\"7860\">91</sup> והוא הנאות העונג אלקי בג\"ע העליון ותחתון כידוע והוא יש ודבר מה לגבי ימא עילאה מחשבה הכללית תכלית הביטול מה שבחכמה כנ\"ל ובמס\"נ יש קונה עולמו עולמות<sup data-n=\"7861\">92</sup> שנתפשט מגדר הגבלה ונכלל במקור העליון בחי' ים עליון מחשבה הכללית והוא ענין שעה א' שהרי המח' הכללית מחשבה א' הוא לבד כנז' בזהר<sup data-n=\"7862\">93</sup> כמשל החושב ומצייר איזה דבר במחשבתו שנתפסת מראשו לרגלו ברגע א', משא\"כ אח\"כ כשמתחלק' המח' באופנים הפרטים יש רבות מחשבות<sup data-n=\"7863\">94</sup> כו' וכמ\"ש במ\"א, וזהו שע\"ה א' תנועה א' כמו וישע ה' אל הבל<sup data-n=\"7864\">95</sup> כו' וד\"ל.\n<b>ואמנם</b> לא בגבורת הסוס יחפץ כי האומר אין לי אלא תורה<sup data-n=\"7865\">96</sup> אפי' תורה אין לו, פי' כי הגם שזאת יתרון מעלת הסוס על הרוכב שיוכל להביא[ו] למקום שאי[נו] ביכולת הרוכב להגיע מצד עצמו, וכמ\"כ אותיות התורה מרמזי'<sup data-n=\"7866\">97</sup> הח\"ע שבהם עד שיוכלו להביא ולהמשיך מלמעלה למטה שפע חכ' עילאה בתוס' מרובה על הקדו[ם] כו' עכ\"ז לא חפץ ה' בגבורת הסו\"ס מטעם תורה שהיא לבד[ה] בלא יראה אפי' תורה אין לו. וביאור שרש<sup data-n=\"7867\">98</sup> הדבר היינו לפי שבאמת גם מ\"ה שבחכ[מ\"ה] שנא' במשה ונחנו מ\"ה כלא חשיבי לגבי עצמות המאציל שהוא חכי\"ם ולא בחכ[מ\"ה] ידיע\"א<sup data-n=\"7868\">99</sup> כלל דהיינו ח\"ס דא\"א כידוע, וא\"כ המשכת מ\"ה שהוא ג\"ר דאבא בעתיקא תליא שהוא חפ\"ץ ורצון ה' שהחפ\"ץ הוא בחי' עתיק והרצון בחי' א\"א<sup data-n=\"7869\">100</sup> כידוע, וזהו בגבורת הסו\"ס מה דממשיך בגבורתו תוס' המשכת מ\"ה שבחכמה שנמשכה מסוף מדרגת החכ' בחי' נה\"י דאבא שמהם שרש כל<sup data-n=\"7870\">101</sup> המשכה הנק' מחשבת שכל כמ\"ש במ\"א והמה המנהיגים האותיות הנק' סו\"ס כו' וד\"ל. וא'<sup data-n=\"7871\">102</sup> רוצה ה' את יריאיו כו' פי' ענין היראה היא התפעלות הנפש מעצמות המאציל דכולא קמי'",[["7855","86","<b>מחשבה הכללית. . בהשוואה</b>: ראה גם מאמרי אדה\"ז תקס\"ב ח\"א ע' רמו. מאמרי אדה\"א בראשית ס\"ע רנט. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300670238\" data-slug=\"torat-chaim\" data-id=\"2300670238\">תו\"ח וירא ק, ב</a>."],["7856","87","<b>צופה ומביט</b>: נסמן לעיל מח, ב."],["7857","88","<b>תולה ארץ על בלימ\"ה</b>: איוב כו, ז. ראה ד\"ה זה במאמרי אדה\"ז תקס\"ב ח\"ב ע' תעה ואילך."],["7858","89","<b>דבי\"ע</b>: ג: אבי\"ע."],["7859","90","<b>יש קונה עולמו</b>: ע\"ז י, ב."],["7860","91","<b>להנחיל אוהבי יש</b>: משלי ח, כא. סוף עוקצי'."],["7861","92","<b>מחשבה הכללית. . עולמות </b>[ב: עולמית]: ג: ליתא."],["7862","93","<b>מחשבה א'. . בזהר</b>: ראה זהר שמות כ, א. הנסמן במאמרי אדה\"א קונטרסים ע' תלא."],["7863","94","<b><a class=\"ft-cite\" href=\"#/read/torah-or/3901370455\" data-slug=\"torah-or\" data-id=\"3901370455\">מחשבה א</a>'. . רבות מחשבות</b>: ראה גם תו\"א ויחי קג, א. מאמרי אדה\"ז תקס\"ב ח\"א ע' י. מאמרי אדה\"א בראשית ע' תצד. הנחות תקע\"ז ע' רפג."],["7864","95","<b>וישע ה' אל הבל</b>: בראשית ד, ד וברש\"י שם."],["7865","96","<b>האומר אין לי אלא תורה</b>: ראה יבמות קט, ב."],["7866","97","<b>מרמזי'</b>: ג: מרוממי'."],["7867","98","<b>שרש</b>: ג: ליתא."],["7868","99","<b>חכי\"ם. . ידיע\"א</b>: ז\"ח יתרו לד, ב. ת\"ז בהקדמה (יז, ב)."],["7869","100","<b>שהחפ\"ץ. . עתיק והרצון בחי' א\"א</b>: ראה גם מאמרי אדה\"א ויקרא ח\"א ע' רטז."],["7870","101","<b>כל</b>: ג: כח."],["7871","102","<b>וא'</b>: ג: אלא."]]],[2300540311,"כלא<sup data-n=\"7872\">103</sup> חשיבי בשמים ממע\"ל ועל הארץ מתחת שהם מקיפי' ופנימי' דהוי' אלקים שניהם שוים ממש כו', וא\"כ התקשרות הנפש במקורה דכולא<sup data-n=\"7873\">104</sup> קמי'<sup data-n=\"7874\">105</sup> היא יכולה להמשיך דוקא חפץ ורצון ה' שיומשך גם מ\"ה שבחכ[מ\"ה] לפי שהתקשרות[\"ם] היינו בעצמות המאציל וזהו רוצה את יריאי\"ו דוקא וד\"ל. ועיקר הטעם שלא יחפוץ בגבורת הסוס היינו לפי שאין עצמות אוא\"ס שורה כ\"א בדבר שהוא בתכלית הביטול במציאות כידוע, וא\"כ הסוסים שהן אותיות התורה [כ]שהן בלא יראה הגם שכחם רב כנ\"ל הרי גבורתם העצמי הוא ואין זה בחי' הביטול האמיתי, שהרי באמת שקר הסוס לתשועה<sup data-n=\"7875\">106</sup> כו' כי הוא דוקא יהיב חכמת\"א לחכימין<sup data-n=\"7876\">107</sup> כו', ולמי נותן למי שמשים עצמו כשיריים<sup data-n=\"7877\">108</sup> שאין בו ענין גבורת חכ' מצד עצמו ואינו אומר אין לי אלא תורה כו' והיינו המייחלי\"ם לחסדו <span data-k=\"pg\">460</span> ּ פי' שמצפים על מה שיתנו להם חכמה מלמעלה מח\"ע<sup data-n=\"7878\">109</sup> דחפץ ה' הנק' חסד דע\"י כידוע כי אין להם מצד עצמם כלל כו' וד\"ל. וזהו סוס ורוכבו דהיינו ענין גבורתו רמה בים השפילו שלא יהי' לו כח מצד עצמו כלום כנ\"ל דהלא<sup data-n=\"7879\">110</sup> הי' כ\"א בעת גילוי ענין גא\"ה גא\"ה דוקא להיות[ו] בחי' העצמות כנ\"ל וד\"ל.\n<b>ועתה</b> יובן ענין חזרת בנ\"י כמ\"ש וישובו<sup data-n=\"7880\">111</sup> כו' למען ידעו מצרי\"ם כו' והגם שלא נותר מהם כלום כי הנה כתיב [המים הי' להם חומה מימינם ומשמאלם<sup data-n=\"7881\">112</sup> כו'] ובנ\"י הלכו ביבשה<sup data-n=\"7882\">113</sup> בתוך הים כו', ויש להבין תחלה למה הזכיר שהי' המים להם חומ\"ה מאליו מובן שהי' כן כו', אך הענין הוא דמים עליונים דאורייתא מח\"ע נפקת [היא] כלולה מחו\"ג רמ\"ח מ\"ע ושס\"ה ל\"ת, המ\"ע נמשכים מחסדים שבח\"ע ושס\"ה ל\"ת נמשכו מבחי' גבורות שבח\"ע כו' כידוע שהוא ענין שמאל דוחה<sup data-n=\"7883\">114</sup> וימין מקרבת, פי' יש ימין בחכמה שהוא הארת השכל לזכות ולקרב כו' ויש שכל בחכמה להרחיק ולדחות כמו לא תאכל חלב ודם<sup data-n=\"7884\">115</sup> וכדומה כו' ולהיות כי מים עליונים אלו יש אותיות<sup data-n=\"7885\">116</sup> המקור למים תחתונים הנק' י\"ם כנ\"ל להיותם<sup data-n=\"7886\">117</sup> בבחי' חפ\"ץ ורצון ה' הנק' [ע\"י וא\"א] כידוע, ע\"פ<sup data-n=\"7887\">118</sup> ישראל דוקא ועלו<sup data-n=\"7888\">119</sup> במחשבה<sup data-n=\"7889\">120</sup> דא\"א וגם מפני שהיו עתידים לקיים התורה במ\"ע ול\"ת מן ההעלם לגילוי נהפך להם הי\"ם ליבשה כמ\"ש ובנ\"י הלכו ביבשה בתוך הים, והטעם מובן להיות כי מחכמה ואילך מתחיל [ענין] ההשתלשלו'<sup data-n=\"7890\">121</sup> מעילה לעילה גם בבחי' אצי' כידוע ואפי' החכמה",[["7872","103","<b>דכולא קמי' כלא</b>: נסמן לעיל פ' שמות לח, א."],["7873","104","<b>במקורה דכולא</b>: זהר בראשית לג, א."],["7874","105","<b>קמי'</b>: ג: ליתא."],["7875","106","<b>שקר הסוס לתשועה</b>: תהלים לג, יז."],["7876","107","<b>יהיב חכמת\"א לחכימין</b>: דניאל לב, כא."],["7877","108","<b>למי שמשים עצמו כשיריים</b>: ר\"ה יז, ריש ע\"ב."],["7878","109","<b>מח\"ע</b>: ג: מחסד עליון."],["7879","110","<b>דהלא</b>: ג: וזה לא."],["7880","111","<b>וישובו</b>: בשלח יד, ב."],["7881","112","<b>המים הי' להם חומה מימינם ומשמאלם</b>: בשלח יד, כב. כט [ושם: והמים להם]."],["7882","113","<b>ובנ\"י הלכו ביבשה</b>: בשלח יד, כט."],["7883","114","<b>שמאל דוחה</b>: סוטה מז, א."],["7884","115","<b>לא תאכל חלב ודם</b>: ראה ויקרא ג, יז."],["7885","116","<b>יש אותיות</b>: ג: הם אמיתי'."],["7886","117","<b>להיותם</b>: ג: להוותם."],["7887","118","<b>ע\"פ</b>: ג: ע\"כ."],["7888","119","<b>ועלו</b>: ג: שעלו."],["7889","120","<b>ישראל. . שעלו במחשבה</b>: נסמן לעיל פ' שמות לב, ב."],["7890","121","<b>מחכמה. . ההשתלשלו'</b>: ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381236\" data-slug=\"likkutei-torah\" data-id=\"4001381236\">לקו\"ת שה\"ש כו, ד</a> (ד\"ה ביאור הדברים). וש\"נ [ושם: וכ\"כ הרמ\"ז פ' ואתחנן בדף רס\"ו. וכנצ\"ל: רסה, ב (קצד, סע\"ב בדפי הספר)]."]]],[2300540336,"שבקוין שהוא ענין הגילוי שבחכ' יש ראש תוך סוף<sup data-n=\"7891\">122</sup>, והרוחניות למעלה מן הגשמיות והאור גבוה מן החשך וכדומה כו', אבל למעלה מחכ' הגלוי' בקוין כו' דהיינו בחכמה עילאה שבעצמות המאציל<sup data-n=\"7892\">123</sup> שהוא חכ' דאוריי' מ\"ע ומל\"ת כנ\"ל <sup data-n=\"7893\">124</sup>שהוא שם המעלה עם המטה רוחניות וגשמיות כחשיכה כאורה כו' כי הוא הגבה למעלה מסדר ענין השתלשלו' מבלי שימצא ראש תוך סוף כלל כנ\"ל. וזהו שמפרש הטעם הזה אח\"כ והמים [הי'] להם חומ\"ה, פי' למה הלכו ביבש\"ה בתוך הים העליונ[י'] ונהפך המעלה למטה כו' לפי שהמי\"ם עליונים דאורייתא הוא להם חומה בבחי' חפץ ורצון ה' שהוא בחי' א\"א וע\"י שנק' חומה ע\"ש הגבה המופלג והגבה החזקה וכמ\"ש בזהר ע\"פ [ו]אני אהי' לה חומת אש<sup data-n=\"7894\">126</sup> כו' שהוא מקור כל המקיפים<sup data-n=\"7895\">125</sup> <sup data-n=\"7896\">127</sup>כו' מימינ[ם] ומשמאל[ם] חו\"ג דרמ\"ח מ\"ע ושס\"ה ל\"ת כנ\"ל וד\"ל. אבל מצרים שרדפו אחריהם בים לא עמדו להם המים עליונים מימינם ומשמאלם מטעם שלא ניתנה תורה להם וגם בשרשם אינם בבחי' העצמ[י]ות כ\"א בבחי' אחוריים דא\"א [ו]נק' מצרי\"ם מצר י\"ם<sup data-n=\"7897\">128</sup> בחי' עורף<sup data-n=\"7898\">129</sup> כו' וכמ\"ש במ\"א, ע\"כ נטבעו בים כי לא יוכלו לקבל יניקה ממקום הנעלה [כ]זה מבחי' גאה גאה מקור כל המקיפים כנ\"ל וד\"ל.\n<b>אמנם</b> יש להבין לאיזה טעם הוחזרו כנס\"י כדי שיטבעו מצרים בי\"ם ולא יקבל יניקה א\"כ מהיכן ידעו מצרים כנ\"ל. והענין הוא דמסיים הפסוק הפך ים ליבשה כו' עיניו בגוים תצפינה<sup data-n=\"7899\">130</sup> הסוררים אל ירומו סלה, פי' אל ירומ\"ו לא יוכלו לקבל יניקה מרום הרוממות גאה גאה כו', כי הגם שאדרבה בבחי' עצמות ההתנשאות דמקיף ופנימי שניהם שוים כנ\"ל וכחשיכה כאורה כו' א\"כ גם החשך שרש המצרים יכול לקבל שפע כמו האור מפני העדר תפיסת מקום כו', ולזה אמר הסוררים אל ירומ\"ו לפי שגם ברום הרוממות נבדלו ונפרדו כו' וד\"ל. <span data-k=\"pg\">רל</span> ּ וזהו וידעו מצרי\"ם כי אני הוי'<sup data-n=\"7900\">131</sup> פי' [ב]טביעה זו שנטבעו בים בשעה שהי' התגלות רום הרוממות וגאה גא\"ה ולא יוכלו לקבל השפע אז דוקא ידעו מצרים כי אני הוי' ולא מקדמת דנא. והטעם מובן עפ\"י הנ\"ל שהרי קליפת מצרים בעודנה חיים",[["7891","122","<b>שבחכ' יש ראש תוך סוף</b>: ראה גם שעה\"י קל, ב ובהערה 13."],["7892","123","<b>המאציל</b>: ג: ליתא."],["7893","124","<b>שהוא</b>: ג: שוה."],["7894","126","<b>[ו]אני אהי' לה חומת אש</b>: זכרי' ב, ט [בדילוג]. ראה גם זהר אחרי סח, ב."],["7895","125","<b>חומה. . מקור כל המקיפים</b>: ראה גם מאו\"א מערכת חומה סט\"ז."],["7896","127","<b>כו'</b>: ג: ליתא."],["7897","128","<b>מצרי\"ם מצר י\"ם</b>: נסמן לעיל פ' שמות לז, ב."],["7898","129","<b>מצרי\"ם. . עורף</b>: ראה לעיל פ' שמות יט, ב ובהערה 796."],["7899","130","<b>עיניו בגוים תצפינה</b>: תהלים סו, ז [בדילוג]."],["7900","131","<b>וידעו מצרי\"ם כי אני הוי'</b>: בשלח יד, ד. יח. וראה לעיל הערה 5."]]],[2300540359,"וקיימים יש להם שרש דשרש עד בחי' אחוריים דא\"א כו', וסיבת שפע קיומם מאין ליש הוא מחמת רוב טוב חסדו העצמי שמאריך אף גם לרשעים<sup data-n=\"7901\">132</sup> כחשיכה כאורה כו' א\"כ לא ידעו את ה', אמנם בא[י]בוד רשעים בים בשעת גילוי העצמות ולא יכלו לקבל היניקה אז הבינו<sup data-n=\"7902\">133</sup> שהכל תלוי בעצמות א\"ס ב\"ה גם חפצו ורצונו כו' וכענין יהי רצון כו' מבעל הרצון, וא\"כ יכול להבדילם גם בבחי' העצמ[י]ות ולא ישתווה חשך לאור כו' ויתפרדו כל<sup data-n=\"7903\">134</sup> כו' הגם שהיו יכולים לקבל מצד שרשם כו' אבל לא חפץ בהם וד\"ל (כי<sup data-n=\"7904\">135</sup> אני ה' בחי' פנימי' החפץ והרצון והוא רצונו הפשוט כידוע ולא חיצוניות הרצון שבעורף המאיר להם וד\"ל).",[["7901","132","<b>שמאריך אף גם לרשעים</b>: נסמן לעיל פ' שמות לא, א."],["7902","133","<b>הבינו</b>: בג: הכירו."],["7903","134","<b>ויתפרדו כל</b>: תהלים צב, י."],["7904","135","<b>כי</b>: ג: פי'."]]],[2300540071,"<b>בעזר\"ה פ' בשלח ה'תקפ\"ה</b>\n<span data-k=\"pg\">462</span> ּ<b>אשירה</b> לה'<sup data-n=\"7905\">1</sup> כי גאה גאה סוס ורוכבו רמה בים<sup data-n=\"7906\">2</sup>, עזי וזמרת י\"ה כו' זה אלי ואנוהו<sup data-n=\"7907\">3</sup> כו', הנה ידוע ששרש ענין ירידת הנשמה האלקי' ממקור חוצבה למטה בעוה\"ז בחומר גופני אע\"פ שזהו בחי' ירידה גדולה אמנם ירידה זו לצורך עלי'<sup data-n=\"7908\">4</sup> הוא שעי\"ז תתעלה למעלה במדרגה מכמו שהיתה במקור חוצבה, וזה פלא גדול לכאורה דאיך תעלה למדרגה גבוה כזו ע\"י התלבשותה בלבוש גשמי בנפש הטבעי' החומריות כו', ולא עוד אלא שבירידתה בעוה\"ז נק' הנשמה בחי' מהלך שיכולה לילך בעילוי המדריגות בלי שיעור למעלה מעלה, ובהיותה למעלה כלולה במקור חוצבה נק' הנשמה עומד<sup data-n=\"7909\">5</sup> כמו המלאכי' שנק' עומדים כמו ונתתי לך מהלכים<sup data-n=\"7910\">6</sup> בין העומדים האלה כו' וכמ\"ש בזהר שנק' עצי שטים עומדים<sup data-n=\"7911\">7</sup> לפי שעומדי' במדרגה א' לא יוסיף ולא יגרע כו'<sup data-n=\"7912\">8</sup> כ[מו] מיכאל וגבריאל שעומדי' מוימ\"ב<sup data-n=\"7913\">9</sup> במדרגה א', כך גם הנשמות הצרורו' בצרור החיים למעלה במקור חוצבם במל' דאצי'<sup data-n=\"7914\">10</sup> נק' עומדי' כמו אליהו שא' חי ה'<sup data-n=\"7915\">11</sup> אשר עמדתי לפניו דר\"ל שעמד בכח<sup data-n=\"7916\">12</sup> בהיות נשמתו היתה<sup data-n=\"7917\">13</sup> דבוקה וקשורה למעלה את ה' כו' שז\"ש אשר עמדתי לפניו ממש, וכן א' בזהר דכל נשמתא הוה קיימא<sup data-n=\"7918\">14</sup> קמי' מלכא קדישא",[["7905","1","<b>אשירה לה'</b>: מיוסד על ד\"ה זה משנת תקס\"ו שנדפס ב<a class=\"ft-cite\" href=\"#/read/torah-or/3901370281\" data-slug=\"torah-or\" data-id=\"3901370281\">תו\"א בשלח סב, ד</a> [והוא הנחת המהרי\"ל — והגהות וכו' נדפסו באוה\"ת בשלח ע' תקט-תקכב]. מאמרי אדה\"א שמות ח\"א ע' קח. ומלהלן קסט, ג ראה גם ד\"ה עזי וזמרת י\"ה נדפס במאמרי אדה\"א הנחות תקע\"ז ע' נח. וראה עוד ע\"ד המאמר להלן ברשימת הכת\"י [ושם מפורט ג\"כ סימני האותיות הבאים להלן בהמראי מקומות]."],["7906","2","<b>אשירה. . רמה בים</b>: בשלח טו, א."],["7907","3","<b>עזי וזמרת. . ואנוהו</b>: בשלח שם, ב."],["7908","4","<b>ירידה זו לצורך עלי'</b>: ראה הנסמן באוה\"ת עקב ע' תפא."],["7909","5","<b>הנשמה עומד</b>: ראה מאמרי אדה\"ז תקע\"א ע' ו. ע' י. ע' יג. ע' כ. שע\"ת כ, ג ובהערה 31."],["7910","6","<b>ונתתי לך מהלכים</b>: זכרי' ג, ז. ראה מאמרי אדה\"ז שבהערה שלפנ\"ז. מאמרי אדה\"א ויקרא ח\"ב ע' תרסז. וש\"נ. ש\"א ח, ב ובהערה 42. לקמן פ' פקודי תנז, א."],["7911","7","<b>עצי שטים עומדים</b>: נסמן לעיל פ' בא קיט, ד."],["7912","8","<b>לא יוסיף ולא יגרע כו'</b>: א: ליתא. בו: כבפנים."],["7913","9","<b>מיכאל וגבריאל. . מוימ\"ב</b>: ראה ב\"ר פ\"א, ג. פ\"ג, ח. תנחומא — באבער — בראשית בתחלתו. וש\"נ. רש\"י איוב ט, ח."],["7914","10","<b>הנשמות. . במל' דאצי'</b>: ראה לעיל פ' וארא סז, א ובהערה 351."],["7915","11","<b>אליהו שא' חי ה'</b>: מל\"א יז, א־ יח, טו [בדילוג]. ראה הנסמן במאמרי אדה\"ז על פרשיות התורה ח\"ב לע' תשכט. שה\"א צח, ב ובהערה 14."],["7916","12","<b>בכח</b>: או: כבר."],["7917","13","<b>היתה</b>: א: ליתא."],["7918","14","<b>דכל נשמתא הוה קיימא</b>: בסה\"מ תרנ\"ד ע' רסג מציין: בזח\"א דרל\"ג ע\"ב. וראה סה\"מ תש\"ח ע' 182 הערה ה. וראה מאמרי אדה\"א דברים ח\"ד ס\"ע א'רפא ואילך."]]],[2300540109,"כו' (והיינו באוצר הנשמות ששמו גוף<sup data-n=\"7919\">15</sup> כמארז\"ל אין ב\"ד בא<sup data-n=\"7920\">16</sup> עד שיכלו הנשמות מן האוצר כו' כמ\"ש במ\"א). ובאמת יש להבין בזה דלמה נק' המלאך או הנשמה בהיותם למעלה בבחי' עומדים במדריגה א' תמיד אחר שעבודתם שם הוא בבחי' אוי\"ר שנק' רו\"ש כמ\"ש והחיות רו\"ש<sup data-n=\"7921\">17</sup> כמראה הבזק ופרש\"י כמו להב היוצא מן החרסית שיוצא וחוזר ונכנס כו', ובחי' רו\"ש נק' עלי' והילוך למעלה וכידוע ביאור הענין דבחי' הרצוא זהו תגבורת כוסף התשוקה באה\"ר לצאת מן הכלי והחומר לידבק וליכלל במקור חוצבו באלקים חיים כניצוץ הנמשך ועולה ונכלל בשלהבת וזהו כלהב היוצא כו', וכמו גם בנשמת האדם בגופו שבצ\"ג תכלה הנפש ותכסוף לצאת מנרתקה בגוף ליכלל באחד כו' כמו נכספה וגם כלתה נפשי<sup data-n=\"7922\">18</sup> כו' וכן צמאה לך נפשי<sup data-n=\"7923\">19</sup> כמה לך בשרי, כלה שארי ולבבי<sup data-n=\"7924\">20</sup> כו' וכה\"ג. וכך המלאכים באמרם שירה תכסוף נפשם לצאת מכלי חומרם ליכלל במקורם כמ\"ש והחיות רצוא כו' ומיד חוזר רוחם ונפשם אל חומרם כלהב היוצא וחוזר ונכנס וזהו ושוב, בחי' זה זהו מחמת בחי' היראה ופחד אלקי' כשבאי' מקרוב בבחי' רצוא כנ\"ל אזי חוזרי' ונסוגי' אחור מצד ביטול העצמו' מכל וכל שמתבטלים ממציאותם לגמרי ויראו לגשת ולהתקרב עוד ע\"כ נסוגי' אחור כו' כענין שהי' במ\"ת דכתי' וירא העם וינועו<sup data-n=\"7925\">21</sup> ויעמדו מרחוק כו', וז\"ש בס\"י אם רץ לבך שוב<sup data-n=\"7926\">22</sup> כו' כמ\"ש ביאורו במ\"א<sup data-n=\"7927\">23</sup>, וע\"י בחי' רו\"ש זה המה הולכי' ועולי' כמו בשתים<sup data-n=\"7928\">24</sup> יעופף<sup data-n=\"7929\">25</sup> כידוע<sup data-n=\"7930\">26</sup>. אך הרי אנו מוצאי' במלאכי' שא' בעמדם תרפינה כנפיהם<sup data-n=\"7931\">27</sup> היינו שנתבטלו לגמרי ונשארו עומדי' כמו אבן דומם דגם בחי' רו\"ש שלהם נתבטל כמ\"ש תרפינה כנפיהם דהיינו בחי' רו\"ש שבכנפיהם כמ\"ש בשתים יעופף, כאוי\"ר שבנשמ' בגופו שעי\"ז יהי' עולה במדרג' כמו השט במים וכעוף הפורח בכנפיו למעלה וכמו הבא מקרוב ממש לפני המלך שמתבטל לגמרי משא\"כ מרחוק מעט יש לו תשוקה להתקרב ונסוג אחור וחוזר ומתקרב כו', וזהו בחי' רו\"ש דמלאכי' מרחוק, אבל מקרוב ממש תרפינה כנפיהם <span data-k=\"pg\">רלא</span> ּ וכן בעמידה דש\"ע כידוע בענין אד' שפתי תפתח כו' דאין מלה בלשוני<sup data-n=\"7932\">28</sup> כו', ולזאת הגם שהי' לנשמ' האלקי בהיותה במקור חוצבה בחי' אוי\"ר אמיתי' בבחי' רו\"ש כמלאכים עכ\"ז לא נקרא מהלך אלא עומד כמ\"ש אשר עמדתי לפניו כו' לפי שלא יוכלו לילך במדרגות ברו\"ש באוי\"ר רק כפי שרשם באלקים חיים",[["7919","15","<b>באוצר הנשמות ששמו גוף</b>: נסמן לעיל פ' וארא סז, א."],["7920","16","<b>אין ב\"ד בא</b>: נסמן לעיל קלג, ד."],["7921","17","<b>והחיות רצו\"ש</b>: יחזקאל יד, א (וברש\"י שם). ראה חגיגה יג, ב וברש\"י שם. וראה גם <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300670436\" data-slug=\"torat-chaim\" data-id=\"2300670436\">תו\"ח בראשית כו, ג</a>. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300670494\" data-slug=\"torat-chaim\" data-id=\"2300670494\">ש\"א פט, ב</a>. מאמרי אדה\"א קונטרסים ס\"ע תלט ואילך. לעיל פ' וארא סג, ג ואילך."],["7922","18","<b>נכספה וגם כלתה נפשי</b>: תהלים פד, ג."],["7923","19","<b>צמאה לך נפשי</b>: תהלים סג, ב."],["7924","20","<b>כלה שארי ולבבי</b>: תהלים עג, כו."],["7925","21","<b>וירא העם וינועו</b>: יתרו כ, טו. ראה מאמרי אדה\"א בראשית ע' תקד וע' תקמד. קונטרסים ע' רפב. שע\"ת לד, א ואילך. לקמן פ' תרומה שו, ג. ויקהל תח, ג."],["7926","22","<b>אם רץ לבך שוב</b>: ראה ס\"י פ\"א, מ\"ח. ת\"ז בהקדמה (ז, א). אוה\"ת יתרו ע' תתקעח וע' תתקפא. הערה בסה\"מ תרנ\"ט ע' ריא."],["7927","23","<b>אם רץ. . במ\"א</b>: ראה גם מאמרי אדה\"ז תקס\"ה ח\"ב ע' תרל. <a class=\"ft-cite\" href=\"#/read/torah-or/3901370327\" data-slug=\"torah-or\" data-id=\"3901370327\">תו\"א יתרו עג, ד</a>. מאמרי אדה\"א במדבר ח\"ב ס\"ע תרצט ואילך. ש\"א פח, ב ואילך. שע\"ת לג, א ואילך. לקמן פ' ויקהל שפט, ג."],["7928","24","<b>בשתים</b>: אב: ובשתים — ראה הערה הבאה. אמנם בסמוך בפנים שו\"ה שבכנפיהם מובא גם בהנ\"ל: בשתים."],["7929","25","<b>בשתים יעופף</b>: ישעי' ו, ב [ושם ובשתים — ראה הערה שלפנ\"ז. וכ\"ה לעיל פ' שמות כח, א. הלשון שבפנים — ראה גם <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300191526\" data-slug=\"likkutei-sichot\" data-id=\"1300191526\">לקו\"ש תצא (כרך יט) ס\"ע 513</a>. מאמרי אדה\"א בראשית ע' קנד. וש\"נ. שמות ח\"ב ע' תקצב]."],["7930","26","<b>כידוע</b>: אב: כו'."],["7931","27","<b>בעמדם תרפינה כנפיהם</b>: יחזקאל א, כד. כה. ראה גם לעיל פ' בא קיח, ד. וש\"נ."],["7932","28","<b>אד' שפתי. . דאין מלה בלשוני</b>: תהלים נא, יז. קלט, ד. נסמן לעיל פ' שמות מז, ג הערה 172."]]],[2300540147,"ולא יעלו למעלה יותר, כי בהגיעם מקרוב יתבטלו לגמרי כנ\"ל וגם בשעה שעולה בבחי' הרצוא מיד חוזר ושב למטה כו' וד\"ל.\n<b>אך</b> הנה בירידת הנשמה בעוה\"ז בחומר הגוף הוא שתוכל להיות בבחי' מהלך דוקא שתוכל לעלות ולילך בלי שיעור למעלה והוא גם מה שאחרי הסתלקותם מעוה\"ז למעלה בג\"ע נאמר ילכו מחיל אל חיל<sup data-n=\"7933\">29</sup> כו' (וכמ\"ש במ\"א על ענין מא' דהאי עלמא דאזלינ[ן] מיני'<sup data-n=\"7934\">30</sup> כו'), ומה שגם קודם ירידת הנשמה בעוה\"ז יש להם הילוך ועלי' כמו מגעה\"ת לגעה\"ע ולמעלה יותר כענין מיכאל מקריב נשמות<sup data-n=\"7935\">31</sup> כו' זהו ע\"י התו\"מ שעשו בעוה\"ז דוקא (כמשי\"ת). וזהו פלא גדול דודאי אין ערך כלל לאוי\"ר דנשמה בהיותה בגוף חומרי שנולד מתאות אב ואם כמ\"ש ובחטא יחמתני אמי<sup data-n=\"7936\">32</sup> כו' הגם שיעבוד עבודה תמה כמו במס\"נ באה\"ר בתענוגי' כצ\"ג כמשה ואבות אין זה רק ע\"י התלבשות הגשמיות דנה\"ט שאין לה ערך לאוי\"ר דנשמה מצד עצמה בהיותה צרורה בצרור החיים את ה' ממש לא מיני' ולא מקצתי'<sup data-n=\"7937\">33</sup>, וגם אוי\"ר האלקי' דנשמה ודאי תחשך אורה הרבה בירידתה למטה בלבוש הגס דנה\"ט במוח ולב גשמי המעורב טו\"ר כו' שמחשיך ומסתיר אור האלקי שבנשמה גם בנשמות הצדיקים הגדולי' כמשה ואברהם שהיו בחי' מרכבה תמידי'<sup data-n=\"7938\">34</sup> כמו שהיו קודם בואם לעוה\"ז כו', וכ\"ש בנשמות שלמטה ממדרגתם שהתפעלותם באה\"ר ודביקות אמיתי' רק לפרקים כמו בק\"ש ותפלה שחרית ולא כל היום שהן בבחי' קטנות המוחי' כו', וכ\"ש בנשמות הבינוני' שנופלים לפרקים למטה בחומריות הגוף לגמרי כו' וא\"כ ודאי זהו ירידה גדולה לנשמה כמו הנפילה מאיגרא רמה לבירא עמיקתא<sup data-n=\"7939\">35</sup> כו' (יותר מיריד' הנשמה דאדה\"ר דכתי' בה ויפח באפיו נ\"ח<sup data-n=\"7940\">36</sup> כו' שהי' גופו טהור וקדוש מתחלת הווייתו להיות חומר לצורה זו כו'), ואיך יוכל להיות להיפך שיהי' עליי' הנשמה ע\"י עבודה זו דאוי\"ר שלה בגוף [ל]מדרגה גבוה יותר משרשה הראשון ומה גם שתקרא בשם מהלך בעילוי עד אין שיעור בכל נשמה לפי ערכה וגם בנשמות משה ואהרן<sup data-n=\"7941\">37</sup> כו'.\n<b>אך</b> הענין הוא כידוע בשרש ההשתלשלו' בכלל שנמשך ע\"י צמצום הראשון בבחי' קו\"ח כו' שהוא מקור הראשון לכל אורות דע\"ס דאצי' ובחי' הגבלת הכלים בב' אופנים בפנימיות",[["7933","29","<b>ילכו מחיל אל חיל</b>: נסמן לעיל פ' שמות ד, ג."],["7934","30","<b>דהאי עלמא דאזלינ[ן] מיני'</b>: כ\"ה בכ\"מ בדא\"ח. ראה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300191526\" data-slug=\"likkutei-sichot\" data-id=\"1300191526\">לקו\"ש תצא כרך יט ס\"ע 513</a> [נדפסה גם באג\"ק שלו ח\"א ע' רצז] שמציין לערובין נד, א. מאמרי אדה\"ז תקס\"ד ע' קד. מאמרי אדה\"א ויקרא ח\"ב ע' תרפב ואילך."],["7935","31","<b>מיכאל מקריב נשמות</b>: נסמן לעיל פ' שמות ה, א."],["7936","32","<b>ובחטא יחמתני אמי</b>: תהלים נא, ז."],["7937","33","<b>לא מיני' ולא מקצתי'</b>: ע\"פ סוטה ה, א."],["7938","34","<b>ואברהם. . מרכבה תמידי'</b>: נסמן לעיל פ' שמות ה, ג."],["7939","35","<b>מאיגרא רמה לבירא עמיקתא</b>: נסמן לעיל פ' שמות ד, ג."],["7940","36","<b>ויפח באפיו נ\"ח</b>: בראשית ב, ז."],["7941","37","<b>ואהרן</b>: או: ואבות."]]],[2300540184,"וחיצוניות, דהיינו כמו ביחוד עליון הפנימי דאו\"א וזו\"נ שהוא שרש הנשמות דאצי' עד נפש דעשי' ובחיצוניות בכלים החיצוני' דע\"ס דאצי' שנמשך לבי\"ע שמשם שרש המלאכי' כמו בחי' הדיבור החיצוני די\"מ כו', ובין בפנימי' ובין בחיצוני' הכל נמשך מבחי' הקו\"ח שנק' קו המדה<sup data-n=\"7942\">38</sup> בכלל למדוד כל אור ושפע באו\"פ ואו\"מ וכלים מכלים שונים הכל במדה ושיעור דוקא לא יוסיף ולא יגרע לעולם כמ\"ש מי מדד בשעלו<sup data-n=\"7943\">39</sup> כו' ונק' משחתא<sup data-n=\"7944\">40</sup> או מתקלא<sup data-n=\"7945\">41</sup> כו' כמ\"ש במ\"א בענין אי\"ה סופ\"ר אי\"ה שוקל<sup data-n=\"7946\">42</sup> כו'. ומטעם זה נק' נשמות ומלאכים ד[א]בי\"ע בשם עומדי' דוקא כנ\"ל שלא יהי' בהן תוס' וגרעון לעולם רק כפי מקור חוצבם בחו\"ב <span data-k=\"pg\">464</span> ּ ומדות דאצי' ממקורם הראשון דבחי' קו\"ח הנ\"ל, אך בהגיע נשמות דאצי' בגופים למטה בעוה\"ז דוקא ומקיימים התו\"מ בגשמיות דוקא אז עי\"ז נק' מהלכי\"ם שיכולים לעלות בעילוי עד אין שיעור למעלה מעלה ממקורם הראשון בחו\"ב כו', וזהו כללות הטעם שע\"י ירידה זו דנשמה בעוה\"ז בגוף גשמי בקיום התו\"מ בגשמיות תבא ותגיע למדרגה גבוה יותר משרשה הראשון בהיותה צרורה בצרור החיים באוצר הנשמות בעמדה לפני ה' ממש כנ\"ל וד\"ל.\n<b>אמנם</b> להבין ביאור כ\"ז למה ע\"י ירידה זו דוקא תעלה הנשמה כ\"כ למעלה כו', הנה יש להקדים תחלה ביאור ענין מה שאנו או' נורא תהלות אדון הנפלאות<sup data-n=\"7947\">43</sup> המחדש בטובו כו', דמונה כאן ג' מדרגות נורא תהלות ואדון הנפלאות ואח\"כ מחדש כו', מה שייכות יש לזה עם זה דמשמע דזהו סדרן דוקא דמבחי' נורא תהלות נמשך להיות אדון הנפלאות וכמ\"ש נורא תהלות ואח\"כ עושה פלא<sup data-n=\"7948\">44</sup> כו', ואח\"ז דוקא מחדש בטובו כו' דהא בהא תליא וד\"ל. וביאור כ\"ז הנה תחלה יש להבין מה שא' מחדש בטובו כו' דזהו בבחי' שם אלקים שהוא בבחי' ממכ\"ע שנק' כח הפועל בנפעל<sup data-n=\"7949\">45</sup> כמו בראשית ברא אלקים<sup data-n=\"7950\">46</sup> וכמו אד' בם<sup data-n=\"7951\">47</sup> כו', ואדון הנפלאות הוא בחי' סוכ\"ע בכלל. והענין הוא כידוע בענין התחדשות הבריאה מאין ליש בכלל ובפרט שזהו מצד ירידת האור והשפע האלקי' דרך עילה ועלול<sup data-n=\"7952\">48</sup> דוקא, דהיינו מבחי' האחרונה שבעילה נמשך שרש התהוות העלול שלמטה הימנו והוא מבחי' אותיות שבעליון לבד שהוא בחי'",[["7942","38","<b>הקו\"ח שנק' קו המדה</b>: נסמן לעיל פ' שמות מא, א."],["7943","39","<b>מי מדד בשעלו</b>: ישעי' מ, יב."],["7944","40","<b>משחתא</b>: ראה זהר בראשית יח, ב. פקודי רלג, א. ביאוה\"ז פקודי נז, ד."],["7945","41","<b>מתקלא</b>: נסמן לעיל יג, ג."],["7946","42","<b>אי\"ה סופ\"ר אי\"ה שוקל</b>: ישעי' לג, יח. ראה מאמרי אדה\"א נ\"ך ע' עא ואילך."],["7947","43","<b>נורא תהלות אדון הנפלאות</b>: ברכת יוצר."],["7948","44","<b>נורא תהלות. . עושה פלא</b>: בשלח טו, יא."],["7949","45","<b>כח הפועל בנפעל</b>: נסמן לעיל פ' וארא עה, א."],["7950","46","<b>בראשית ברא אלקים</b>: בראשית א, א."],["7951","47","<b>אד' בם</b>: תהלים סח, יח. ראה גם מאמרי אדה\"א שמות ח\"ב ע' תקעג. וש\"נ. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300670107\" data-slug=\"torat-chaim\" data-id=\"2300670107\">תו\"ח בראשית לה, א</a> ובהערה 10."],["7952","48","<b>עילה ועלול</b>: ב<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381108\" data-slug=\"likkutei-torah\" data-id=\"4001381108\">לקו\"ת ברכה צה, ב</a>: הנזכר בספרים. ראה רמב\"ם הל' יסוה\"ת פ\"ב, ה\"ו."]]]]});
